window.__D("text/zohar/c010",{"p":[[9520011415,"<p>רִבִּי יְהוּדָה וְרִבִּי יוֹסֵי אִעָרְעוּ בִּכְפַר חָנָן. עַד דְּהֲווּ יָתְבֵי בֵּי אוּשְׁפִּיזַיְיהוּ, אֲתָא חַד בַּר נָשׁ וְחַד מָטוּלָא דְחַמְרָא קַמֵיהּ וְעָאל בְּבֵיתָא. אַדְּהָכִי, אָמַר רִבִּי יְהוּדָה לְרִבִּי יוֹסֵי, הָא תָּנִינָן, דְּדָוִד מַלְכָּא הֲוָה מִתְנַמְנֵם כְּסוּס, וְשֵׁינְתֵיהּ זְעֵיר, הֵיךְ הֲוָה קָם בְּפַלְגּוּת לֵילְיָא. הַאי שִׁעוּרָא זְעֵיר אִיהוּ וְלָא הֲוָה אִתְעַר אֲפִילּוּ בִּתְלָתוּת לֵילְיָא.</p>\n<p>אָמַר לֵיהּ, בְּשַׁעְתָּא דְּעָאל לֵילְיָא, הֲוָה יָתִיב עִם כָּל רַבְרְבֵי בֵיתֵיהּ וְדָאִין דִּינָא, וְעָסִיק בְּמִלֵּי דְאוֹרַיְיתָא. וּלְבָתַר הֲוָה נָאִים שֵׁינְתֵיהּ עַד פַּלְגוּת לֵילְיָא, וְקָם בְּפַלְגוּת לֵילְיָא וְאִתְעַר, וְאִשְׁתְּדָּל בְּפוּלְחָנָא דְמָארֵיהּ, בְּשִׁירִין וְתוּשְׁבְּחָן.</p>\n<p>אַדְהָכִי אָמַר <Nonei></i>הַהוּא בַּר נָשׁ, וְכִי הַאי מִלָּה דְקָאַמְרִיתּוּ, הָכִי הוּא. רָזָא דְמִלָּה הָכָא, דְּהָא דָוִד מַלְכָּא חַי וְקַיָּים לְעָלַם וּלְעָלְמֵי עָלְמִין. וְדָוִד מַלְכָּא הֲוָה נָטִיר כָּל יוֹמוֹי דְּלָא יִטְעַם טַעַם מִיתָה. בְּגִין דְּשֵׁינְתָא חַד מִשִּׁתִּין בְּמִיתָה אִיהוּ. וְדָוִד בְּגִין דּוּכְתֵּיהּ דְּאִיהוּ חַי, לָא הֲוָה נָאִים אֶלָּא שִׁיתִּין נִשְׁמֵי. דְּעַד שִׁתִּין נִשְׁמֵי חָסֵר חַד, אִיהוּ חַי. מִתַּמָּן וּלְהָלְאָה, טָעִים בַּר נָשׁ טַעְמָא דְמוֹתָא, וְשַׁלִּיט בֵּיהּ סִטְרָא דְרוּחַ מְסָאֲבָא.</p>\n<p>וְדָא הֲוָה נָטִיר דָּוִד מַלְכָּא, דְּלָא יִטְעַם טַעְמָא דְמוֹתָא, וְשַׁלִּיט (ס\"א דלא ישליט) בֵּיהּ סִטְרָא דְרוּחָא אָחֳרָא, בְּגִין דְּשִׁתִּין נִשְׁמֵי חָסֵר חַד, אִיהוּ רָזָא דְחַיִּים דִּלְעֵילָא. עַד שִׁתִּין נִשְׁמֵי, דְּאִינוּן שִׁתִּין (ד\"א ל\"ג חסר חד נשמי) נִשְׁמֵי עִלָּאִין, וְאִילֵין רָזָא דִלְהוֹן, דְּתַלְיָין בְּהוֹן חַיֵּי. וּמִכָּאן וּלְתַתָּא, רָזָא דְמוֹתָא הוּא.</p>\n<p>וְעַל דָּא, דָּוִד מַלְכָּא הֲוָה מְשַׁעֵר שִׁעוּרָא דְלֵילְיָא, בְּגִין דְּיִתְקַיֵּים בַּחַיִּים, דְּלָא יִשְׁלוֹט בֵּיהּ טַעְמָא דְמוֹתָא. וְכַד אִתְפְּלִיג לֵילְיָא, הֲוָה דָּוִד מִתְקַיֵּים בְּאַתְרֵיהּ. בְּגִין דְּכַד אִתְעַר פַּלְגוּ לֵילְיָא וְכִתְרָא קַדִּישָׁא אִתְעַר, בָּעָא דְלָא לְאַשְׁכָּחָא לֵיהּ לְדָוִד מִתְקַשַּׁר בְּאֲתַר אָחֳרָא, בְּאֲתַר דְּמוֹתָא.</p>\n<p>בְּגִין דְּכַד אִתְפְּלִיג לֵילְיָא וּקְדוּשָּׁה עִלָּאָה אִתְעַר, וּבַר נָשׁ דְּנָאִים בְּעַרְסֵיהּ וְלָא אִתְעַר לְאַשְׁגָּחָא בִּיקָרָא דְמָארֵיהּ. הָא אִיהוּ אִתְקַשַּׁר בְּרָזָא דְמוֹתָא וּמִתְדַּבַּק בְּאֲתַר אָחֳרָא, וְעַל דָּא דָּוִד מַלְכָּא הֲוָה קָאִים לְאַשְׁגָּחָא בִּיקָרָא דְמָארֵיהּ תָּדִיר. חַי לְגַבֵּי חַי, וְלָא נָאִים בְּשֵׁינְתָא לְטָעֲמָא טַעְמָא דְמוֹתָא. וּבְגִין כָּךְ, הֲוָה מִתְנַמְנֵם כְּסוּס שִׁתִּין נִשְׁמֵי, וְלָא בִּשְׁלִימוּ.</p>\n<p>אָתוּ רִבִּי יְהוּדָה וְרִבִּי יוֹסֵי וּנְשָׁקוּהָ, אָמְרוּ לֵיהּ, מַה שְּׁמָךְ. אָמַר לְהוֹן, חִזְקִיָּה. אָמְרוּ לֵיהּ, יִתְיַישֵּׁר חֵילָךְ וְיִתְתַּקַּף אוֹרַיְיתָךְ. יְתִיבוּ. אָמַר רִבִּי יְהוּדָה, הוֹאִיל וְשָׁרִית, אֵימָא לָן מֵהַנֵּי רָזִין עִלָּאִין דְּקָאֲמַרְתְּ.</p>\n<p>פָּתַח וְאָמַר, (משלי ג׳:י״ט) ה' בְּחָכְמָה יָסַד אֶרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, חָמָא דְלָא יָכִיל לְאִתְקָיְימָא, עַד דְּבָרָא אוֹרַיְיתָא. בְּגִין דְּמִנָּהּ נָפְקִין כָּל נִמּוּסִין עִלָּאִין וְתַתָּאִין, וּבָהּ קָיְימֵי עִלָּאֵי וְתַתָּאֵי. הֲדָא הוּא דִכְתִיב, ה' בְּחָכְמָה יָסַד אָרֶץ כּוֹנִן שָׁמַיִם בִּתְבוּנָה. דְּהָא בְּחָכְמָה קָיְימִין כָּל קִיּוּמִין דְּעַלְמָא, וְכֻלְּהוּ נָפְקֵי מִגַּוָּהּ.</p>\n<p>דָּבָר אַחֵר ה' בְּחָכְמָה יָסַד אֶרֶץ, עַלְמָא עִלָּאָה לָא אִתְבְּרֵי אֶלָּא מִגּוֹ חָכְמָה. וְעַלְמָא תַּתָּאָה לָא אִתְבְּרֵי אֶלָּא מִגּוֹ חָכְמָה תַּתָּאָה. וְכֻלְּהוּ נָפְקָן מִגּוֹ חָכְמָה עִלָּאָה וּמִגּוֹ חָכְמָה תַּתָּאָה. כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. כּוֹנֵן, מַאי כּוֹנֵן. אֶלָּא, כּוֹנֵן כָּל יוֹמָא וְיוֹמָא וְלָא פָּסִיק, וְלָא אִתְתַּקַּן בְּזִמְנָא חָדָא, אֶלָּא בְּכָל יוֹמָא וְיוֹמָא אַתְקִין לֵיהּ.</p>\n<p>וְהַיְינוּ רָזָא דִּכְתִיב, (איוב ט״ו:ט״ו) וְשָׁמַיִם לֹא זַכּוּ בְעֵינָיו. וְכִי סַלְקָא דַעְתָּךְ, דִּגְרִיעוּתָא אִיהוּ מִשָּׁמַיִם, אֶלָּא חֲשִׁיבוּ מִשָּׁמַיִם אִיהוּ, בְּגִין חֲבִיבוּ וּרְעוּ סַגְיָא, דְּקוּדְשָׁא בְּרִיךְ הוּא רָעֵי בְּהוּ, וַחֲבִיבוּתַיְהוּ לְגַבֵּיהּ. דְּהָא אַף עַל גַּב דְּאִיהוּ מַתְקִין לוֹן כָּל יוֹמָא וְיוֹמָא, לָא דָמֵי בְּעֵינוֹי דְּאִינוּן מִתְתַּקְנָן כְּדְקָא יְאוּת. בְּגִין דִּרְחִימוּתָא דִלְהוֹן לְגַבֵּיהּ, וּרְעוּתֵיהּ לְאַנְהָרָא לוֹן תָּדִיר בְּלָא פְּסִיקוּ. דְּהָא עַלְמָא דְאָתֵי אַפִּיק נְהוֹרִין זְהִירִין כָּל יוֹמָא וְיוֹמָא תָּדִיר בְּלָא פְּסִיקוּ, בְּגִין לְאַנְהָרָא לוֹן תָּדִיר. וְעַל דָּא לא זַכּוּ בְּעֵינָיו. לא זַכּוּ בִּלְחוֹדוֹי לָא כְּתִיב, אֶלָּא לא זַכּוּ בְעֵינָיו. וּבְגִין כָּךְ, כּוֹנֵן שָׁמַיִם בִּתְבוּנָה.</p>\n<p>מַאן שָׁמַיִם. דָּא הוּא רָזָא דְּאֲבָהָן, וְרָזָא דְּאֲבָהָן דָּא הוּא יַעֲקֹב דְּאִיהוּ כְּלָלָא דִלְהוֹן. בְּגִין דְּיַעֲקֹב תּוּשְׁבַּחְתָּא דְּאֲבָהָן אִיהוּ, וְאִיהוּ קָיְימָא לְאַנְהָרָא עַל עַלְמָא.</p>\n<p>וּבְגִין דְּאִיהוּ אִסְתָּלַּק גּוֹ עַלְמָא דְאָתֵי, נָפַק מִנֵּיהּ עֲנָפָא חָדָא שַׁפִּירָא בְּחֵיזוּ, וְכָל נְהוֹרִין מִינֵיהּ נָפְקִין. וְכָל שָׂבְעָא וּמְשַׁח רְבוּ לְאַנְהָרָא לְאַרְעָא, וּמַאן אִיהוּ. דָּא יוֹסֵף הַצַּדִּיק, דְּאִיהוּ יָהִיב שָׂבְעָא לְכָל עַלְמָא, וְעַלְמָא מִנֵּיהּ אִתְּזָן. וּבְגִין כָּךְ, קוּדְשָׁא בְּרִיךְ הוּא כָּל מַה דְּעָבַד בְּעַלְמָא, כֹּלָּא אִיהוּ בְּרָזָא עִלָּאָה, וְכֹלָּא כְּדְקָא חָזֵי.</p>\n<p>אַדְהָכִי אֲתָא רִבִּי אֶלְעָזָר, כֵּיוָן דְּחָמָא לוֹן אָמַר, וַדַּאי שְׁכִינְתָּא הָכָא. בְּמַאי עַסְקִיתוּ. אָמְרוּ לֵיהּ <Nonei></i>כָּל עוֹבָדָא. אָמַר, וַדַּאי שַׁפִּיר קָאֲמַר. אֲבָל אִינוּן שִׁתִּין נִשְׁמֵי, וַדַּאי שִׁתִּין נִשְׁמֵי אִינוּן דְּחַיִּין, בֵּין לְעֵילָא בֵּין לְתַתָּא. מִכָּאן וּלְהָלְאָה, אִיכָּא שִׁתִּין נִשְׁמִין אָחֳרָנִין, דְּאִינוּן כֻּלְּהוּ מִסִּטְרָא דְמוֹתָא, וְדַרְגָּא דְמוֹתָא עֲלַיְיהוּ, וְאִקְרוּן דּוּרְמִיטָא, וְכֻלְּהוּ טַעֲמָא דְמוֹתָא.</p>\n<p>וּבְגִין כָּךְ דָּוִד מַלְכָּא הֲוָה אִיהוּ מִתְדְּבַּק בְּאִינוּן שִׁתִּין נִשְׁמִין דְּחַיִּין, וּמִתַּמָּן וּלְהָלְאָה לָא נָאִים כְּלַל. הֲדָא הוּא דִכְתִיב, (תהילים קל״ב:ד׳) אִם אֶתֵּן שְׁנָת לְעֵינָי לְעַפְעַפַּי תְּנוּמָה. וְעַל דָּא שַׁפִּיר קָאֲמַר, בְּגִין דְּיָקוּם דָּוִד חַי, בְּסִטְרָא דְחַי וְלָא בְּסִטְרָא דְמוֹתָא. יָתְבוּ כֻּלְּהוּ וְאִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא וְאִתְחַבָּרוּ כְּחֲדָא.</p>\n<p>פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (תהילים פ״ח:ב׳) ה' אֱלֹקֵי יְשׁוּעָתִי יוֹם צָעַקְתִּי בַלַּיְלָה נֶגְדֶּךָ. תָּא חֲזֵי, דָּוִד מַלְכָּא הֲוָה קָם בְּפַלְגּוּת לֵילְיָא, וְאִשְׁתְּדָּל בְּאוֹרַיְיתָא בְּשִׁירִין וְתוּשְׁבְּחָן, לְחֶדְוָה דְמַלְכָּא וּמַטְרוֹנִיתָא. וְדָא הֲוָה חֶדְוָה דִמְהֵימְנוּתָא בְּאַרְעָא. בְּגִין דְּהַאי אִיהוּ שְׁבָחָא דִמְהֵימְנוּתָא דְּאִתְחֲזֵי בְּאַרְעָא.</p>\n<p>דְּהָא לְעֵילָא פָּתְחֵי בְּחֶדְוָה שִׁירָתָא כַּמָּה מַלְאָכִין עִלָּאִין, בְּכַמָּה זִינִין דְּקָא מְשַׁבְּחָן בְּלֵילְיָא בְּכָל סִטְרִין. כְּהַאי גַּוְונָא לְתַתָּא בְּאַרְעָא, מַאן דִּמְשַׁבַּח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא בְּלֵילְיָא, רָעֵי בֵּיהּ (בעי) קוּדְשָׁא בְּרִיךְ הוּא. וְכָל אִינוּן מַלְאָכִין קַדִּישִׁין דְּקָא מְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, כֻּלְּהוּ צַיְיתִין לְהַהוּא דְקָא מְשַׁבַּח לֵיהּ בְּלֵילְיָא בְּאַרְעָא. דְּהַאי תּוּשְׁבַּחְתָּא אִיהוּ בִּשְׁלִימוּ, לְסַלְקָא יְקָרֵי דְּקוּדְשָׁא בְּרִיךְ הוּא מִתַּתָּא, וּלְזַמְּרָא בְּחֶדְוָה דְּיִחוּדָא.</p>\n<p>תָּא חֲזֵי, דָּוִד מַלְכָּא כָּתַב, ה' אֱלֹהֵי יְשׁוּעָתִי וְגו', ה' אֱלהֵי יְשׁוּעָתִי, אֵימָתַי אִיהוּ יְשׁוּעָתִי. בְּהַהוּא יוֹמָא דְאַקְדֵּמִית תּוּשְׁבַּחְתָּא בְּלֵילְיָא לְגַבָּךְ, כְּדֵין אִיהוּ יְשׁוּעָתִי בִּימָמָא.</p>\n<p>וְתָּא חֲזֵי, דְּהָא בְּלֵילְיָא, מַאן דִּמְשַׁבַּח לְמָארֵיהּ בְּתוּשְׁבַּחְתָּא דְאוֹרַיְיתָא, כְּדֵין אַתְקַף בִּתְקִיפוּ בִּיְמָמָא בְּסִטְרָא דִּימִינָא. דְּהָא חוּטָא חַד נַפְקָא מִסִּטְרָא דִּימִינָא, וּכְדֵין אִתְמָשַּׁךְ עֲלֵיהּ וְאִתְתַּקַּף בֵּיהּ. וְעַל דָּא אָמַר, ה' אֱלֹהֵי יְשׁוּעָתִי יוֹם צָעַקְתִּי וְגו'.</p>\n<p>וּבְגִין כָּךְ אָמַר, (תהילים קט״ו:י״ז) לא הַמֵּתִים יְהַלְּלוּ יָהּ. לא הַמֵּתִים, בְּגִין דְּאִצְטְרִיךְ לְשַׁבְּחָא חַי לְחַי. וּמֵת לְחַי לָאו הָכִי, דִּכְתִיב לֹא הַמֵּתִים יְהַלְּלוּ יָהּ. וַאֲנַחְנוּ נְבָרֵךְ יָהּ, דְּהָא אֲנַן חַיִּין וְלֵית לָן חוּלָקָא בְּסִטְרָא דְמוֹתָא כְּלַל. חִזְקִיָּהוּ אָמַר, (ישעיהו ל״ח:י״ט) חַי חַי הוּא יוֹדֶךָ כָּמוֹנִי, בְּגִין דְּחַי אִתְקְרַב לְחַי. דָּוִד מַלְכָּא אִיהוּ חַי, וְקוּרְבָא דִילֵיהּ לְחַי הָעוֹלָמִים. וּמַאן דְּאִתְקְרִיב לְגַבֵּיהּ, אִיהוּ חַי. דִּכְתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. וּכְתִיב, (שמואל ב כ״ג:כ׳) וּבְנָיָהוּ בֶּן יְהוֹיָדָע בֶּן אִישׁ חַי רַב פְּעָלִים מִקַּבְצְאֵל.</p>"],[9520011416,"<p>פָּתַח הַהוּא יוּדָאי אֲבַתְרֵיהּ וְאָמַר, (דברים ח׳:י׳) וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלקֶיךָ. וְכִי לָא מְבָרְכִינָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא עַד לָא נִיכוּל, וְהָא אִית לָן לְאַקְדּוּמֵי בְּצַפְרָא וּלְסִדּוּרֵי שְׁבָחָא דִילֵיהּ (דמאריה) כְּדְקָא יְאוּת, וּלְבָרְכָא בִּשְׁמֵיהּ עַד לָא יְבָרֵךְ לְאַחֲרָא בְּעַלְמָא. וּכְתִיב (ויקרא כט) לא תֹאכֵלוּ עַל הַדָּם, אָסוּר לֵיהּ לְמֵיכַל עַד לָא יְבָרֵךְ לְמָארֵיהּ. וְהַשְׁתָּא כְּתִיב וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ.</p>\n<p>אֶלָּא, דָּא בִּרְכָתָא דִצְלוֹתָא דְּיִחוּדָא, וְדָא בִּרְכָתָא דִּמְזוֹנָא. לְאַחֲזָאָה לְגַבֵּי דַרְגָּא דִמְהֵימְנוּתָא, שָׂבָע כְּדְקָא יָאוֹת. וּכְדֵין בְּעֵי לְבָרְכָא לֵיהּ כְּדְקָא יְאוּת, דְּהַהוּא דַרְגָּא דִמְהֵימְנוּתָא יִתְרַוֵּי וִיבָרֵךְ, וְיִתְמַלֵּא חֵידוּ מֵחַיִּין דִּלְעֵילָא כְּמָה דְאִצְטְרִיךְ, בְּגִין לְמֵיהַב לָן מְזוֹנֵי.</p>\n<p>דְּהָא קָשִׁין מְזוֹנָא דְבַר נָשׁ קַמֵי קוּדְשָׁא בְּרִיךְ הוּא, כִּקְרִיעַת יַם סוּף. מַאי טַעְמָא. בְּגִין דִּמְזוֹנָא דְעַלְמָא דִלְעֵילָא הוּא, דִּתְנַן בָּנֵי חַיֵּי וּמְזוֹנֵי וְכוּ', וּבְגִין כָּךְ קַשְׁיָין קַמֵּיהּ מְזוֹנֵי דְעַלְמָא. דְּהָא בְּמַזָּלָא תַּלְיָא מִילְתָא. דְּמִנֵּיהּ נָפְקֵי מְזוֹנֵי וְחַיֵּי וּבָנֵי. וּבְגִין כָּךְ קָשִׁין קַמֵּיהּ מְזוֹנֵי דְעַלְמָא, דְּהָא לָאו בִּרְשׁוּתֵיהּ קָיְימָא, עַד דְּיִתְבָּרֵךְ אִיהוּ.</p>\n<p>כְּגַוְונָא דָא זִיִוְגִּין דְּעַלְמָא קָשִׁין קַמֵּיהּ, וְכֹלָּא בְּגִין דְּרָקִיעַ וִילוֹן לָא מְשַׁמֵּשׁ כְּלוּם. וְכָל שֶׁכֵּן אִלֵּין מִלִּין דְּקָיְימִין לְעֵילָא בְּאֲתַר אָחֳרָא, וְעַל דָּא אִצְטְרִיךְ לְאִתְבָּרְכָא.</p>\n<p>תָּא חֲזֵי, כָּל זִווּגִין דְּעַלְמָא קָשִׁין קַמֵּיהּ הַאי דַרְגָא, בְּגִין דְּכַד הַאי זִוּוּגָא קַדִּישָׁא אִשְׁתַּכַּח, כָּל <Nonei></i>נִשְׁמָתִין נָפְקִין מִגּוֹ הַאי מַזָּלָא לְעֵילָא, דְּאִיהוּ הַהוּא נָהָר דְּנָגִיד וְנָפִיק. וְכַד תִּיאוּבְתָּא אִשְׁתַּכַּח מִלְרַע לְעֵילָא, כְּדֵין פָּרְחִין נִשְׁמָתִין, וְאִתְיְיהִיבוּ כֻּלְּהוּ כְּלִילָן דְּכַר וְנוּקְבָא כְּחֲדָא בְּהַאי דַרְגָּא. וּלְבָתַר אִיהוּ פָּרִישׁ לוֹן כָּל חַד וְחַד לְאַתְרֵיהּ כְּדְקָא חָזֵי לֵיהּ. וּלְבָתַר קָשִׁין קַמֵּי הַאי דַרְגָּא לְחַבְּרָא לוֹן כְּקַדְמִיתָא, בְּגִין דְּלָא מִתְחַבְּרָן, בַּר כְּאִינוּן אָרְחֵי דְבַּר נָשׁ, וְכֹלָּא לְעֵילָא תַּלְיָין.</p>\n<p>וְעַל דָּא קָשִׁין קַמֵּיהּ כִּקְרִיעַת יַם סוּף. דְּהָא קְרִיעַת יַמָּא לְאִתְפַּתְּחָא בֵּיהּ שְׁבִילִין, לְעֵילָא אִיהוּ. וּכְמָה דְּמִתְפַּתְּחִין שְׁבִילִין וְאוֹרְחִין בֵּיהּ, הָכִי אִתְבַּקַּע וְאִתְפַּתַּח.</p>\n<p>וּבְגִין כָּךְ כֹּלָּא תַּלְיָא לְעֵילָא, וּבְעִינָן לְבָרְכָא לֵיהּ, וּלְמֵיהַב לֵיהּ תּוּקְפָא מִתַּתָּא, בְּגִין דְּיִתְבָּרְכָא מִלְּעֵילָא, וְיִתְתַּקַּף כְּדְקָא חָזֵי. וְעַל דָּא כְּתִיב, וּבֵרַכְתָּ אֶת ה', אֶת דַּיְיקָא.</p>\n<p>וּלְגַבֵּי הַאי אֲתַר, אִצְטְרִיךְ לְאַחֲזָאָה קַמֵּיהּ שָׂבְעָא וּנְהִירוּ דְאַנְפִּין. וּלְגַבֵּי סִטְרָא אָחֳרָא, בְּזִמְנָא דְאִיהִי שָׁלְטָא בְּעַלְמָא, בְּעֵי לְאַחֲזָאָה קַמֵּיהּ כַּפְנָא. דְּהַהוּא דַרְגָּא רָעָב אִיהוּ, וְאִתְחֲזֵי לְאַחֲזָאָה קַמֵּיהּ כַּפְנָא וְלָא שׂוֹבְעָא, הוֹאִיל וְשָׂבָע לָא שָׁלְטָא בְּעַלְמָא. וְעַל דָּא, וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלֹקֶיךָ. אָמַר רִבִּי אֶלְעָזָר, הָכִי הוּא וַדַּאי, וְהָכִי אִצְטְרִיךְ.</p>\n<p>אָמַר רִבִּי יְהוּדָה, זַכָּאִין אִינוּן צַדִּיקַיָּיא דְּקוּרְבָא דִּלְהוֹן אִיהוּ שְׁלָמָא בְּעַלְמָא. בְּגִין דְּיָדְעֵי לְיַחֲדָא יִחוּדָא, וּמְקַרְבֵי קוּרְבָא לְאַסְגָּאָה שְׁלָמָא בְּעַלְמָא. דְּהָא יוֹסֵף וִיהוּדָה עַד לָא אִתְקְרִיבוּ דָּא עִם דָּא, לָא הֲוָה שְׁלָמָא. כֵּיוָן דְּאִתְקְרִיבוּ יוֹסֵף וִיהוּדָה כְּחֲדָא, כְּדֵין אַסְגִּיאוּ שְׁלָמָא בְּעַלְמָא. וְחֵידוּ אִתּוֹסַף לְעֵילָא וְתַתָּא, כְּמָה דְּקוּרְבָא דִּיהוּדָה וְיוֹסֵף וְכֻלְּהוּ שִׁבְטִין אִשְׁתַּכָּחוּ כְּחֲדָא בֵּיהּ בְּיוֹסֵף. וְהַהוּא קוּרְבָא אַסְגֵּי שְׁלָמָא בְּעַלְמָא, כְּמָה דְאוֹקִימְנָא. דִּכְתִיב, וַיִּגַּשׁ אֵלָיו יְהוּדָה:</p>"],[9520011417,"<p>וְלֹא יָכוֹל יוֹסֵף לְהִתְאַפֵּק לְכָל הַנִּצָּבִים עָלָיו וְגו', רִבִּי חִיָּיא פָּתַח וְאָמַר, (תהילים קי״ב:ט׳) פִּזַּר נָתַן לָאֶבְיוֹנִים צִדְקָתוֹ עוֹמֶדֶת לָעַד קַרְנוֹ תָּרוּם בְּכָבוֹד. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא בָּרָא עַלְמָא, וְאַשְׁלִיט עֲלֵיהּ לָאָדָם, דִּיהֵא מַלְכָּא עַל כֹּלָּא.</p>\n<p>וְהַאי בַּר נָשׁ, מִתְפָּרְשָׁן מִנֵּיהּ בְּעַלְמָא כַּמָּה זִינִין. מִנְּהוֹן צַדִּיקַיָּא וּמִנְּהוֹן רַשִּׁיעַיָא. מִנְּהוֹן טִפְּשִׁין וּמִנְּהוֹן חַכִּימִין. וְכֻלְּהוּ אִתְקָיְימוּ בְּעַלְמָא, עֲתִירִין וּמִסְכֵּנִין. וְכֻלְּהוּ בְּגִין לְמִזְכֵּי אִלֵּין בְּאִלֵּין, לְמִזְכֵּי צַדִּיקַיָא עִם רַשִּׁיעַיָא, לְמִזְכֵּי חַכִּימִין עִם טִפְּשִׁין, לְמִזְכֵּי עֲתִירִין עִם מִסְכֵּנִין. דְּהָא בְּגִין כָּךְ, זָכֵי בַּר נָשׁ לְחַיֵּי עָלְמָא, וְאִתְקַשַּׁר בְּאִילָנָא דְחַיֵּי. וְלָא עוֹד, אֶלָּא דְּהָא צְדָקָה דְּאִיהוּ עָבִיד, קָאִים לְעָלְמִין. דִּכְתִיב וְצִדְקָתוֹ עוֹמֶדֶת לָעַד.</p>\n<p>פִּזַּר נָתַן לָאֶבְיוֹנִים. רִבִּי אֶלְעָזָר אָמַר, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, קָאִים לֵיהּ עַל סַמְכָא חַד, וְצַדִּיק שְׁמֵיהּ, וְהַאי צַדִּיק אִיהוּ קִיּוּמָא דְעַלְמָא, וְדָא אִיהוּ דְאַשְׁקֵי, וְזָן לְכֹלָּא. דִּכְתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֶד וְהָיָה לְאַרְבָּעָה רָאשִׁים.</p>\n<p>וּמִשָּׁם יִפָּרֶד, מַהוּ יִפָּרֶד. אֶלָּא, הַהוּא מְזוֹנָא וּמַשְׁקַיָא דְּהַהוּא נָהָר, נָטִיל גִּנְתָא כֹּלָּא, וּלְבָתַר אִתְבַּדַּר הַהוּא מַשְׁקַיָא לְד' סִטְרִין דְּעַלְמָא. וְכַמָּה אִינוּן דִּמְצַפָּאן לְאִתְשַׁקְיָיא וּלְאִתְּזְנָא מִתַּמָּן. כְּמָא דְאַתְּ אָמֵר, (תהילים קמ״ה:ט״ו) עֵינִי כֹל אֵלֶיךָ יְשַׂבֵּרוּ וְאַתָּה נוֹתֵן לָהֶם אֶת אָכְלָם בְּעִתּוֹ. וּבְגִין כָּךְ פִּזַּר נָתַן לָאֶבְיוֹנִים, דָּא צַדִּיק. צִדְקָתוֹ עוֹמֶדֶת לָעַד, דָּא כְּנֶסֶת יִשְׂרָאֵל. דִּבְגִין כָּךְ, אִיהִי קָיְימָא בְּרָזָא דִשְׁלָם, בְּקִיּוּמָא שְׁלִים. רָשָׁע יִרְאֶה וְכָעַס, דָּא מַלְכוּת עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת.</p>\n<p>תָּא חֲזֵי, מַלְכוּת שָׁמַיִם, אִיהִי בֵּי מַקְדְּשָׁא. לְקָיְימָא כָּל מִסְכְּנֵי בְּגוֹ צִלָּא דְּשֵׁרוּתָא דִשְׁכִינְתָּא. וְצַדִּיק דָּא אִיהוּ אִקְרֵי גַּבָּאי צְדָקָה, לְמֵיחַן וּלְמֵיזַן לְכֹלָּא. דִּכְתִיב פִּזַּר נָתַן לָאֶבְיוֹנִים. בְּגִין כָּךְ, גַּבָּאֵי צְדָקָה נָטְלֵי אַגְרָא לָקֳבֵיל כֻּלְּהוּ דְּיַהֲבֵי צְדָקָה.</p>\n<p>תָּא חֲזֵי, וְלֹא יָכוֹל יוֹסֵף לְהִתְאַפֵּק לְכָל הַנִּצָּבִים, אִלֵּין אִינוּן כָּל דְּקָיְימֵי לְאִתְּזָנָא וּלְאִתְשַׁקְיָיא מִנֵּיהּ. וְלֹא עָמַד אִישׁ אִתּוֹ <Nonei></i>בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו. אִתּוֹ, דָּא כְּנֶסֶת יִשְׂרָאֵל. אֶחָיו, אִלֵּין שְׁאָר רְתִיכִין חֲיָילִין, דִּכְתִיב בְּהוּ (תהילים קכ״ב:ח׳) לְמַעַן אֲחַי וְרֵעָי. דָּבָר אַחֵר, וְלֹא עָמַד אִישׁ אִתּוֹ. בְּזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְאִזְדַּוְּוגָא בִּכְּנֶסֶת יִשְׂרָאֵל. בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו, בְּזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה מִתְחַבֵּר בְּהוּ בְּיִשְׂרָאֵל, בְּגִין דְּאִינוּן נָטְלֵי בִּלְחוֹדַיְיהוּ, וְלָא חִבּוּרָא דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת בַּהֲדַיְיהוּ. בְּגִין כָּךְ (במדבר כ״ט:ל״ה) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. דְּהָא בְּזִמְנָא דָא, אִיהוּ קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, בְּחִבּוּרָא חָדָא עִם יִשְׂרָאֵל, דִּכְתִיב בְּהוּ אֲחַי וְרֵעָי כְּמָה דְאוּקְמוּהָ.</p>\n<p>רִבִּי יֵיסָא פָּתַח קְרָא, בְּזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא יוֹקִים לָהּ לִכְנֶסֶת יִשְׂרָאֵל מֵעַפְרָא, וְיִבָּעֵי לְאִנָּקְמָא נִקְמָתָא מֵעַמְּמַיָא עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, כְּדֵין כְּתִיב, (ישעיהו ס״ג:ג׳) וּמֵעַמִים אֵין אִישׁ אִתִּי. וּכְתִיב הָכָא, וְלֹא עָמַד אִישׁ אִתּוֹ בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ס״ג:ט׳) וַיְנַטְּלֵם וַיְנַשְּׂאֵם כָּל יְמֵי עוֹלָם.</p>\n<p>וְלֹא יָכוֹל יוֹסֵף לְהִתְאַפֵּק, רִבִּי חִזְקִיָּה פָּתַח וְאָמַר, (תהילים קכ״ג:א׳) שִׁיר הַמַּעֲלוֹת אֵלֶיךָ נָשָׂאתִי אֶת עֵינַי הַיּוֹשְׁבִי בַּשָּׁמָיִם, הַאי קְרָא אוּקְמוּהָ וְאִתְּמָר. אֲבָל תָּא חֲזֵי, אֵלֶיךָ נָשָׂאתִי אֶת עֵינַי, וּכְתִיב, (תהילים קכ״א:א׳) אֶשָּׂא עֵינַי אֶל הֶהָרִים. אֶלָּא, דָּא לְעֵילָא וְדָא לְתַתָּא. אֶשָּׂא עֵינַי אֶל הֶהָרִים, דָּא לְעֵילָא. בְּגִין לְאַמְשָׁכָא בִּרְכָאן מֵעֵילָא לְתַתָּא, מֵאִלֵּין הָרִים עִלָּאִין, לְאַמְשָׁכָא מִנַּיְיהוּ בִּרְכָאן לִכְנֶסֶת יִשְׂרָאֵל דְּאִתְבָּרְכָא מִנַּיְיהוּ. אֵלֶיךָ נָשָׂאתִי אֶת עֵינַי, לְמִצְפֵּי וּלְחַכָּאָה לְאִנּוּן בִּרְכָאן דְּנָחֲתוּ מִתַּמָּן לְתַתָּא.</p>\n<p>הַיּוֹשְׁבִי בַּשָּׁמָיִם, דְּכָל תּוּקְפָהָא וְחֵילָאָה וְקִיּוּמָהָא, אִיהוּ בַּשָּׁמַיִם. בְּגִין דְּכַד יוֹבֵלָא אַפְתַּח מַבּוּעֵי דְּכָל אִינוּן תַּרְעִין, כֻּלְּהוּ קָיְימֵי בַּשָּׁמַיִם. וְכֵיוָן דְּשָׁמַיִם נָטִיל כָּל אִינוּן נְהוֹרִין דְּנָפְקֵי מִיּוֹבֵלָא, כְּדֵין אִיהוּ זָן וְאַשְׁקֵי לָהּ לִכְנֶסֶת יִשְׂרָאֵל עַל יְדָא דְצַדִּיק חַד.</p>\n<p>וְכֵיוָן דְּדָא אִתְעַר לְגַבָּהּ, כַּמָּה אִינוּן דְּקָיְימָן בְּכָל סִטְרִין לְאִתְשַׁקְאָה וּלְאִתְבָּרְכָא מִתַּמָּן. כְּמָא דְאַתְּ אָמֵר, (תהילים ק״ד:כ״א) הַכְּפִירִים שׁוֹאֲגִים לַטֶּרֶף וּלְבַקֵּשׁ מֵאֵל אָכְלָם. וּכְדֵין, אִיהִי סָלְקָא בְּרָזָא דְרָזִין כְּדְקָא חָזֵי (ד\"א ל\"ג ליה), וּמְקַבְּלָא עִדּוּנִין מִבַעֲלָהּ כְּדְקָא יְאוּת, וְכֻלְּהוּ דְּקָיְימִין בְּכָל סִטְרִין עָמְדֵי בִּלְחוֹדַיְיהוּ. כְּמָא דְאַתְּ אָמֵר, וְלֹא עָמַד אִישׁ אִתּוֹ. דִּכְתִיב, וַיִּקְרָא הוֹצִיאוּ כָּל אִישׁ מֵעָלַי, וּלְבָתַר דְּאִיהִי מְקַבְּלָא עִדּוּנִין מִבַּעֲלָהּ, כֻּלְּהוּ אִתְשַׁקְיָין לְבָתַר וְאִתְּזָנוּ. כְּמָא דְאַתְּ אָמֵר, (תהילים ק״ד:י״א) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם.</p>"],[9520011418,"<p>רִבִּי יוֹסֵי פָּתַח קְרָא בְּאֵלִיָּהוּ, דִּכְתִיב, (מלכים א י״ז:כ׳) וַיִּקְרָא אֶל ה' וַיֹּאמַר ה' אֱלהָי הֲגַם עַל הָאַלְמָנָה אֲשֶׁר אֲנִי מִתְגּוֹרֵר עִמָּהּ הֲרֵעוֹתָ לְהָמִית אֶת בְּנָהּ. תָּא חֲזֵי, תְּרֵי הֲווּ דְּקָאָמְרִין מִלִּין לָקֳבֵיל קוּדְשָׁא בְּרִיךְ הוּא, משֶׁה וְאֵלִיָּהוּ. משֶׁה אָמַר, (שמות ה׳:כ״ב) לָמָּה הֲרֵעוֹתָ לָעָם הַזֶּה. וְאֵלִיָּהוּ אָמַר, הֲרֵעוֹתָ לְהָמִית אֶת בְּנָהּ, וְתַרְוַיְיהוּ מִלָּה חָדָא קָאֲמְרוּ.</p>\n<p>מַאי טַעְמָא. אֶלָּא רָזָא אִיהוּ. משֶׁה אָמַר, לָמָּה הֲרֵעוֹתָ, מַאי טַעְמָא. אֶלָּא, בְּגִין דְּאִתְיְהִיב רְשׁוּ לְסִטְרָא אָחֳרָא לְשַׁלְּטָאָה עֲלַיְיהוּ דְיִשְׂרָאֵל, הֲרֵעוֹתָ, יְהַבְתְּ רְשׁוּ לְסִטְרָא אָחֳרָא דְרַע, לְמִשְׁלַט עֲלַיְיהוּ. אֵלִיָּהוּ אָמַר, הֲרֵעוֹתָ יְהַבְתְּ רְשׁוּ לְסִטְרָא דְרַע, לִיטוֹל נִשְׁמָתָא דְּדָא. וְדָא הוּא הֲרֵעוֹתָ, וְכֹלָּא רָזָא חָדָא.</p>\n<p>תָּא חֲזֵי, אֵלִיָּהוּ אָמַר, הֲגַם עַל הָאַלְמָנָה אֲשֶׁר אֲנִי מִתְגּוֹרֵר עִמָּהּ. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ לְאֵלִיָּהוּ, הִנֵּה צִוִּיתִי שָׁם אִשָּׁה אַלְמָנָה לְכַלְכְּלֶךָ. וְכָל מַאן דְּזָן וּמְפַרְנֵס לְמַאן דְּאִצְטְרִיךְ לֵיהּ, וְכָל שֶׁכֵּן בְּיוֹמָא דְכַפְנָא. הָא אִתְאַחִיד בְּאִילָנָא דְחַיֵּי, וְגָרִים לֵיהּ חַיִּים וְלִבְנוֹי, וְהָא אוֹקִימְנָא. וְהַשְׁתָּא אֵלִיָּהוּ אָמַר, כָּל מַאן דְּקִיֵּים נַפְשָׁא בְּעַלְמָא, זָכֵי לֵיהּ חַיִּים וְזָכֵי לְאִתְאַחֲדָא בְּאִילָנָא דְחַיֵּי. וְהַשְׁתָּא שָׁלְטָא אִילָנָא דְמוֹתָא סִטְרָא דְרַע עַל הָאַלְמָנָה דְּאַנְתְּ פְּקַדְתְּ לְמֵיזַן לִי. בְּגִין כָּךְ הֲרֵעוֹתָ (למה הרעות).</p>\n<p>וְאִי תֵימָא דְּרַע לָא אִתְעֲבִיד לְבַר נָשׁ מֵעִם קוּדְשָׁא בְּרִיךְ הוּא. תָּא חֲזֵי, בְּזִמְנָא דְבַר נָשׁ אָזִיל לִימִינָא, נְטִירוּ דְקוּדְשָׁא בְּרִיךְ הוּא תָּדִיר לְגַבֵּיהּ, וְלָא יָכִיל סִטְרָא אָחֳרָא לְשַׁלְטָאָה עֲלֵיהּ. וְהַאי רָע אִתְכַּפְיָא קַמֵּיהּ, וְלָא יָכִיל לְשַׁלְּטָאָה. וְכֵיוָן דִּנְטִירָא דְקוּדְשָׁא בְּרִיךְ הוּא אִתְעַבְרָא מִנֵּיהּ, בְּגִין <Nonei></i>דְּאִיהוּ אִתְדָּבַּק בְּרָע, כְּדֵין הַהוּא רָע, כֵּיוָן דְּחָמֵי דְּלָאו עִמֵּיהּ נְטִירוּ, כְּדֵין שַׁלִּיט עֲלֵיהּ, וְאָתֵי לְשֵׁיצָאָה לֵיהּ, וּכְדֵין אִתְיְהִיב לֵיהּ רְשׁוּ, וְנָטִיל נִשְׁמָתֵיהּ.</p>\n<p>משֶׁה אָמַר לָמָּה הֲרֵעוֹתָ, דְּאִתְיְהִיב לֵיהּ רְשׁוּ לְסִטְרָא דְרָע, לְמִשְׁלַט עֲלַיְיהוּ דְיִשְׂרָאֵל, לְמֶהֱוֵי בְּשִׁעְבּוּדָא דִילֵיהּ. דָּבָר אַחֵר לָמָּה הֲרֵעוֹתָ, דְּחָמָא כַּמָּה מִנְהוֹן דְּהֲווּ מֵתִין, וְאִתְמְסָרוּ בְּסִטְרָא דְרָע.</p>\n<p>תָּא חֲזֵי, בְּשַׁעְתָּא דְּטוֹב אִתְעַר, דְּאִיהוּ יְמִינָא, כָּל חֵידוּ, וְכָל טִיבוּ, וְכָל בִּרְכָאן מִשְׁתַּכְּחָן, וְכֹלָּא בַּחֲשַׁאי אִיהוּ, כְּמָה דְאוּקְמוּהָ, דְּאָמְרֵי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד בַּחֲשַׁאי, וְרָזָא דָא בְּגִין (ס\"א דהאי איהו יחודא) דְּאִיהוּ כְּדֵין יִחוּדָא כְּדְקָא חָזֵי.</p>\n<p>אָמַר רִבִּי חִיָּיא, וְכִי אֵלִיָּהוּ, כֵּיוָן דְּאִיהוּ גָּזַר, וְקוּדְשָׁא בְּרִיךְ הוּא מְקַיֵּים. וְאִיהוּ גָּזִיר עַל שְׁמַיָא, דְּלָא לַאֲחָתָא מִטְרָא וְטַלָּא, הֵיךְ דָּחִיל אִיהוּ מֵאִיזֶבֶל, דְּשַׁדְּרַת לֵיהּ. דִּכְתִיב, (מלכים א י״ט:ב׳) כִּי כָעֵת מָחָר אָשִׂים אֶת נַפְשְׁךָ כְּנֶפֶשׁ אַחַד מֵהֶם, וּמִיָּד דָּחִיל וְעָרַק עַל נַפְשֵׁיהּ.</p>\n<p>אָמַר לֵיהּ רִבִּי יוֹסֵי, הָא אוּקְמוּהָ, דְּצַדִּיקַיָא לָא בָּעָאן לְאַטְרָחָא לְמָארֵיהוֹן, בְּאֲתַר דְּנִזְקָא אִשְׁתַּכְּחַת (ליה) לְעֵינָא. כְּגַוְונָא דִשְׁמוּאֵל, דִּכְתִיב, (שמואל א ט״ז:ב׳) אֵיךְ אֵלֵךְ וְשָׁמַע שָׁאוּל וַהֲרָגָנִי, אָמַר לֵיהּ, עֶגְלַת בָּקָר תִּקַּח בְּיָדֶךָ. בְּגִין דְּצַדִּיקַיָּא לָא בָּעָאן לְאַטְרָחָא לְמָארֵיהוֹן בְּאֲתַר דְּנִזְקָא אִשְׁתַּכַּח. אוּף הָכִי אֵלִיָּהוּ, כֵּיוָן דְּחָמָא דְּנִזְקָא אִשְׁתַּכַּח, לָא בָּעֵי לְאַטְרָחָא לְמָארֵיהּ.</p>\n<p>אָמַר לֵיהּ, אֲנָא מִלָּה שְׁמַעְנָא, דְּהָא בְּאֵלִיָּהוּ לָא כְּתִיב בֵּיהּ וַיִּירָא וַיֵּלֶךְ אֶל נַפְשׁוֹ, אֶלָּא (מלכים א י״ט:ג׳) וַיַּרְא. רְאִיָה חָמָא. וּמַה חָמָא, אֶלָּא חָמָא דְּהָא מִכַּמָּה שְׁנִין אֲזַל בַּתְרֵיהּ מַלְאַךְ הַמָּוְת, וְלָא אִתְמָסַר בִּידֵיהּ. וְהַשְׁתָּא וַיֵּלֶךְ אֶל נַפְשׁוֹ, מַאי וַיֵּלֶךְ אֶל נַפְשׁוֹ, אֲזַל לְקִיּוּמָא דְנַפְשָׁא, וּמַאן אִיהוּ אִילָנָא דְחַיֵּי לְאִתְדַּבְּקָא תַּמָּן.</p>\n<p>תָּא חֲזֵי, כֻּלְּהוּ כְּתִיב אֶת נַפְשׁוֹ, וְהָכָא כְּתִיב אֶל נַפְשׁוֹ, וְרָזָא דָא שְׁמַעְנָא, דְּאָמַר רִבִּי שִׁמְעוֹן, כָּל נִשְׁמָתִין דְּעַלְמָא, כֻּלְּהוּ נָפְקֵי מֵהַהוּא נָהָר דְּנָגִיד וְנָפִיק, וְכֻלְּהוּ נָקִיט לוֹן הַהוּא צְרוֹרָא דְחַיָּיא (דחיי), וְכַד נוּקְבָא אִתְעַבְּרַת מִן דְּכוּרָא, כֻּלְּהוּ בְּתִיאוּבְתָּא דִּתְרֵין סִטְרִין, בְּתִיאוּבְתָּא דְּנוּקְבָא לְגַבֵּי דְכוּרָא. וְכַד תִּיאוּבְתָּא דִּדְכוּרָא נָפְקָא בִּרְעוּתָא, כְּדֵין אִינוּן נִשְׁמָתִין בְּקִיּוּמָא יַתִּיר, בְּגִין דְּכֹלָּא בְּתִיאוּבְתָּא וּרְעוּ דְּאִילָנָא דְּחַיָּיא. וְאֵלִיָּהוּ, בְּגִין דְּהֲוָה מֵהַהוּא רְעוּתָא יַתִּיר מִבַּר נָשׁ אָחֳרָא, אִתְקְיַּים.</p>\n<p>וּבְגִין כָּךְ אֶל נַפְשׁוֹ כְּתִיב, וְלָא כְּתִיב אֶת נַפְשׁוֹ. דְּהָא אֶת נַפְשׁוֹ דָּא הִיא נוּקְבָא. וְאִי תֵימָא וְאֶל הָאִשָּׁה אָמַר, כְּלָלָא דִּדְּכַר וְנוּקְבָא. כַּד הִיא בְּגוֹ דְּכוּרָא, כְּדֵין וְאֶל הָאִשָּׁה אָמַר. אֶת הָאִשָּׁה, נוּקְבָא בִּלְחוּדָהָא, וְלָא דִּדְּכוּרָא. כְּגַוְונָא דָא אֶל נַפְשׁוֹ, דָּכָר בִּלְחוֹדוֹי, אֶת נַפְשׁוֹ נוּקְבָא בִּלְחוּדָהָא וְלָא כְּלִילוּ דִּדְּכוּרָא. וּבְגִין דְּאִיהוּ מִסִּטְרָא דִּדְּכוּרָא יַתִּיר מִכָּל בְּנֵי עַלְמָא, אִתְקְיַּים בְּקִיּוּמֵיהּ יַתִּיר, וְלָא מִית כִּשְׁאָר בְּנֵי עַלְמָא. בְּגִין דְּכֹלָּא אִיהוּ מֵאִילָנָא דְחַיֵּי, וְלָא מִגּוֹ עַפְרָא. וּבְגִין דָּא אִסְתַּלַּק לְעֵילָא, וְלָא מִית כְּאֹרַח כָּל בְּנֵי עַלְמָא. דִּכְתִיב, (מלכים ב ב׳:י״א) וַיַּעַל אֵלִיָּהוּ בִּסְעָרָה הַשָּׁמַיִם.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב וְהִנֵּה רֶכֶב אֵשׁ וְסוּסֵי אֵשׁ וְגו', (שמות קצז ע\"א) דְּהָא כְּדֵין אִתְפַּשַּׁט גּוּפָא מִן רוּחָא, וְאִסְתַּלַּק דְּלָא כִּשְׁאָר אֹרַח בְּנֵי עַלְמָא. וְאִשְׁתָּאַר מַלְאֲכָא קַדִּישָׁא, כִּשְׁאָר קַדִּישֵׁי עֶלְיוֹנִין, וְעָבִיד שְׁלִיחוּתָא בְעַלְמָא. וְהָא אוּקְמוּהָ, דְּנִסִּין דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּעַלְמָא, עַל יְדֵיהּ אִתְעֲבִידָן.</p>\n<p>וְתָא חֲזֵי, מַה כְּתִיב, (מלכים א י״ט:ג׳) וַיִּשְׁאַל אֶת נַפְשׁוֹ. בְּקַדְמִיתָא, וַיֵּלֶךְ אֶל נַפְשׁוֹ, כְּמָה דְאִתְּמָר בְּקִיּוּמָא. וְהָכָא אֶת נַפְשׁוֹ לָמוּת, אִילָנָא דְבֵיהּ שַׁרְיָא מוֹתָא. וְתַמָּן אִתְגְּלִי עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דִכְתִיב, (מלכים א י״ט:י״ב) צֵא וְעָמַדְתָּ בָּהָר. מַה כְּתִיב בַּתְרֵיהּ, וְאַחַר הָרַעַשׁ אֵשׁ לא בָאֵשׁ ה' וְאַחַר הָאֵשׁ קוֹל דְּמָמָה דַקָּה, דָּא הוּא אֲתַר פְּנִימָאָה דְּכֹלָּא, דְּמִנֵּיהּ נָפְקִין כָּל נְהוֹרִין.</p>\n<p>מַה כְּתִיב, (מלכים א י״ט:י״ג) וַיְהִי כִּשְׁמֹעַ אֵלִיָּהוּ וַיָּלֶט פָּנָיו בְּאַדַּרְתּוֹ וְהִנֵּה אֵלָיו קוֹל וַיֹּאמֶר (תשא ק\"ץ ע\"א) מַה לְּךָ פֹה אֵלִיָּהוּ וַיֹּאמֶר קַנֹּא קִנֵּאתִי, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, עַד מָתַי אַתָּה מְקַנֵּא לִי, טְרָקַת גַּלָּא דְּלָא <Nonei></i>יָכִיל לְשַׁלְּטָאָה בָּךְ מוֹתָא לְעָלְמָא, וְעַלְמָא לָא יָכִיל לְמִסְבְּלָךְ עִם בָּנַי (נשא). אָמַר לֵיהּ, כִּי עָזְבוּ בְרִיתְךָ בְּנִי יִשְׂרָאֵל וְגו'. אָמַר לֵיהּ, חַיֶּיךָ, דְּבְּכָל אֲתַר דְּבָנַי (נשא) יְקַיְּימוּ קְיָים קַדִּישָׁא, אַנְתְּ תְּהֵא זַמִּין תַּמָּן. (ד\"א והא אתמר בגין כך מתקנין כורסיא לאליהו דאיהו זמין תמן)</p>\n<p>תָּא חֲזֵי, מַה גָּרַם הַהִיא מִלָּה דְאֵלִיָּהוּ, דִּכְתִיב, (מלכים א י״ט:י״ח) וְהִשְׁאַרְתִּי בְּיִשְׂרָאֵל שִׁבְעַת אֲלָפִים כָּל הַבִּרְכַּיִם אֲשֶׁר לא כָּרְעוּ לַבַּעַל וְכָל הַפֶּה אֲשֶׁר לֹא נָשַׁק לוֹ. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מִכָּאן וּלְהָלְאָה, דְּלָא יָכִיל עַלְמָא לְמִסְבְּלָךְ עִם בָּנַי (נשא). וְאֶת אֱלִישָׁע בֶּן שָׁפָט מֵאָבֵל מְחוֹלָה תִּמְשַׁח לְנָבִיא תַּחְתֶּיךָ. יְהֵא נְבִיאָה אָחֳרָא לְגַבֵּי בָּנַי (נשא), וְאַתְּ תִּסְתַּלַּק לְאַתְרָךְ.</p>\n<p>וְתָּא חֲזֵי, כָּל הַהוּא בַּר נָשׁ דִּמְקַנִּי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, לָא יָכִיל מַלְאֲכָא דְמוֹתָא לְשַׁלְּטָאָה בֵּיהּ, כִּשְׁאָר בְּנֵי נָשָׁא. וְיִתְקַיֵּים בֵּיהּ שְׁלָם, וְהָא אוּקְמוּהָ. כְּמָה דְאִתְּמָר בְּפִנְחָס, (במדבר כ״ה:י״ב) לָכֵן אֱמוֹר הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם:</p>"],[9520011419,"<p>וַיִּפּוֹל עַל צַוְּארֵי בִּנְיָמִן אָחִיו וַיֵּבְךִ וּבִנְיָמִן בָּכָה עַל צַוָּארָיו. רִבִּי יִצְחָק אָמַר, הָא אוּקְמוּהָ, דְּבָכָה עַל מִקְדָּשׁ רִאשׁוֹן וְעַל מִקְדָּשׁ שֵׁנִי.</p>\n<p>פָּתַח וְאָמַר, (שיר השירים ד׳:ד׳) כְּמִגְדַּל דָּוִד צַוָּארֵךְ בָּנוּי לְתַלְפִּיּוֹת אֶלֶף הַמָּגֵן תָּלוּי עָלָיו כֹּל שִׁלְטֵי הַגִּבּוֹרִים. כְּמִגְדַּל דָּוִד, מַאן מִגְדַּל דָּוִד. דָּא מִגְדַּל דָּוִד וַדַּאי, דְּבָנָה לֵיהּ דָּוִד, וְסָלִיק לֵיהּ גּוֹ יְרוּשָׁלַיִם. אֶלָּא כְּמִגְדַּל דָּוִד, דָּא יְרוּשָׁלֵם דִּלְעֵילָא, דִּכְתִיב בֵּיהּ, (משלי י״ח:י׳) מִגְדַּל עֹז שֵׁם ה' בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. מַאן נִשְׂגָּב, אֶלָּא הַהוּא מִגְדַּל נִשְׂגָּב, בְּגִין דְּבֵיהּ יָרוּץ צַדִּיק.</p>\n<p>צַוָּארֵךָ, דָּא בֵּית מַקְדְּשָׁא דִלְתַתָּא, דְּאִיהוּ קָאִים בְּתִקּוּנָא דְּשַׁפִּירוּ, כְּקַדְלָא לְגוּפָא. מַה צַּוָּאר, אִיהוּ שַׁפִּירוּ דְּכָל גּוּפָא, הָכִי נָמֵי בֵּי מַקְדְּשָׁא, אִיהוּ שַׁפִּירוּ דְּכָל עַלְמָא.</p>\n<p>בָּנוּי לְתַלְפִּיּוֹת, תִּלָּא דְּכָל בְּנֵי עַלְמָא הֲווּ מִסְתַּכְּלָן בֵּיהּ, וְהָכִי אוּקְמוּהָ, תַּלְפִּיּוֹת, תֵּל דְּכָל פִּיּוֹת דְּעַלְמָא מְשַׁבְּחָן וּמְצַלָּאן לְגַבֵּיהּ.</p>\n<p>אֶלֶף הַמָּגֵן תָּלוּי עָלָיו, אִלֵּין אֶלֶף תִּקּוּנִין, דִּמְתַקְּנִין בֵּיהּ כְּדְקָא יְאוּת. כֹּל שִׁלְטֵי הַגִּבּוֹרִים, דְּכֻלְּהוּ קָא אַתְיָין מִסִּטְרָא דְּדִינָא קַשְׁיָא.</p>\n<p>מַה צַּוָּאר, כָּל תִּקּוּנִין דְּאִתְּתָא בֵּיהּ תַּלְיָין. כָּךְ בְּמַקְדְּשָׁא, כָּל תִּקּוּנִין דְּעַלְמָא בֵּיהּ תַּלְיָין וְשָׁרְיָין. וְהָא אוּקְמוּהָ, דִּכְתִיב, (איכה ה׳:ה׳) עַל צַוָּארֵינוּ נִרְדָּפְנוּ, עַל בֵּי מַקְדְּשָׁא, דְּאִיהוּ צַוָּאר וְשַׁפִּירוּ דְּכָל עַלְמָא. נִרְדָּפְנוּ, יָגַעְנוּ לְמִבְנֵי לֵיהּ תְּרֵין זִמְנִין, וְלֹא הוּנַח לָנוּ. דְּהָא לָא שָׁבְקוּהָ לָן, וְאִתְחָרַב וְלָא אִתְבְּנֵי לְבָתַר.</p>\n<p>מַה צַּוָּאר, כֵּיוָן דְּאִשְׁתֵּצֵי, כָּל גּוּפָא אִשְׁתֵּצֵי עִמֵּיהּ. הָכִי נָמֵי בֵּי מַקְדְּשָׁא, כֵּיוָן דְּאִיהוּ אִשְׁתֵּצֵי וְאִתְחַשַּׁךְ, כָּל עַלְמָא הָכִי נָמֵי אִתְחַשַּׁךְ, וְלָא נָהִיר שִׁמְשָׁא, וְלָא שְׁמַיָא וְאַרְעָא וְכֹכְבַיָא.</p>\n<p>בְּגִין כָּךְ בָּכָה יוֹסֵף עַל דָּא. וּלְבָתַר דְּבָכָה עַל דָּא, בָּכָה עַל שִׁבְטִין דְּאִתְגָּלוּ. כַּד אִתְחָרִיב בֵּי מַקְדְּשָׁא, כֻּלְּהוּ שִׁבְטִין אִתְגָּלוּ מִיָּד, וְאִתְבַּדְּרוּ בֵּינֵי עַמְמַיָא. הֲדָא הוּא דִכְתִיב וַיְנַשֵּׁק לְכָל אֶחָיו וַיֵּבְךִ עֲלֵיהֶם, עֲלֵיהֶם וַדַּאי.</p>\n<p>עַל כֻּלָּם בָּכָה, עַל בֵּי מַקְדְּשָׁא דְּאִתְחָרִיב תְּרֵין זִמְנִין, וְעַל אֲחוֹי עֲשֶׂרֶת הַשְּׁבָטִים, דְּאִתְגָּלוּ בְּגָלוּתָא וְאִתְבַּדְּרוּן בֵּינֵי עַמְמַיָא. וְאַחֲרֵי כֵן דִּבְּרוּ אֶחָיו אִתּוֹ, וְלָא כְּתִיב וַיִּבְכּוּ, דְּהָא אִיהוּ בָּכָה, דְּנִצְנְצָה בֵּיהּ רוּחָא קַדִּישָׁא, וְאִינוּן לָא בָּכוּ, דְּלָא שָׁרָא עֲלַיְיהוּ רוּחַ קוּדְשָׁא:</p>"],[9520011420,"<p>וְהַקֹּל נִשְׁמַע בֵּית פַּרְעֹה. רִבִּי (אלעזר) אַבָּא פָּתַח וְאָמַר, (תהילים פ״ד:ג׳) נִכְסְפָה וְגַם כָּלְתָה נַפְשִׁי לְחַצְרוֹת ה' לִבִּי וּבְשָׂרִי יְרַנְּנוּ אֶל אֵל חָי. תָּא חֲזֵי, כָּל בַּר נָּשׁ דְּצַלֵּי צְלוֹתֵיהּ (וקם) קַמֵּי מָארֵיהּ, אִצְטְרִיךְ לֵיהּ לְאַקְדָּמָא לֵיהּ בִּרְכָאן בְּכָל יוֹמָא וְיוֹמָא, וּלְצַלֵּי צְלוֹתֵיהּ קַמֵּי מָארֵיהּ בְּזִמְנָא דְאִצְטְרִיךְ.</p>\n<p>בְּצַפְרָא, לְאַחֲדָא בִּימִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא. בְּמִנְחָה, לְאַחֲדָא בִּשְׂמָאלָא. וּצְלוֹתָא וּבָעוּתָא, אִצְטְרִיךְ לֵיהּ לְבַר נָשׁ בְּכָל יוֹמָא וְיוֹמָא בְּגִין לְאִתְאַחֲדָא בֵּיהּ. וְאוֹקִימְנָא, מַאן דְּצַלֵּי צְלוֹתֵיהּ, (וקם) קַמֵּי מָארֵיהּ, אִצְטְרִיךְ לֵיהּ דְּלָא לְמִשְׁמַע קָלֵיהּ בִּצְלוֹתֵיהּ. וּמַאן דְּאַשְׁמַע קָלֵיהּ בִּצְלוֹתֵיהּ, צְלוֹתֵיהּ לָא אִשְׁתְּמַע.</p>\n<p>מַאי טַעְמָא. בְּגִין <Nonei></i>(שמות ר\"ב ע\"ב) דִּצְלוֹתָא, לָאו אִיהִי הַהִיא קָלָא דְּאִשְׁתְמַע. דְּהַהוּא קוֹל דְּאִשְׁתַּמַּע לָאו הִיא צְלוֹתָא. וּמַאן אִיהִי צְלוֹתָא. דָּא קָלָא אָחֳרָא, דְּתַלְיָא בְּקָלָא דְאִשְׁתְּמַע, וּמַאן הוּא קָלָא דְּאִשְׁתְּמַע. דָּא הַהוּא קוֹל דְּהוּא בְּוא\"ו, קָלָא דְתַלְיָא בֵּיהּ, דָּא הַהוּא קֹל בְּלָא וא\"ו.</p>\n<p>וּבְגִין כָּךְ, לָא אִצְטְרִיךְ לֵיהּ לְבַר נָשׁ לְמִשְׁמַע קָלֵיהּ בִּצְלוֹתֵיהּ, אֶלָּא לְצַלָּאָה בְּלַחַשׁ, בְּהַהוּא קָלָא דְּלָא אִשְׁתְּמַע. וְדָא הִיא צְלוֹתָא דְּאִתְקַבָּלַת תָּדִיר. וְסִימָנִיךְ, וְהַקֹּל נִשְׁמַע, קֹל בְּלָא וא\"ו, נִשְׁמַע. דָּא הִיא צְלוֹתָא דְּהִיא בַּחֲשַׁאי. דִּכְתִיב בְּחַנָּה, (שמואל א א׳:י״ג) וְקוֹלָהּ לא יִשָּׁמַע. דָּא הִיא צְלוֹתָא דְּקוּדְשָׁא בְּרִיךְ הוּא קַבִּיל, כַּד אִתְעֲבִיד גּוֹ רְעוּתָא וְכַוָּונָה וְתִקּוּנָא כְּדְקָא יְאוּת, וּלְיַחֲדָא יִחוּדָא דְמָרֵיהּ כְּדְקָא יָאוֹת בְּכָל יוֹמָא. (והקל נשמע בית פרעה. והקל נשמע חסר וא\"ו, מאי טעמא, אמר רבי אלעזר, דא היא שכינתא דבכאת על חרוב בי מקדשא ועל גלותהון דישראל. כתיב הכא, והקל נשמע, וכתיב התם, (ירמיהו ל״א:ט״ו) קול ברמה נשמע. מה להלן שכינתא, אף כאן נמי שכינתא).</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, קָלָא בַּחֲשַׁאי, דָּא הִיא קָלָא עִלָּאָה, דְּכָל קָלִין נָפְקִין מִתַּמָּן. אֲבָל קֹל בְּלָא ו', דָּא הִיא צְלוֹתָא דִלְתַתָּא, דְּאִיהִי אָזְלָא לְאִסְתַּלְּקָא בְּוא\"ו וּלְאִתְחַבְּרָא בֵּיהּ.</p>\n<p>תָּא חֲזֵי, וְהַקֹּל נִשְׁמַע, דָּא הוּא קֹל בְּלָא וא\"ו. דָּא הִיא קָלָא דְּבָּכַאת עַל מִקְדָּשׁ רִאשׁוֹן וְעַל מִקְדָּשׁ שֵׁנִי. נִשְׁמַע, כְּמָה דְאַתְּ אָמֵר, קוֹל בְּרָמָה נִשְׁמָע. בְּרָמָה, מַאי בְּרָמָה. דָּא הוּא עַלְמָא עִלָּאָה, עַלְמָא דְאָתֵי. וְסִימָנִיךְ, מִן הָרָמָה וְעַד בֵּית אֵל, (תהילים ק״ו:מ״ח) מִן הָעוֹלָם וְעַד הָעוֹלָם. הָכָא בְּרָמָה, דָּא עַלְמָא עִלָּאָה. דְּהָא בְּהַהִיא שַׁעְתָּא דִּי בְּרָמָה נִשְׁמַע. כְּדֵין מַה כְּתִיב, (ישעיהו כ״ב:י״ב) וַיִּקְרָא ה' אֱלהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וְגו'.</p>\n<p>וְהַקֹּל נִשְׁמַע, לְעֵילָא לְעֵילָא. מַאי טַעְמָא. בְּגִין דְּוא\"ו אִתְרַחַק וְאִסְתַּלַּק מִנֵּיהּ, וּכְדֵין רָחֵל מְבַכָּה עַל בָּנֶיהָ מֵאֲנָה לְהִנָּחֵם עַל בָּנֶיהָ כִּי אֵינֶנוּ. כִּי אֵינֶנּוּ, כִּי אֵינָם מִבָּעֵי לֵיהּ. אֶלָּא כִּי אֵינֶנּוּ, וְהָא אוֹקִימְנָא, כִּי אֵינֶנּוּ, דְּבַעֲלָהּ לָא אִשְׁתַּכַּח עִמָּהּ. דְּאִלְּמָלֵא בַּעֲלָהּ יִשְׁתַּכַּח עִמָּהּ, תִּתְנַחֵם עֲלַיְיהוּ. דְּהָא כְּדֵין בְּנָהָא, לָא יְהוֹן בְּגָלוּתָא. וּבְגִין דְּאֵינֶנּוּ, לָאו אִיהִי מִתְנַחֲמָא עַל בְּנָהָא, בְּגִין דִּבְנָהָא אִתְרַחֲקוּ מִנָּהּ, עַל דְּאֵינֶנּוּ עִמָּהּ.</p>\n<p>תָּא חֲזֵי, בֵּית פַּרְעֹה, דָּא הוּא סִימָנִיךְ לְעֵילָא, בֵּיתָא דְּאִתְפְּרָעוּ וְאִתְגַּלְּיָין מִנֵּיהּ כָּל נְהוֹרִין וְכָל בּוּצִינִין, כָּל מַה דְּהֲוָה סָתִים, מִתַּמָּן אִתְגְּלִי. וּבְגִין כָּךְ, קוּדְשָׁא בְּרִיךְ הוּא אַפִּיק כָּל נְהוֹרִין וְכָל בּוּצִינִין, בְּגִין לְאַנְהָרָא לְהַהוּא קוֹל, דְּאִקְרֵי קֹל בְּלָא וא\"ו.</p>\n<p>תָּא חֲזֵי, כַּד יָקִים קוּדְשָׁא בְּרִיךְ הוּא לְהַאי קֹל מֵעַפְרָא, וְיִתְחַבַּר בְּוא\"ו, כְּדֵין כָּל מַה דְּאִתְאֲבִיד מִנַּיְיהוּ בְּזִמְנָא דְגָלוּתָא, יִתְהֲדַר וְיִתְעַדְּנוּן בִּנְהוֹרִין עִלָּאִין דְּאִתּוֹסְפָן מִגּוֹ עַלְמָא עִלָּאָה. כְּמָא דְאַתְּ אָמֵר, (ישעיהו כ״ז:י״ג) וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וּבָאוּ הָאוֹבְדִים בְּאֶרֶץ אַשּׁוּר וְהַנִּדָּחִים בְּאֶרֶץ מִצְרַיִם וְהִשְׁתַּחֲווּ לַה' בְּהַר הַקֹּדֶשׁ בִּירוּשָׁלָם:</p>"],[9520011421,"<p>וְאַתָּה צֻוֵּיתָה זֹאת עֲשׂוּ קְחוּ לָכֶם מֵאֶרֶץ מִצְרַיִם וְגו'. רִבִּי חִיָּיא פָּתַח, (ישעיהו ס״ו:י׳) שִׂמְחוּ אֶת יְרוּשָׁלַם וְגִילוּ בָהּ כָּל אוֹהֲבֶיהָ שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ וְגו'. תָּא חֲזֵי, כַּד אִתְחָרַב בֵּי מַקְדְּשָׁא וְגָרְמוּ חוֹבִין, וְאִתְגָּלוּ יִשְׂרָאֵל מֵאַרְעָא, (ויקרא ע\"ה ע\"א) אִסְתַּלַּק קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָא לְעֵילָא, וְלָא אַשְׁגַּח עַל חָרוּב בֵּי מַקְדְּשָׁא, וְעַל עַמֵּיהּ דְּאִתְגָּלוּ, וּכְדֵין שְׁכִינְתָּא אִתְגַּלְּיָיא עִמְּהוֹן.</p>\n<p>כַּד נָחַת, אַשְׁגַּח עַל בֵּיתֵיהּ דְּאִתּוֹקַד, אִסְתַּכַּל עַל עַמֵּיהּ וְהָא אִתְגְּלִי. שָׁאַל עַל מַטְרוֹנִיתָא וְאִתְתָּרְכַת. כְּדֵין וַיִּקְרָא ה' אֱלֹהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וּלְקָרֵחָה וְלַחֲגֹר שָׂק. וְהִיא גַּם הִיא מַה כְּתִיב בָּהּ, (יואל א׳:ח׳) אֱלִי כִּבְתוּלָה חֲגֻרַת שַׂק עַל בַּעַל נְעוּרֶיהָ. כְּמָא דְאַתְּ אָמֵר כִּי אֵינֶנּוּ, בְּגִין דְּאִסְתַּלַּק מִינָהּ, וְאִשְׁתַּכַּח פִּירוּדָא.</p>\n<p>וְאֲפִילּוּ שְׁמַיָא וְאַרְעָא, כֻּלְּהוּ אִתְאַבָּלוּ, דִּכְתִיב, (ישעיהו נ׳:ג׳) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. מַלְאֲכֵי עִלָּאֵי כֻּלְּהוּ אִתְאַבָּלוּ עֲלֵיהּ, דִּכְתִיב, (ישעיהו ל״ג:ז׳) הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָּה מַלְאַכֵי שָׁלוֹם מַר יִבְכָּיוּן. שִׁמְשָׁא וְסִיהֲרָא אִתְאַבָּלוּ וְחָשְׁכוּ נְהוֹרֵיהוֹן. דִּכְתִיב, (ישעיהו י״ג:י׳) חָשַׁךְ הַשֶּׁמֶשׁ בְּצֵאתוֹ וְגו', וְכֹלָּא עִלָּאֵי וְתַתָּאֵי, בָּכוּ עֲלָהּ <Nonei></i>וְאִתְאַבָּלוּ. מַאי טַעְמָא, בְּגִין דְּשָׁלְטָא עֲלָהּ סִטְרָא אָחֳרָא, דְּשָׁלְטָא עַל אַרְעָא קַדִּישָׁא.</p>\n<p>פָּתַח וְאָמַר, (יחזקאל ז׳:ב׳) וְאַתָּה בֶּן אָדָם כֹּה אָמַר ה' אֱלֹהִים לְאַדְמַת יִשְׂרָאֵל קֵץ בָּא הַקֵּץ עַל אַרְבַּע כַּנְפוֹת הָאָרֶץ. הַאי קְרָא רָזָא עִלָּאָה אִיהוּ. לְאַדְמַת יִשְׂרָאֵל קֵץ, מַאי אִיהוּ. וְכִי אַדְמַת יִשְׂרָאֵל קֵץ הִיא. אֶלָּא הָכִי הוּא וַדַּאי וְאִתְּמָר, קֵץ אִיהוּ לִימִינָא, קֵץ אִיהוּ לִשְׂמָאלָא. קֵץ לִימִינָא, דִּכְתִיב, (דניאל יב) לְקֵץ הַיָּמִין. קֵץ לִשְׂמָאלָא, דִּכְתִיב, (איוב כ״ח:ג׳) קֵץ שָׂם לַחשֶׁךְ וּלְכָל תַּכְלִית הוּא חוֹקֵר, וְדָא הוּא (בראשית ו׳:י״ג) קֵץ כָּל בָּשָׂר, כְּמָה דְאִתְּמָר.</p>\n<p>קֵץ דִּימִינָא, הַיְינוּ דִכְתִיב לְאַדְמַת יִשְׂרָאֵל קֵץ. בָּא הַקֵּץ, דָּא קֵץ דִּשְׂמָאלָא. קֵץ דִּימִינָא, דָּא קֵץ דְּיֵצֶר הַטּוֹב. קֵץ דִּשְׂמָאלָא, דָּא קֵץ דְּיֵצֶר הָרָע, וְדָא אִיהוּ דְּכַד חוֹבִין גָּרְמוּ וְאִתְגַּבְּרוּ, אִתְגְּזַר וְאִתְיְיהִיב שָׁלְטָנָא לְמַלְכוּת הָרְשָׁעָה לְשַׁלְטָאָה, וּלְחָרָבָא בֵּיתֵיהּ וּמִקְדְּשֵׁיהּ. וְדָא הוּא דִכְתִיב, (יחזקאל ז׳:ה׳) כֹּה אָמַר ה' אֱלהִים רָעָה אַחַר רָעָה הִנֵּה בָאָה, וְכֹלָּא חַד.</p>\n<p>וּבְגִין כָּךְ, אִתְאַבָּלוּ עִלָּאֵי וְתַתָּאֵי עַל דְּאִתְיְיהִיב שָׁלְטָנוֹ לְהַאי קֵץ דִּשְׂמָאלָא. וּבְגִין כָּךְ, כֵּיוָן דְּמַלְכוּ קַדִּישָׁא, מַלְכוּת שָׁמַיִם אִתְכַּפְיָא, וּמַלְכוּת חַיָּיבָא (אחרא) אִתְגַּבַּר. (כדין) אִית לֵיהּ לְכָל בַּר נָשׁ, לְאִתְאַבָּלָא עִמָּהּ, וּלְאִתְכַּפְיָא עִמָּהּ. וּבְגִין דְּכַד אִיהִי יִזְדַּקְּפָא, וְעַלְמָא יִתְחַדֵּי, יִתְחַדֵּי אִיהוּ בַּהֲדָהּ. דִּכְתִיב, (ישעיהו ס״ו:י׳) שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ כָּל הַמִּתְאַבְּלִים עָלֶיהָ.</p>\n<p>תָּא חֲזֵי, כְּתִיב בְּהוּ בְּמִצְרַיִם, (ירמיה מו) עֶגְלָה יְפִיפִיָה מִצְרַיִם. וְרָזָא דְּעֶגְלָה דָא, הֲווּ יִשְׂרָאֵל תְּחוֹת שָׁלְטָנֵיהּ כַּמָּה זִמְנִין וְכַמָּה שְׁנִין. וּבְגִין דִּזְמִינִין יִשְׂרָאֵל לְשַׁלְּטָאָה לְבָתַר עֲלָהּ, אִתְרְמִיז לוֹן הַשְׁתָּא עֲגָלוֹת.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, רֶמֶז רָמַז לֵיהּ יוֹסֵף לְיַעֲקֹב עַל עֶגְלָה עֲרוּפָה. דְּהָא בְּהַהוּא פִּרְקָא אִתְפְּרַשׁ מִנֵּיהּ. וְאוּקְמוּהָ, עֶגְלָה עֲרוּפָה, דְּאִיהִי אַתְיָא עַל דְּאִשְׁתַּכַּח קָטוֹלָא, וְלָא אִתְיְידַע מַאן קָטִיל לֵיהּ. וּבְגִין דְּלָא יִשְׁלְטוּן עַל אַרְעָא רוּחִין בִּישִׁין דְּלָא אִצְטְרִיכוּ, יַהֲבִין הַאי עֶגְלָה לְתִקּוּנָא, בְּגִין דְּלָא יִשְׁתְּמוֹדְעוּן לְגַבֵּיהּ, וְלָא יִשְׁלְטוּ עֲלַיְיהוּ. (לעיל קיד ע\"א)</p>\n<p>תָּא חֲזֵי, כָּל בְּנֵי נָשָׁא כֻּלְּהוּ עָבְרִין עַל יְדֵי דְּמַלְאַךְ הַמָּוֶת, בַּר מֵהַאי דְּאַקְדִּימוּ לֵיהּ בְּנֵי נָשָׁא, עַד לָא יִמְטֵי זִמְנָא לְשַׁלְּטָאָה בֵּיהּ וְלִיטוֹל רְשׁוּ. דְּהָא לָא שַׁלִּיט בְּבַר נָשׁ, עַד דְּנָטִיל רְשׁוּ.</p>\n<p>וּבְגִין כָּךְ, אִית לֵיהּ דִּינָא לְשַׁלְּטָאָה עַל הַהוּא אֲתַר. כְּמָה דְאַתְּ אָמֵר, (דברים כ״א:א׳) לא נוֹדַע מִי הִכָּהוּ. הָכִי נָמֵי אִית לֵיהּ דִּינָא דְּלָא אִתְיְידַע, בְּגִין לְקַטְרְגָא עַל הַהוּא אֲתַר. וְעַל דָּא, (דברים כ״א:ג׳) וְלָקְחוּ זִקְנֵי הָעִיר הַהִיא עֶגְלַת בָּקָר וְגו'. בְּגִין לְאַעֲבָרָא דִינֵיהּ דְּהַהוּא אֲתַר, וּלְאִתְתַּקָּנָא דְּלָא יִשְׁלוֹט בֵּיהּ מְקַטְרְגָא, וּלְאִשְׁתְּזָבָא מִנֵּיהּ.</p>\n<p>תָּא חֲזֵי, יוֹסֵף כַּד אִתְפְּרַשׁ מֵאֲבוֹי, בְּלָא לְוָיָה, וּבְלָא אֲכִילָה אִשְׁתַּדַּר, וְהֲוָה מַה דְּהֲוָה. וְכַד אָמַר יַעֲקֹב, (בראשית ל״ז:ל״ה) טָרוֹף טוֹרַף יוֹסֵף, אָמַר, כִּי אֵרֵד אֶל בְּנִי אָבֵל שְׁאוֹלָה, דְּאֲנָא גָרִימְנָא לֵיהּ. וְתוּ, דַּהֲוֵינָא יָדַע דַּאֲחוֹי סַנְיָין לֵיהּ, וְשַׁדַּרְנָא לֵיהּ. וְרֶמֶז קָא רָמִיז לֵיהּ.</p>\n<p>אָמַר לֵיהּ רִבִּי יְהוּדָה, אִינוּן עֲגָלוֹת עַל פִּי פַּרְעֹה שַׁדַּר לוֹן, דִּכְתִיב וַיִּתֵּן לָהֶם יוֹסֵף עֲגָלוֹת עַל פִּי פַּרְעֹה. אָמַר לֵיהּ, דִּיּוּקָא דְמִלָּה, דִּכְתִיב וְאַתָּה צֻוֵּיתָה זֹאת עֲשׂוּ. וְאַתָּה צֻוֵּיתָה דַּיְיקָא, וּבְגִין כָּךְ כְּתִיב בְּה\"א, מַשְׁמַע דְּיוֹסֵף תָּבַע לוֹן, וּבְגִין כָּךְ וַיִּתֵּן לָהֶם יוֹסֵף עֲגָלוֹת עַל פִּי פַּרְעֹה. וְיַעֲקֹב לָא אִתְקְיַּים בְּמִלָּה, עַד דְּחָמָא לוֹן. דִּכְתִיב, וַיַּרְא אֶת הָעֲגָלוֹת אֲשֶׁר שָׁלַח יוֹסֵף לָשֵׂאת אוֹתוֹ וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּקַדְמִיתָא וַתְּחִי רוּחַ יַעֲקֹב, וּלְבָתַר וַיֹּאמֶר יִשְׂרָאֵל רַב עוֹד יוֹסֵף בְּנִי חָי. אֶלָּא, בְּקַדְמִיתָא קָרֵי לֵיהּ אוֹרַיְיתָא יַעֲקֹב, בְּגִין שׁוּתָּפוּתָא, דְּאִשְׁתַּתְּפוּ שְׁכִינְתָּא בְּהַהוּא חֵרֶם, כַּד אִזְדַּבַּן יוֹסֵף. וְהַשְׁתָּא דִּשְׁכִינְתָּא סָלְקָא, כְּדֵין אִיהוּ, וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם, וְדָא הוּא רָזָא דִשְׁכִינְתָּא. וּבָתַר דְּאִיהִי קָיְימָא בְּקִיּוּמָא, (בגין) כְּדֵין דַּרְגָּא דִלְעֵילָא, אִתְעֲבַר לְגַבָּהּ, דַּרְגָּא דְּאִיהוּ יִשְׂרָאֵל. (נ\"א כדין דרגא דלעילא, אתער לגבה, ואיהו דרגא דישראל) מִכָּאן, דְּדַרְגָּא דִלְעֵילָא לָא אִתְעַר לְעֵילָא, עַד דְּאִתְעַר בְּקַדְמִיתָא לְתַתָּא, דְּהָא הָכָא וַתְּחִי רוּחַ <Nonei></i>יַעֲקֹב בְּקַדְמִיתָא, וּלְבָתַר וַיֹּאמֶר יִשְׂרָאֵל.</p>\n<p>וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאֹת הַלַּיְלָה, בְּמַרְאַת כְּתִיב. תָּא חֲזֵי, וַיִּזְבַּח זְבָחִים לֵאלהֵי אָבִיו יִצְחָק, בְּקַדְמִיתָא. בְּגִין לְאִתְעָרָא שְׂמָאלָא בְּרָזָא דִרְחִימוּ. וּכְדֵין וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאוֹת הַלַּיְלָה, בְּהַאי דַרְגָּא דְּקָאֲמָרָן דְּאִיהִי מַרְאוֹת הַלַּיְלָה.</p>\n<p>וַיֹּאמֶר אָנֹכִי הָאֵל אֱלֹהֵי אָבִיךָ, מַאי טַעְמָא. בְּגִין דְּסִטְרָא דִקְדּוּשָּׁה דִלְעֵילָא, הָכִי הוּא. דְּהָא סִטְרָא דִמְסָאֲבָא, לָא אַדְכַּר שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכָל סְטַר דִּקְדּוּשָּׁה אִדְכַּר בִּשְׁמֵיהּ. אָנֹכִי אֵרֵד עִמְּךָ מִצְרַיְמָה וְגו', מִכָּאן, דִּשְׁכִינְתָּא נָחֲתַת עִמֵּיהּ בְּגָלוּתָא, וּבְכָל אֲתַר דְּיִשְׂרָאֵל אִתְגָּלוּ, שְׁכִינְתָּא אִתְגַּלְּיָא עִמְּהוֹן, וְהָא אוּקְמוּהָ.</p>\n<p>תָּא חֲזֵי, כַּמָּה עֲגָלוֹת הֲווּ. שִׁית. כְּמָא דְאַתְּ אָמֵר, (במדבר ו) שֵׁשׁ עֶגְלוֹת צָב. דָּבָר אַחֵר, שִׁיתִּין הֲווּ, וְכֹלָּא רָזָא חָדָא. בְּקַדְמִיתָא כְּתִיב בָּעֲגָלוֹת אֲשֶׁר שָׁלַח יוֹסֵף, וּלְבַסּוֹף אֲשֶׁר שָׁלַח פַּרְעֹה. אֶלָּא, כֻּלְּהוּ דְּשַׁדַּר יוֹסֵף, הֲווּ בְּחוּשְׁבָּנָא כְּדְקָא חָזֵי. וְאִינוּן דְּשַׁדַּר פַּרְעֹה יַתִּיר מִנַּיְיהוּ, לָא הֲווּ בְּרָזָא דָא, וְלָא הֲווּ בְּחוּשְׁבָּנָא.</p>\n<p>וְאִלֵּין וְאִלֵּין קָאָתוּ. בְּגִין כָּךְ, אֲשֶׁר שָׁלַח יוֹסֵף, אֲשֶׁר שָׁלַח פַּרְעֹה. וְכַד יִפְקוּן יִשְׂרָאֵל מִן גָּלוּתָא מַה כְּתִיב, (ישעיהו ס״ו:כ׳) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה' וְגו':</p>"],[9520011422,"<p>וַיֶּאֱסוֹר יוֹסֵף מֶרְכַּבְתּוֹ, רִבִּי יִצְחָק פָּתַח וְאָמַר, (יחזקאל א׳:כ״ב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ כְּעֵין הַקֶּרַח הַנּוֹרָא נָטוּי עַל רָאשֵׁיהֶם מִלְּמַעְלָה, הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, אִית חַיָּה לְעֵיל מִן חַיָּה, וְאִית חַיָּה קַדִּישָׁא דְּקָיְימָא עַל רִישׁ חֵיוָתָא.</p>\n<p>וְאִית חַיָּה עִלָּאָה, לְעֵילָא עַל כָּל שְׁאָר חֵיוָתָא, וְהַאי (נ\"א ואית) חַיָּה שָׁלְטָא עַל כֻּלְּהוּ. בְּגִין דְּכַד הַאי חֵיוָתָא יָהֲבָא וְנָהֲרָא לְכֻלְּהוּ, כְּדֵין כֻּלְּהוּ נָטְלִין לְמַטְלָנוֹי, וִיהִיבַת דָּא לְדָא, וְשָׁלְטָא דָּא עַל דָּא.</p>\n<p>וְאִית חֵיוָתָא לְעֵילָא עַל תַּתָּאֵי, עַל שְׁאָר חֵיוָתָא לְתַתָּא, וְכֻלְּהוּ אִתְּזָנוּ מִינָהּ, וְד' סִטְרֵי דְעַלְמָא רְשִׁימִין בָּהּ. אַנְפִּין נְהִירִין יְדִיעָן (דינין) לְכָל סְטַר, וְאִיהִי שָׁלְטָא עַל ד' סִטְרֵי. וְהָא אוּקְמוּהָ, דְּאִינוּן ג' לִסְטַר דָּא, וְג' לִסְטַר דָּא, וְכֵן לְד' סִטְרִין דְּעַלְמָא.</p>\n<p>(שמות ריב ע\"א) וְאִית רָקִיעַ לְעֵיל מִן רָקִיעַ, וְהַאי רָקִיעַ דְּשָׁלְטָא עֲלַיְיהוּ, כֻּלְּהוּ מִסְתַּכְּלָן לְגַבֵּיהּ. מַה כְּתִיב, (יחזקאל א׳:כ״ג) וְתַחַת הָרָקִיעַ כַּנְפֵיהֶם יְשָׁרוֹת אִשָּׁה אֶל אֲחוֹתָהּ וְגו'. בְּגִין דְּכֻלְּהוּ שָׁלְטִין עַל מַה דְּאִתְפָּקְדוּ, וּשְׁלִיחוּ דְּקוּסְטָא דְּקוּפְטְרָא בְּהוּ.</p>\n<p>וְאִינוּן לְכָל סְטַר תִּשְׁעָה, (ט') לְד' סִטְרִין דְּעַלְמָא, וְאִינוּן ל\"ו בְּחוּשְׁבְּנָא. וְכַד מִתְחַבְּרָן כֻּלְּהוּ, אִתְעֲבִידוּ רְשִׁימָא חָדָא בְּרָזָא דִשְׁמָא חָדָא, בְּיִחוּדָא שְׁלִים כִּדְקָחָזֵי.</p>\n<p>וְכַד מִתְתַּקְנֵי לְגַבֵּי כָּרְסְיָא, מַה כְּתִיב. וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֶה אָדָם עָלָיו מִלְּמָעְלָה, וְהָא אוֹקִימְנָא (נ\"א דיוקנא) דְּהַאי אֶבֶן טָבָא בְּכָרְסְיָא דְּקָיְימָא עַל ד' קָיְימִין, וְעַל הַהוּא כָּרְסְיָא דִּיוּקְנָא דְאָדָם, לְאִתְחַבְּרָא בֵּיהּ כְּחֲדָא, וּלְאִתְבָּרְכָא כְּדְקָא יְאוּת.</p>\n<p>וְכַד אִיהִי מִתְתַּקְנָא לְגַבֵּיהּ דְּאָדָם, לְמֶהֱוֵי כֹּלָּא רְתִיכָא (נ\"א קדישא, וכהן כלא רתיכא) חָדָא, לְהַאי אָדָם. כְּדֵין כְּתִיב, וַיֶּאֱסוֹר יוֹסֵף מֶרְכַּבְתּוֹ דָּא צַדִּיק. וַיַּעַל לִקְרַאת יִשְׂרָאֵל אָבִיו גּשְׁנָה. לִקְרַאת יִשְׂרָאֵל, דָּא רָזָא דְּאָדָם. גּשְׁנָה, תִּקְרוּבְתָּא חָדָא, לְאִתְקְרָבָא כְּחֲדָא, בְּקָרְבָּנָא חָדָא וְיִחוּדָא חָדָא.</p>\n<p>וַיֵּרָא אֵלָיו, דְּכַד אִתְחֲזֵי שִׁמְשָׁא בְּסִיהֲרָא, כְּדֵין נָהִיר סִיהֲרָא וְאַנְהִיר לְכֻלְּהוּ דִלְתַתָּא. וְכֵן כְּגַוְונָא דָא, כָּל זִמְנָא דִּקְדּוּשָּׁה דִלְעֵילָא שָׁרָא עַל מַקְדְּשָׁא דִלְתַתָּא, אִתְנְהִיר בֵּי מַקְדְּשָׁא וְקָיְימָא בִּשְׁלִימוּתֵיהּ. וְכַד אִסְתַּלַּק מִנֵּיהּ וְאִתְחָרִיב בֵּי מַקְדְּשָׁא, כְּדֵין, וַיֵּבְךִ עַל צַוָּארָיו עוֹד. דְּבָכוּן כֹּלָּא עַל מַקְדְּשָׁא דְּאִתְחָרִיב. עוֹד, מַאי עוֹד. דָּא גָלוּתָא בַּתְרָאָה.</p>\n<p>כְּדֵין כֵּיוָן דְּחָמָא יַעֲקֹב וְאִסְתַּכַּל דְּהָא תִּקּוּנָא דִלְתַתָּא אִשְׁתַּכְלַל כְּגַוְונָא דִלְעֵילָא, כְּדֵין אָמַר אָמוּתָה הַפָּעַם וְגו'. כִּי עוֹדְךָ חַי, דְּאִתְקָיְימַת בְּרָזָא דִּבְרִית קַדִּישָׁא, <Nonei></i>דְּאִקְרֵי חַי הָעוֹלָמִים, וּבְגִין כָּךְ כִּי עוֹדְךָ חָי. וְעַל דָּא בְּקַדְמִיתָא אָמַר, רַב עוֹד יוֹסֵף בְּנִי חָי, דְּאִצְטְרִיךְ לְמֵיקַם בְּרָזָא דְחַי, וְהָא אִתְּמָר.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, וַיְבָרֶךְ יַעֲקֹב אֶת פַּרְעֹה, אָמַר רִבִּי יוֹסֵי, פַּרְעֹה אַף עַל גַּב דְּאוּקְמוּהָ בְּרָזָא אוֹחֲרָא, סֶמֶךְ דְּקָא סַמְכִינָן בְּעַלְמָא.</p>\n<p>אֲבָל תָּא חֲזֵי, (שיר השירים א׳:ט׳) לְסוּסָתִי בְּרִכְבֵי פַרְעֹה דִּמִּיתִיךְ רַעֲיָתִי, תָּא חֲזֵי, אִית רְתִיכִין לִשְׂמָאלָא בְּרָזָא דְסִטְרָא אָחֳרָא, וְאִית רְתִיכִין לִימִינָא בְּרָזָא דִלְעֵילָא דִקְדּוּשָּׁה, וְאִלֵּין לָקֳבֵל אִלֵּין. אִלֵּין דְּרַחֲמֵי וְאִלֵּין דְּדִינָא.</p>\n<p>וְכַד קוּדְשָׁא בְּרִיךְ הוּא עָבַד דִּינָא בְּמִצְרָאֵי, כָּל דִּינָא דְּעָבִיד, כְּהַהוּא גַוְונָא דְּאִינוּן רְתִיכִין מַמָּשׁ, וּכְגַוְונָא דִילֵיהּ דְּהַהוּא סִטְרָא מַמָּשׁ. מַה הַהוּא סִטְרָא (ממש) קָטִיל וְאַפִּיק נִשְׁמָתִין, אוּף קוּדְשָׁא בְּרִיךְ הוּא עָבִיד בְּהַהוּא גַוְונָא מַמָּשׁ. דִּכְתִיב, (שמות י״ג:ט״ו) וַיַּהֲרֹג ה' כָּל בְּכוֹר, וְכֵן כֹּלָּא בְּמִצְרַיִם, בְּהַהוּא גַוְונָא מַמָּשׁ. וּבְגִין כָּךְ דִּמִיתִיךְ רַעֲיָתִי, כְּגַוְונָא דִילָהּ מַמָּשׁ לְקָטְלָא. דִּכְתִיב, כִּי אֲנִי ה' אֲנִי הוּא וְלא אַחֵר. וּלְזִמְנָא דְאָתֵי מַה כְּתִיב, (ישעיהו ס״ג:א׳) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגו'.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, וַיֵּשֶׁב יִשְׂרָאֵל בְּאֶרֶץ מִצְרַיִם בְּאֶרֶץ גּוֹשֶׁן וַיֵּאָחֲזוּ בָהּ וַיִּפְרוּ וַיִּרְבּוּ מְאֹד. וַיֵּאָחֲזוּ בָהּ, אַחְסָנַת עָלְמִין. וְיֵּאָחֲזוּ בָּהּ, דְּהָא לְהוֹן אִתְחֲזֵי, כְּמָה דְאוּקְמוּהָ. (ד\"א ל\"ג אמר רבי יוסי) וַיִּפְרוּ וַיִּרְבּוּ מְאֹד, ודַּאי, דְּהָא צַעֲרָא לָא שָׁרַאת בְּהוּ, וְקָיְימֵי בְּתַפְנוּקֵי עַלְמָא, וּבְגִין כָּךְ וַיִּפְרוּ וַיִּרְבּוּ מְאֹד. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן:</p>"],[9520011423,"<p><Nonesmall></small> וַיְחִי יַעֲקֹב בְּאֶרֶץ מִצְרַיִם שְׁבַע עֶשְׂרֵה שָׁנָה וגו'. אָמַר רִבִּי יוֹסֵי, לִבָּא חָמָא בִּנְבוּאָה, בְּמִצְרַיִם, דִּיהוֹן בְּנוֹהִי בְּכַמָּה גַּלָּוון, עַד הָכָא ועַד עִדָּנָא דְּקֵץ מְשִׁיחָא.</p>\n<p>ולָא מָטָא לִנְבוּאָה דְּויְחִי אֶלָּא בְּמִצְרַיִם. וְהִיא מַעַלְיָיתָא, נְבוּאָתָא מִדְּאִתְנַבִּיאוּ (ד\"א לא אתנביאו) אִתְנַבִּיאוּ דְּכַוָּותָה, וְלָא מָטָא לְהוּ שׁוּם אֵינִישׁ מִן בְּנִי נְבִיאָה, אֶלָּא הוּא וּמשֶׁה. בְּמשֶׁה כְּתִיב, (שמות ל״ג:כ׳) כִּי לא יִרְאַנִי הָאָדָם וָחָי. בְּיַעֲקֹב כְּתִיב, ויְחִי יַעֲקֹב. וַיְחִי, נְבוּאָתָה דְּנַחֲתָא מֵאַסְפַּקְלַרְיָאה (מאירתא) דְּנַהֲרָא.</p>\n<p>בָּעֵי לְמֵימַר (חפץ ההוא הוה בעינוהי) נְבוּאָן דְּגָלוּתָא דְּעַרְעָן לִבְנוֹהִי בְּאַרְעָא דִכְנָעַן וּבְכָל אַרְעָא דְאִתּוֹתַב בָּהּ. מֵאַרְעָא דְמִצְרַיִם הֲוָה תְּבִיר לִבֵּיהּ. דִּכְתִיב, (בראשית מ״ב:א׳) כִּי יֵשׁ שֶׁבֶר בְּמִצְרַיִם.</p>\n<p>וְעַל דָּא מָטָא, וַיְחִי יַעֲקֹב בְּמִצְרַיִם, וְלָא הֲוָה חָדֵי. (סי א') כִּי בְּאַרְעָא <Nonei></i>הַהִיא סְפֵיקָן דְּעַמִין, סַפִּרִין דְּכוּרְסֵי יְקָרָא. וְלָא מָטָא לְהוֹן שׁוּם אֵינִישׁ, לָא מִן עִלָּאָה וְלָא מִן תַּתָּאָה, אֶלָּא ח\"י. וְרָזָא דָא, כִּי לֹא יִרְאַנִי הָאָדָם וָחָי.</p>\n<p>כַּמָּה הוּא רָזָא עִלָּאָה בְּדָא קְרָא, וְאֲנַן חַבְרַיָיא תְּמֵיהִין עֲלַיְיהוּ, עַל וַיְחִי דְּדָכִיר עִמֵּיהּ יַעֲקֹב. הֲוָה לֵיהּ לְמֵימַר קַמֵּי יִשְׂרָאֵל. יִשְׂרָאֵל מִנַּיִן, דִּכְתִיב, (ירמיהו ב׳:ג׳) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית וְגו'. (שמות ד) בְּנִי בְּכוֹרִי יִשְׂרָאֵל. רִבִּי אֶלְעָזָר בְּרֵיהּ דְּרִבִּי שִׁמְעוֹן אָמַר, וְכִי לָא אָמַר קְרָא, (בראשית כ״ה:ל״ג) וַיִּמְכֹּר אֶת בְּכוֹרָתוֹ לְיַעֲקֹב.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן אֲבוּהָ, בְּעִידְנָא דְּהֲווּ יִשְׂרָאֵל קְשִׁיטִין וְזַכָּאִין וְעָבְדִין זְכוּ, וְלָא הֲווּ רְתִיתִין יִשְׂרָאֵל, אֶלָּא יַעֲקֹב לְחוּדֵיהּ. בְּדִין טָבָאן דְּעָבְדִין, הֲוָה לְמֶעְבַּד לְהוּ טָבָאן סַגִּיאִין דָּא בְּדָא.</p>\n<p>מִדְּחָבוּ, וְאִתְגְּלִיאוּ עַל חוֹבֵיהוֹן, וְעַל עוֹבָדֵיהוֹן בִּישִׁין, לָא הֲווּ סָבְלִין יָתֵיהּ, דְּלָא יֶהֶוְיָין לְעַלְמָא, בְּקוּשְׁטָא עַל חוֹבֵיהוֹן. וְעַל דָּא אָתֵי מְכִילְתָּא דְרַחֲמֵי וְדִינָא לְחוּד, יִשְׂרָאֵל, וְיַהֲבִית (וישראל יהבית) יַתְהוֹן בְּאַרְעָא גָּלוּתְהוֹן.</p>\n<p>יָאוֹת בָּעֵי בְּרִי, אֲבָל אִינִישׁ מִסְתַּכֵּל וְיִנְדַע יָתֵיהּ, יַעֲקֹב דְּמִתְלַף עִם וַיְחִי, קֹדֶשׁ. וְעַל דְּנָא רָזָא אָמְרִין, יַעֲקֹב בָּחַר יָתֵיהּ סַפִּירָא בְּכוּרְסֵי יְקָרָא.</p>\n<p>רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ישעיהו נ״ז:ט״ו) וְאֶת דַּכָּא וּשְׁפַל רוּחַ לְהַחֲיוֹת רוּחַ שְׁפָלִים וּלְהַחֲיוֹת לֵב נִדְכָּאִים. לֵב נִדְכָּאִים, דָּא יַעֲקֹב. כְּמָא דְאַתְּ אָמֵר, תְּחוֹת מִן דַּרְגָּא נְחִיתַת עֲלוֹהִי נְבִיאִין בִּרְכָאן בְּמִצְרַיִם.</p>\n<p>תָּנָא אָמַר רִבִּי אַבָּא, לִבָּא חָמָא, דְּיַעֲקֹב דְּהֲוָה בְּמִצְרַיִם לֵית נְבוּאָתֵיהּ מַעַלְיוּתָא. (ס\"א דארעא סניאה) אַרְעָא סַגִּיאָה.</p>\n<p>תָּא חֲזֵי, לָא זָכֵי לְבָרֵךְ לְחַד מִבְּנוֹהִי, וְלָא הֲוָה בִּידֵיהּ רוּחָא לְבָרֵךְ אֶלָּא בְּמִצְרַיִם, כַּד בָּרִיךְ יַתְהוֹן כָּל חַד וְחַד בְּרָזָא. וְרָזָא (בראשית מ״ב:א׳) וַיַּרְא יַעֲקֹב כִּי יֵשׁ שֶׁבֶר בְּמִצְרַיִם וַיֹּאמֶר יַעֲקֹב לְבָנָיו לָמָּה תִּתְרָאוּ. תָּא חֲזֵי, דְּלָא אִיתְיְיהִיבַת נְבוּאֲתָא, אֶלָּא לִתְבִירֵי לִבָּא. כְּמָא דְאַתְּ אָמֵר, (בראשית מ״ב:ב׳) רְדוּ שָׁמָּה וְשִׁבְרוּ לָנוּ מִשָּׁם וְנִחְיֶה וְלֹא נָמוּת.</p>\n<p>אָמַר רִבִּי יוֹסֵי, תְּחוֹת כָּרְסֵי יְקָרָא קַדִּישָׁא, יַעֲקֹב סַפִּיר, דְּאִיהִי מְכִילָתָא דְּדִינָא לְסִטְרֵיהּ, אֲתָא אָמַר, (בראשית ל״ב:כ״ט) לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְּךָ כִּי אִם יִשְׂרָאֵל כִּי שָׂרִיתָ עִם אֱלֹהִים וְעִם אֲנָשִׁים וַתּוּכָל. אַתְּ מַשְׁכַּח דְּיַעֲקֹב חָזָא לְסִטְרֵיהּ מְכִילָתָא דְּדִינָא, וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ כַּאֲשֶׁר עָבַר אֶת פְּנוּאֵל וְגו', וְרָזָא דְמִלָּה (ירמיהו ו׳:ד׳) אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְּלֵי עָרֶב.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, כַּד אִתְגְּלִיאוּ מִן יְרוּשְׁלֵם, וְאַעֲדִיאוּ תְּדִירָא, וְסָאִיב מְסַנְאָה יַת הֵיכָלָא. בְּעִדָּנָא הַהִיא לָא סוֹבְלַת מַלְכוּתָא לְיִשְׂרָאֵל עַל חוֹבֵיהוֹן, אֶלָּא יִשְׂרָאֵל. בְּגִין דְּהִיא מִתְּרֵי גִיסָא, רַחֲמֵי וְדִינָא.</p>\n<p>וּמִלָּה דְּלֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךָ כִּי אִם יִשְׂרָאֵל, כַּד אִתְפְּרִישׁ בִּסְבִירֵיהּ. יִשְׂרָאֵל יַעֲקֹב עִלָּאָה דָּא מִן דָּא, וּבְגִינֵהוֹן הֲוָה חוּטְרָא דְמשֶׁה גְּלִיפָא מִתְּרֵין סִטְרוֹי מִשְׁמֵיהּ קַדִּישָׁא, חַד רַחֲמֵי בְּדִינָא, וְחַד דִּינָא בְּדִינָא.</p>\n<p>וְרָזָא (במדבר כ״ג:כ״א) לֹא הִבִּיט אָוֶן בְּיַעֲקֹב וְלא רָאָה עָמָל בְּיִשְׂרָאֵל, מִדַּאֲנַן בְּגָלוּתָא, דְּחִיקָן בֵּין שָׂנְאֵי, וְאִסְתַּלִּיקַת מַטְרוֹנִיתָא מִן מַלְכָּא, וְאִתְרְחִיקַת מִנֵּיהּ, הוּא יַשְׁרֵי שְׁכִינְתָּא בֵּינָנָא וְיִפְרְקִינָנָא. וְרָזָא (ישעיהו מ״ה:י״ג) כֹּה אָמַר ה' מֶלֶךְ יִשְׂרָאֵל וְגוֹאֲלוֹ ה' צְבָאוֹת. וַיְחִי חַי, (ישעיהו ס״ו:א׳) כֹּה אָמַר ה' הַשָּׁמַיִם כִּסְאִי וְהָאָרֶץ הֲדוֹם רַגְלָי.</p>\n<p>בִּנְיָן עִלָּאָה, שְׁתֵּ\"י רַגְלַי חַי, לי' רַבָּתָא, י' לְח' זְעֵירְתָּא, ח' לְתיו, וי' לְו', ו' לְד', הֲדָא הוּא דְּנָפִיק מֵעִלָּאָה.</p>\n<p>תְּחוֹת כָּרְסֵיהּ יְקָרָא, מֵאֶבֶן טָבָא בְּאֶרֶץ מִצְרַיִם. הַיְינוּ דִּכְתִיב, (ישעיהו י״ט:כ״ב) וְנָגַף ה' אֶת מִצְרַיִם וְגו', י\"ב פְּרִישָׁא. (ישעיהו כ״ו:י״ט) כִּי טַל אוֹרוֹת טַלֶּךָ א' בְּגִין פְּרִישָׁא.</p>\n<p>וּבְגִין דָּא מִתְחַלַף כְּחֲדָא, ב' פְּרִישָׁא גָּלוּתָא, א' פְּרִישָׁא קַדְמַיְיתָא. תָּא חֲזֵי, מַאי דִכְתִיב, (ישעיהו ב׳:ה׳) בֵּית יַעֲקֹב לְכוּ וְנֵלְכָה בְּאוֹר ה', בְּגָלוּתָא, אַתְוָון דְּאִתְגְּזַר עֲלֵיהוֹן, עַל חוֹבֵיהוֹן, בְּקוּשְׁטָא בְּדִינָא הֲווּ, בְּאוֹרַיְיתָא תַּקַּנְתָּא, וְתִפְקוּן מִן חַמְרָא טִינָא, דְּהִיא גָלוּתָא, וְתַהֲכוּ לְנַהֲרָא דַּיְיָ.</p>\n<p>א' רְצוֹנוֹ לוֹמַר בָּאָרֶץ, אִתְצַפֵּי אֲתָא בְּתִיגְנָא דְּסִיפְרָא דְאוֹרַיְיתָא. וְאֲנָא אִתְפַּלִיג בָּאָרֶץ, בָּאָרֶץ אַתְּ מַשְׁכַּח בְּתִיגְנָא דְסִפְרָא דְאוֹרַיְיתָא, ר\"ץ מִתְלַפִּין כְּחֲדָא גָּלוּתָא. מַאי גָּלוּתָא דְמִצְרָאֵי. אַרְבַּע <Nonei></i>מְאָה שְׁנִין הֲוָה אָמַר לְאַבְרָהָם, דִּיהֵא גָּלוּתָא לִבְנוֹהִי בְּמִצְרָאֵי, וְכִי הֲוֵית מָנֵיתָא יַתְהוֹן, מָאתָן וְתִשְׁעִין שְׁנִין הֲווּ.</p>\n<p>תָּא חֲזֵי, וַיָּמָת יוֹסֵף בֶּן מֵאָה וְעֶשֶׂר שָׁנִים. רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ישעיה ו) הִנֵּה הָעַלְמָה הָרָה וְיוֹלֶדֶת בֵּן וְקָרָאת שְׁמוֹ עִמָּנוּאֵל, עִדּוּי וְלֵידָה, דְּאִתְמְלֵי לְגִלּוּיָאן וְעָקְתָן סַגִּיאִין וְעִידָן בִּישִׁין. וְאַף עַל גַּב דִּיְהוּ בְּאִלֵּין, מַטְרוּנִיתָא אִזְדַּעְזְעַת וְאִתְרַחֲקַת מִן בַּעֲלָהּ, תְּהֵא עִמָּנָא בְּגָלוּתָא, בֶּן מֵאָה וְעֶשֶׂר הֲוָה גִּלּוּפָא דְּאִתּוֹסַף, יִתְרְעֵי לְמֵימַר וְהֲוָה עָבַר מִן גָּלוּתָא מֵאָה וְעֶשֶׂר שְׁנִין, וּמָאתָן וְתִשְׁעִין, הֲוִי אַרְבַּע מְאָה שְׁנִין, וְלָא אִתְמְנֵי גָלוּתָא דְיַעֲקֹב, אֶלָּא מִדְּמִית יוֹסֵף, (והיינו דא על גבי דא דאמר ומעת הוסר התמיד ולתת שקוץ שומם וגו'.)</p>\n<p>וַיְּהִי יְמֵי יַעֲקֹב שְׁנֵי חַיָּיו שֶׁבַע שָׁנִים וְאַרְבָּעִים וּמְאַת שְׁנָה, הָכָא רָזָא בְּגָלוּתָא בְּמִנְיְינָא, תִּקוּנְתָּא יְהוֹן בְּנַיָיא דְּאִתְגַּלְּיָין בְּמִכִילָתָא דְּדִינָא תְּלָתָא גַּלָּוָון. קַדְמָאָה דְמִצְרָאֵי, דְּאִתְמְתַל בִּשְׁבַע שְׁנִין. רִבִּי חִיָּיא פָּתַח וְאָמַר, (שיר השירים ב׳:ז׳) הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַם בִּצְבָאוֹת אוֹ בְּאַיְלוֹת וְגו'.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר מֵהָכָא, (ירמיהו ל״א:ג׳) מֵרָחוֹק ה' נִרְאָה לִי וְאַהֲבַת עוֹלָם אֲהַבְתִּיךְ וְגו'. הָכָא רָזָא בְּגָלוּתָא תַּקַּנְתָּא יְהוֹן בְּנוֹהִי דְיִשְׂרָאֵל. מִשְׁתְּרֵי גַּלָּיָיא וְיִתְרְעֵי לְמֵימַר, יְהוֹן בְּנַיָא קַדִּישָׁא דְּאִתְגַּלָּוָון עַל חוֹבֵיהוֹן בְּדִינָא, שְׁנִין סַגִּיאִין יְהֵא. (ויקרא כ״ו:כ״א) שֶׁבַע כְּחַטֹּאתֵיכֶם, (בראשית ד׳:כ״ד) כִּי שִׁבְעָתַיִם יוּקַּם קָיִן, בְּגָלוּתָא קַדְמָאָה דְמִצְרָאֵי, דְּהִיא זְעֵירָא.</p>\n<p>תִּנְיָינָא, גָּלוּתָא דְשׁוֹפְטִים, דְּאִתְמְתַל לְאַרְבָּעִים שְׁנִין, בִּשְׁבַע דְּאִינְהוּ סַגִּיאֵי מִנֵּיהּ.</p>\n<p>תְּלִיתָאֵי, גָּלוּתָא דַאֲנַן בֵּיהּ אֲרִיכָא, דְּאִתְמְתַל לִמְאָה שְׁנִין, לְאַרְבְּעִין וְהַיְינוּ דָּא עַל גַּבֵּי עִלָאָה דְּאֲמָר (דניאל י״ב:י״א) וּמֵעֵת הוּסַר הַתָּמִיד וְלָתֵת שִׁקּוּץ שׁוֹמֵם וְגו':</p>"],[9520011424,"<p>וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת. רִבִּי חִזְקִיָּה אָמַר, חֲמָא דָא עַקְתָא דְגָלוּתָא דְּהֲוָה עָרְעָן לִבְנוֹהִי, קְרִיבָא אֲנַפְשֵׁיהּ וּדְחִיקַת לִמְמָת, לָא אִשְׁתָּאַר חַי, כַּד הֲוָה נָחִית מִדַרְגִין, בְּדִיל חוֹבֵיהוֹן דְּיִשְׂרָאֵל, לָא נָחִית עִמְּהוֹן בְּגָלוּתָא, זַכָּאָה חוּלְקֵהוֹן, דְּאִי לָא נָחִית עִמְּהוֹן בְּגָלוּתָא, אִשָׁתָּאֲרָן בֵּינֵי עַמְמַיָא, וְאַתְּ אֲמַרְתְּ (ישעיהו נ׳:ב׳) מַדּוּעַ בָּאתִי וְאֵין אִישׁ קָרָאתִי וְאֵין עוֹנְה. וְאֵין עוֹנֶה, דָּא יִשְׂרָאֵל, בָּאתִי וְאֵין אִישׁ, דָּא שְׁכִינָה. הַקָּצוֹר קָצְרָה יָדִי מִפְּדוּת וְאִם אֵין בִּי כֹּחַ לְהַצִּיל הֵן בְּגַעֲרָתִי אַחֲרִיב יָם אָשִׂים נְהָרוֹת מִדְבָּר. קוּדְשָׁא בְּרִיךְ הוּא יָהַב חוּלָקָא לְיִשְׂרָאֵל דְּלָא יִשְׁלוֹט רַבְרְבָנָא אָחֳרָא בְהוֹן. נָחֲתוּ לְגָלוּתָא, שְׁכִינְתָּא עִמְּהוֹן וְהוּא רָחִיק מִמַּטְרוֹנִיתָא:</p>"],[9520011425,"<p>וַיִּקְרָא לִבְנוֹ לְיוֹסֵף וַיֹּאמֶר לוֹ אִם נָא מָצָאתִי חֵן בְּעֵינֶיךָ, חָקַר יַת בְּנוֹהִי כֻּלְּהוֹן, וְאָמַר לְהוֹן, עַקְתָן סַגִּיאִין, בִּישִׁין רַבְרְבִין, חָמִית לְמֵיעַל לִבְרֵיכוֹן אַשְׁכְּחָן רַחֲמֵי עִלָּאֵי.</p>\n<p>וְאִי אַתּוּן בָּעָאן לְמֵיפַּק מִכָּל עָקְתָא, קַיְימוּ לִי, וְהֲבוּ בֵּינָנָא רִבּוֹן עָלְמָא וְתַעַבְדוּן קְשׁוֹט וְדִינָא, וְתֶהוֵי כַּאֲבָהַתְכוֹן, וּפַקִּידֵי בְּכָל דָּר וְדָר דְּיֵיתֵי בַּתְרֵיכוֹן, וְאִי אַתּוּן בָּעָאן לְמֶעְבַּד הָכִי, תִּפְקוּן מִכָּל עַקְתָא דְּיֵיתֵי עֲלֵיכוֹן.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, (עמוס ה׳:ט״ו) וְהַצִּיגוּ בַשַּׁעַר מִשְׁפָּט אוּלַי יֶחנַן ה' אֱלֹהֵי צְבָאוֹת שְׁאֵרִית יוֹסֵף. (דאתקריאו בנוהי ישראל כלהון יוסף)</p>\n<p>וְאִי תַעַבְדוּן הָכִי, לָא תִקְבְּרוּן חַד מִן בְּרִי, אֶלָּא אִתִּי תְּתוּבוּן לְאַרְעֲכוֹן בִּשְׁלָמָא.</p>\n<p>הֲדָא הוּא דִכְתִיב, (בראשית כ״ד:ב׳) שִׂים נָא יָדְךָ תַּחַת יְרֵכִי, מַהוּ יָדְךָ. פָּתַח וְאָמַר, (תהילים מ״ה:ד׳) חֲגוֹר חַרְבְּךָ עַל יָרֵךְ גִּבּוֹר הוֹדְךָ וַהֲדָרֶךָ, סַיְיפָא דְקָאי בָּהּ חֶסֶד וְאֱמֶת, תְּרֵין סְפִירָן סְפִירָן, וְלָא שָׁבְקִין דָּא לְדָא. וְעַל דָּא אָמַר, (תהילים פ״ט:ט״ו) חֶסֶד וֶאֱמֶת יְקַדְמוּ פָנֶיךָ, (איכה ד׳:ט״ז) פְּנֵי ה' חִלְּקָם. וְאִי הֲווּ טָבָאן בְּנוֹהִי, וְעֲבִידוּ מַה דְּקָיְימוּ, לָא מִית חַד מִבְּנַיְיהוּ בְּמִצְרָאֵי, דְּכָל טַב וְטַב דְּגָזִיר שְׁמָא דֵּאלָהָא עַל אֵינָשָׁא, לָא הֲוֵי אֶלָּא עַל דִּיהוֹן טָבִין. וְאִי לָא, לָא. כְּמָה דְּאָמַר דָוִד, (מלכים א ב׳:ד׳) לְמַעַן יָקִים ה' אֶת דְּבָרוֹ אֲשֶׁר דִּבֶּר עָלַי לֵאמֹר אִם יִשְׁמְרוּ בָנֶיךָ אֶת דַּרְכָּם לָלֶכֶת לְפָנַי בֶּאֱמֶת. וְאִי לָא, לָא (מייתי ברכאן דאמר עליהון).</p>\n<p>תָּא חֲזֵי, כַּמָּה הוּא עָדִיף רוּחָא דְּאַבָּא מֵרוּחָא דְּבָרָא. דְּרוּחָא דְּאַבָּא הוּא רוּחָא דִבְרָא, רוּחָא מֵרוּחָא סָלְקָא. וְאִי סַיְיעַת אֲוִירָא אָחֳרָא בְּרוּחָא, לָא נָפִיק שְׁלִים. <Nonei></i>דְּהָא חָסִיר הוּא בְּהַאי אֲוִירָא. וְהַיְינוּ (ירמיהו ב׳:כ״ד) פֶּרֶה לִמֻּד מִדְבָּר בְּאַוַּת נַפְשָׁהּ שָׁאֲפָה רוּחַ.</p>\n<p>תָּנָא, (ויקרא ע\"ה ע\"ב, ע\"ש כי שם בא כל הענין בשלמותו) רַב הַמְנוּנָא סָבָא אֲזַל לְקַפּוֹטְקִיָּיא, עָאל לְקַמַּייהוּ רַב יִיִסָא סָבָא. אָמַר לֵיהּ, בְּמַאי עַסְקִיתוּ. וַוי לֵיהּ, וַוי לְנַפְשֵׁיהּ. אִי אִשְׁתְּלַף רוּחָא דִּמְסָאֲבָא דְּאִשְׁתַּכַּח עִמֵּיהּ וְאוֹרִית לֵיהּ לִבְרֵיהּ. וְהַאי אִיהוּ דְּקוּדְשָׁא בְּרִיךְ הוּא לֵית לֵיהּ חוּלָקָא. שָׁבִיק לֵיהּ חוּלָקָא שָׁבִיק לֵיהּ לְשֵׁיצָאָה לֵיהּ לְעַלְמָא דְאָתֵי. אָמַר לֵיהּ, מְנָא לָךְ הָא. אָמַר לֵיהּ, הָכָא אוֹלִיפְנָא, דְּהַאי יְרוּתָא בִּישְׁתָּא, אַחְסְנִין (אחרי מות עו ע\"א) כֻּלְּהוּ בְּנוֹי אִי לָא יְתוּבוּן, דְהָא לֵית מִלָּה קָיְימָא קַמֵי תְּשׁוּבָה. וְאֲנָא הָכִי אוֹלִיפְנָא, דְּהָא אַסְוָותָא דָא יַהֲבוּ לִי זִמְנָא חָדָא, דְּהֲוֵינָא רְשִׁים בְּאַנְפִּי, וְיוֹמָא חַד הֲוֵינָא אָזִיל בְּאָרְחָא וְעַרְעָנָא בְּחַד זַכָּאָה, וְעַל יְדוֹי אִתְעֲבַר מִנָאי הַהוּא רְשִׁימָא. אָמַר לֵיהּ מַה שְּׁמָךְ, אָמַר לֵיהּ אֶלְעָזָר, וְקָרֵינָא לֵיהּ אֶלְעָזָר אָחֳרָא, אָמַר לֵיהּ בְּרִיךְ רַחֲמָנָא דְּחָמֵינָא לָךְ, זַכָּאָה חוּלָקָךְ בְּעַלְמָא דֵין, וּבְעַלְמָא דְאָתֵי:</p>\n<p>וַיֹּאמֶר הִשָּׁבְעָה לִי וְגו'. רִבִּי חִזְקִיָּה פָּתַח וְאָמַר, (ישעיהו ס״ב:ח׳) נִשְׁבַּע ה' בִּימִינוֹ וּבִזְרוֹעַ עֻזּוֹ, קִּיֵּים קוּדְשָׁא בְּרִיךְ הוּא דְּיִפּוּק לְיִשְׂרָאֵל מִן גָּלוּתָא דִלְהוֹן, וְדָא קִּיֵּים לְהוֹן, קְיָים, דְּלָא יִשְׁבּוֹק לוֹן בְּאַרַע שַׂנְאֵיהוֹן.</p>\n<p>(בראשית ל״ב:כ״ז) וַיֹּאמֶר שַׁלְחֵנִי כִּי עָלָה הַשָּׁחַר וַיֹּאמֶר לא אֲשַׁלֵּחֲךָ כִּי אִם בֵּרַכְתָּנִי. מַאן בֵּרַכְתָּנִי. יָהַב לוֹן גָּלוּתָא, וְקִּיֵּים לוֹן דְּיִפְקוּן מִנֵּיהּ.</p>\n<p>תָּנָא, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לִבְרֵיהוֹן דְּיִשְׂרָאֵל, דִּיהוֹן כָּל חַד וְחַד תְּחוֹת כָּרְסֵיהּ, וִיהוֹן מַעַלְיָין מִכָּל עִלָּאֵי, בְּגִין דָּא תִּשְׁכַּח וא\"ו אֲרִיכָא. קִּיֵּים קוּדְשָׁא בְּרִיךְ הוּא לִשְׁלֵמוּתָא דְּו' דְּר\"א וּבְגִין שִׁתָּא וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה. סְגִיד יִשְׂרָאֵל דְּלֵיתֵי מְשִׁיחָא בְּסוֹף מִנְיָינָא דָא, וְתִשְׁרֵי שְׁכִינְתָּא עִמְּהוֹן.</p>"],[9520011426,"<p>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וַיֹּאמֶר לְיוֹסֵף הִנֵּה אָבִיךָ חוֹלֶה וְגו': מַתְנִיתִין, אָמַר רִבִּי חִזְקִיָּה, לָא אֲתָא קְרָא לְאַשְׁמוּעִינָן דְּעָבַד, אֶלָּא אֲתָא קְרָא לְאַתְיָא מַה דְּיֶהוֵי בְּסוֹף גָּלוּתָא, כָּל אִלֵּין לְסוֹף מִנְיָינָא דְאִתְמְנֵי. צָבֵי לְמֵימַר דְּיֵיתֵי מְשִׁיחָא, וְיֵימָא לֵיהּ אָבוּךְ דְּבִשְׁמַיָיא בָּהִיל לִסְבַר אַפָּךְ, סָפִין לְקִצָּא דִמְשִׁיחָא. יְהֵא רַעֲוָא מִן אֱלֹהָא דִשְׁמַיָא, דְּיִסַּב בְּרֵיהּ דְּאַסְגִּיאוּ בְּגָלוּתָא, וּמִדְּאִתְנְשִׁיאוּ בְּהוּ, דְּנָשֵׁי יַתְהוֹן קוּדְשָׁא בְּרִיךְ הוּא בְּחוֹבֵיהוֹן בְּקוּשְׁטָא.</p>\n<p>כַּד אֲתָא רִבִּי אַבָּא אָמַר, לָאו לִדְרָשָׁא קָא אֲתִינָא, חֲשׁוֹב רָזָא דְמִלְּתָא (בראשית ל׳:כ״ד) יוֹסֵף ה' לִי בֶּן אַחֵר, כִּדְפָרִישְׁנָא לְעֵיל, הַאי שְׁמֵיהּ קַדִּישָׁא בְּיוֹסֵף, יה\"ו יֹאמַר, הָא אֲבוּךְ מָארֵי עַלְמָא, דְאָתֵי לְמֶעְבַּד טָבָא לִבְרֵיהּ, דְּיִפְקוּן מִן גָּלוּתָא דִּלְהוֹן. וְאִי אַתְּ לָא רָעֵי בְּקוּשְׁטָךְ, רִבּוּעָא ידו\"ד אֶחָד יַעֲבֵד יָתָךְ, וְיָדְעֵי דְּתֵיתוּב מַטְרוֹנִיתָא לְאַתְרָא.</p>\n<p>דַּאֲבָהֳתָנָא אִינוּן רְתִיכִין דִּלְעֵילָא, (בראשית י״ז:כ״ב) וַיַּעַל אֱלהִים מֵעַל אַבְרָהָם, אֲבָהָן שׁוֹקֵי עַלְמָא, (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב חֶסֶד לְאַבְרָהָם, תָּנָא דְיֵיתֵי מְשִׁיחָא.</p>"],[9520011427,"<p>רִבִּי יוֹסֵי פָּתַח וְאָמַר, (זכריה ד) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה' לֹא יוֹם וְלֹא לַיְלָה וְהָיָה לְעֵת עֶרֶב יִהְיֶה אוֹר. רוֹצֶה לְמֵימַר, תְּרֵין מְעַרְעִין בִּישִׁין דְּאָתָן לִבְנוֹהִי לְמֶהוֵי בְּגָלוּתָא בְּאַרַע שַׂנְאֵיהוֹן, וְלָא יִסְתְּכֵי בְּהוֹן, כַּמָּה שְׁנִין סַגִּיאִין, עַל חוֹבֵיהוֹן בְּקוּשְׁטָא, הָכִי יִזְנַח יַתְהוֹן בְּאַרַע שַׂנְאֵיהוֹן. וְיִסַּב בְּנַיְיהוּ דְּאַרַע לְהוֹן בִּישִׁין אִלֵּין, וְיַדְבֵּר לְהוֹן לַאֲרַע טַב כְּפִירוּשָׁא דִקְרָא.</p>\n<p>וְהֲוָה תְּרֵי רַבְרְבָן סַגִּיאִין מַעַלְיָיאן הֲוָה מְטַרְקָן תְּחוֹת כָּרְסֵי יְקָרָא, דְּאַפַּטְרוֹפָּא דְּיִשְׂרָאֵל מְכִילָתָא חֲמִישָׁאָה, בְּדִיל דִּיְהוֹן בְּגָלוּתָא כָּל עִדָּנָא הָדֵין, וְאַרַע דְּנָשֵׁי יַתְהוֹן בְּאַרַע שַׂנְאֵיהוֹן.</p>\n<p>וְהוּא תְּרֵין מְכִילָתָן, בִּתְרֵין סָפִין, נָפַק חָדָא וּמַלִּיל לָקֳבֵל רִבּוֹן עָלְמָא, וְיָהִיב לֵיהּ רְשׁוּ דִּימַלֵּל כָּל מַאן דְּבָעֵי, וְחָזֵי בְּיִשְׂרָאֵל מִן גִּיסָא חָדָא לְמִגְזַר בְּהוֹן בְּיִשְׂרָאֵל, דְּיִפְקוּן מִן גָּלוּתָא, בְּדִין אֲבָהַתְהוֹן. וּמִן גִּיסָא אַחֲרִינָא, רָעָא לְמִגְזַר עֲלֵיהוֹן, בְּדִיל חוֹבֵיהוֹן, דְּאָמְרוּ עֲלַיְיהוּ בִּישָׁא סַגִּיאָה. הָא ד' מְכִילָתָן, וְלָא הֲוָה בְּהוֹן מְכִילָתָא חֲמִישָׁאָה אַפַּטְרוֹפָּא דְיִשְׂרָאֵל, וּמַלִּילוּ כָּל דִּרְעוּ.</p>\n<p><Nonei></i>עַד דְּמָטָא לְוַותְהוֹן מְכִילָתָא חֲמִישָׁאָה, וְהֲוָה בְּכָרְסֵי יְקָרָא מִן שְׁמָא קַדִּישָׁא, וְאָמַר עַל בְּנוֹהִי דְיִשְׂרָאֵל טַב, וְלָא הֲווּ רַתְיָין תְּרֵין מְכִילָתָן קַמַּיְיתָא לְמַלָּלָא קַמֵּיהּ, בְּדִין מְכִילָתָא חֲמִישָׁאָה דְּאִתְמְתַל לְלֵילְיָא, וְנָפַק לִנְהוֹרָא דִלְהוֹן. וְעַל דָּא פָּתַח, וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה' לֹא יוֹם וְלֹא לַיְלָה וְהָיָה לְעֵת עֶרֶב יִהְיֶה אוֹר.</p>\n<p>תָּנִינָא (בראשית א׳:ה׳) וַיִּקְרָא אֱלהִים לָאוֹר יוֹם וְלַחשֶׁךְ קָרָא לָיְלָה, וְהָתָם אָמַר וְחשֶׁךְ עַל פְּנֵי תְהוֹם, וְקַשְׁיָא דִידֵיהּ אֲדִידֵיהּ. אֲתָא רִבִּי אֶלְעָזָר לְרִבִּי שִׁמְעוֹן אֲבוֹי, וְאָמַר לֵיהּ אַבָּא מָארִי, מַאי דָא. אָמַר לֵיהּ, מִבְּרֵאשִׁית עַד ו' דוֹרוֹת בָּרָא ידו\"ד אֶחָד, צָבֵי לְמֵימַר, ו' דִּשְׁמֵיהּ, יָהַב בֵּיהּ רוּחַ חָכְמָה, עַד הָכָא לָא הֲוָה מִנְדַּע מַהוּ חשֶׁךְ. קָם רִבִּי אֶלְעָזָר וְנָשַׁק יְדוֹי דְּאֲבוֹי.</p>\n<p>קָם רִבִּי אַבָּא וְשָׁאַל, מַאי חשֶׁךְ. אִסְתַּחֲרוּ חַבְרַיָא וְלָא מָטוּ מַאי דְּשָׁאֲלוּ, עֲבָדוּ עוֹבָדָא, וּמָטָא קָלָא מִן קֳדָם רִבּוֹן עַלְמָא, בְּהָאי קְרָא, (איוב י׳:כ״ב) אֶרֶץ עֵיפָתָה וְגו' צַלְמָוֶת וְלֹא סְדָרִים, וַתּוֹפַע כְּמוֹ אוֹפֶל, גֵּיהִנֹּם מִקַּמֵּי דְּאִתְבְּרֵי עַלְמָא, הֲוָה גָּנִיז לְרַשִּׁיעַיָּא, וַוי לְהוֹן לְחַיָּיבַיָא, דִּיהוֹן כַּד יַעֲבִיד אֱלָהָא יַת אִלֵּין, (ישעיהו ס׳:ב׳) כִּי הִנֵּה הַחשֶׁךְ יְכַסֶּה אֶרֶץ וַעֲרָפֶל לְאוּמִּים וְעָלַיִךְ יִזְרַח יְיָ וּכְבוֹדוֹ עָלַיִךְ יֵרָאֶה. זַכָּאָה חוּלְקֵהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא לָא בָּרָא לְהוֹן דָּא, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ אַשְׁרֵי הָעָם שֶׁיְיָ אֱלהָיו:</p>"],[9520011428,"<p>וַיַּגֵּד לְיַעֲקֹב וַיֹּאמֶר הִנֵּה בִּנְךָ יוֹסֵף בָּא אֵלֶיךָ. רִבִּי יוֹסֵי אָמַר, מַלְאָכָא הוּא, דְּהֲוָה עָתִיד לְמֵימַר טַב עַל בְּנֵי יִשְׂרָאֵל, כַּד יְתִיבוּן לְקוּדְשָׁא בְּרִיךְ הוּא, בְּכָל עָקַתְהוֹן, כַּד יֵיתֵי קִצָּא דִמְשִׁיחָא, בְּכָל עָקְתָא דְּתֵיתֵי עֲלֵיהוֹן, יֵימְרוּן לִמְכִילָתָא בְּרִיךְ אָתִי לְוָתָךְ, וְיִתְפָּרְקוּן טָבָאי.</p>\n<p>זַכָּאָה חוּלְקֵהוֹן דְּיִשְׂרָאֵל, דְּאִתְקְרִיאוּ בְּנוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִינוּן כְּמַלְאָכַיָיא, (איוב ל״ח:ז׳) וַיָּרִיעוּ כָּל בְּנֵי אֱלהִים, הוי\"ה מַאי.</p>\n<p>תָּא חֲזֵי, מִנַּיִן שֶׁקָּרָא קוּדְשָׁא בְּרִיךְ הוּא לְיַעֲקֹב אֵ\"ל, אַתְּ בְּעִלָּאָה, וְאֲנָא אֱהֵא בְּתַתָּאָה, (נ\"א את תהא בתתאה, ואנא אהא אלהא בעלאה), מַאי קָא מַיְירֵי. (בראשית י״ז:כ״ב) וַיַּעַל אֱלֹהִים מֵעַל אַבְרָהָם, אֲבָהָתָן אִינוּן רְתִיכָאן דְּקוּדְשָׁא בְּרִיךְ הוּא. תָּנָא, (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב חֶסֶד לְאַבְרָהָם, הָא תְּרֵין סְפִירָן, בִּתְרֵין רְתִיכָן, רַבְרְבָן עִלָּאִין.</p>\n<p>תְּלִיתָאָה יִצְחָק, מַאי (בראשית ל״א:נ״ג) וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. וּבְגִין פַּחַד יִצְחָק דְּהֲוָה סְפִירָה, וְקוּדְשָׁא בְּרִיךְ הוּא דְּהוּא כָּרְסֵי יְקָרָא רְתִיכָא עִלָּאָה, וּסְפִירָה דְיִצְחָק הִיא מֵעִלָּאָה, מְפָרְשָׁא יַתִּיר מִכָּל סְפִירָן דַּאֲבָהָתָא, הֲדָא הוּא דִכְתִיב וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק.</p>\n<p>רִבִּי אַבָּא פָּתַח וְאָמַר, (בראשית ל״א:נ״ג) אֱלהֵי אַבְרָהָם וֵאלֹהֵי נָחוֹר יִשְׁפְּטוּ בֵּינֵינוּ אֱלֹהֵי אֲבִיהֶם, וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק, מֵהַאי קְרָא אַתְּ יָכִיל לְמִנְדַע דָּא.</p>"],[9520011429,"<p>וַיִּתְחַזֵּק יִשְׂרָאֵל וַיֵּשֶׁב עַל הַמִּטָּה, וְרָזָא דִקְרָא, (דניאל י״ב:א׳) בָּעֵת הַהִיא יַעֲמוֹד מִיכָאֵל הַשַּׂר הַגָּדוֹל הָעוֹמֵד עַל בְּנִי עַמְּךָ וְהָיְתָה עֵת צָרָה. רִבִּי שִׁמְעוֹן אָמַר, דָּא גְּבוּרַת יְדָא דְמִיכָאֵל רַבְרְבָא. וַיֵּשֶׁב עַל הַמִּטָּה, כְּמָּה לֵיהּ הֲוָה מִקַּדְּמַת דְּנָא סְגִיד. לְמַאן הֲוָה סְגִיד, סְגִיד לְעַרְסָא, הֲוָה עַרְסָא פְּתִיחָא מִנֵּיהּ. לְמָהוּלְתָּא הֲוָה סְגִיד, דְּהָא הֲוַת חֲבִיבָא מִינֵּיהּ.</p>\n<p>(מלאכי ב׳:י״א) כִּי חִלֵּל יְהוּדָה קֹדֶשׁ ה' אֲשֶׁר אָהֵב וּבָעַל בַּת אֵל נִכָר, כַּד אִסְתַּלַּק זִיוֵיהּ מִנֵּיהּ עַל חוֹבֵיהוֹן, לָא הֲוָה לֵיהּ לְמֵיקַם קַמֵּיהּ, וְאִתָּרְכַת מַטְרוֹנִיתָא מִן מַלְכָּא, בְּדִיל דְּלָא יָכְלָא לְשָׁבְקָא לָהּ לִבְרָהָא בֵּין עַמִין לְמִקְטַלְּהוֹן, וְהֲוָה בְּאַרְעָא קַדִּישָׁא הוּא, בְּהָא דִּיהוֹן עַמִּין נוּכְרָאִין מִן עַמֵּיהּ. צָבֵי לְמֵימַר, עָאל שְׁכִינְתָּא בֵּינֵיהוֹן בְּגָלוּתָא, וְעִדָּנָא דְלָא הֲוָה בְּאַרְעָא, וְהִיא בַּאֲרַע עַמְּמִין, בְּזִיוָא דְיִשְׂרָאֵל, אִסְתַּמָּרוּ עַמְּמַיָּא דִי בְסַחְרָנִיהוֹן.</p>\n<p>תָּאנָא, אָמַר רִבִּי יוֹסֵי, תְּרֵין רַבְרְבִין הֲווּ תְּחוֹת כָּרְסֵי יְקָרָא קַדִּישָׁא, וְהָא בִּשְׁמֵיהּ חַד מָאנִי בְּעַרְסָא, דְּהֲוָה שָׁדֵי אֲגוֹזֵּיהּ דְּהֵיכָלָא. וְהָא אֲנַן בְּגָלוּתָא, לָא אִשְׁתָּאַר בֵּינָנָא אֶלָּא דָּא דְּבֵּינֵי דְּזִינֵיהּ, וְהוּא חָתוּךְ מִן שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>הֲדָא הוּא דִכְתִיב, (שמותכג) הִנֵּה אָנֹכִי שׁוֹלֵחַ מַלְאָךְ לְפָנְיךָ לִשְׁמָרְךָ וְגו', לָא לְמַלָּלָא הָכִי, אֶלָּא בְּעַלְמָא דְאָתֵי, כַּד פָּרִישְׁנָא בְּסִטְרִין וְהוּא צוּרִין בְאָרְחָא, אֲנָא שָׁרֵינָא שְׁכִינְתָּא בֵּינִיכוֹן לְמָארֵיהוֹן בְּגָלוּתָא וְהִיא נָטְרַת יַתְכוֹן, עַד <Nonei></i>דְּתֵיתֵי יַתְכוֹן לְאַרְעֲכוֹן, כְּמָה דְּהֲוִיתוּן מִקַּדְמַת דְּנָא. אֲשֶׁר הֲכִינוֹתִי, מוֹתָבָן מִקַּדְמַת דְּנָא.</p>\n<p>דָּא שְׁכִינְתָּא מִן מטטרו\"ן. וְאִתָּרְכַת מַטְרוֹנִיתָא מִן מַלְכָּא, עַד דְּתֵיתוּב לְאַתְרָהָא, וְרָזָא (דברים ג׳:י״א) כִּי רַק עוֹג מֶלֶךְ הַבָּשָׁן נִשְׁאָר מִיֶּתֶר הָרְפָאִים הִנֵּה עַרְשׂוֹ עֶרֶשׂ בַּרְזֶל הֲלא הִוא בְּרַבַּת בְּנֵי עַמּוֹן, כִּדְפָרִישְׁנָא בְּאַתְרֵיהּ.</p>\n<p>וְאָרְחָא, דְּאִתְמְתַל לְגָלוּתָא, נָטַר יַתְהוֹן בְּגָלוּתָא, עַל עַקְתָא דְּתֵתֵי עֲלֵיכוֹן, עַד דְּיֵיתֵי וְיֵיעוּל יַתְכוֹן לְאַרְעָא, דְּקַיַּים לַאֲבָהַתְכוֹן דְּאִתְנַטְרַת.</p>\n<p>רַבְרְבָא תִּנְיָנָא הוּא, דְּהוּא תְּחוֹת כָּרְסֵי קַדִּישָׁא, דְּשָׁרֵי בְּגַזֵּיהּ דְּהֵיכָלָא הוּא נוּרִיאֵל. דְּהָא רַבְרְבָא דְיִשְׂרָאֵל דְּאִתְמַנֵּי עֲלֵיהוֹן, בְּכָל עִידָן דַּהֲוַת מַטְרוֹנִיתָא עִם מַלְכָּא, הֲוָה נָפֵיק וְעָאל קֳדָמֵיהוֹן, מטטרו\"ן. וְהוּא, קָבֵיל פּוּלְחַנְהוֹן לְקוּדְשָׁא בְּרִיךְ הוּא, כְּנוּרָא. כַּד אִתְבַּטֵיל נוּרָא וְאִתְגַּלִיאוּ, אִסְתַּלַּק זִיוָהּ, וְאִסְתַּלְּקָא מַטְרוֹנִיתָא מִן מַלְכָּא.</p>\n<p>רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר (רות ג׳:י״ג) לִינִי הַלַּיְלָה וְהָיָה בַּבֹּקֶר אִם יִגְאָלֵךְ טוֹב יִגְאָל, אָמַר רִבִּי יוֹסֵי, שַׁלִּיט רַחֲמֵי עַל דִּינָא. (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, טוֹב וְאוֹר שָׁוִין, דְּהוּא מַבּוּעוֹי דְּנַחֲלִין, דְּנָפַק מִנְּהוֹן יַמָּא וְנַחֲלָא דִּבְעָלְמָא.</p>\n<p>תָּנָא אָמַר רִבִּי שִׁמְעוֹן, זִמְנָא חָדָא סָלִיקְנָא וְנָחִיתְנָא לְאַנְהָרָא בְּמַבּוּעֵי דְּנַחֲלִין, וְסָלִיק בַּתְרָאי רִבִּי אַבָּא. אָמַר לִי, בְּמַאי עַסְקִיתוּ. אָמָרִית לֵיהּ, בְּהַאי קְרָא (קהלת א׳:ז׳) דְּכָל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְהַיָּם אֵינְנּוּ מָלֵא. מִזִּיוִיהּ אִתְבְּרִיאוּ כָּל רַבְרְבַיָיא דְּמִן עַלְמָא, וּמִן זִיוֵיהּ אִתְנְבִיעוּ כָּל נַחֲלַיָיא, נַחֲלַיָיא הֲווּ אִינוּן לְהַאי קְרָא, דְּמֵאִיכֵי בְּהַאי גָלוּתָא, דְּהָא חֲשׁוֹכָא כָּמוּפְלָא, חִבָּתָא דְּאִמָּא עָבִיד לְהוּ, וְאִי לָאו, נַחֲלָא עָבִיד בְּרַתֵּיהּ. רַבְרְבָא תָּנִינתָא הוּא, הוּא תְּחוֹת קַדִּישָׁא, דְּגָנֵי אֲגְנִים דְּהֵיכָלָא. דְּהָא רַבְרְבָא דְיִשְׂרָאֵל דְּאִתְמַנֵּי עֲלֵיהוֹן, בְּכָל עִידָן דְּהֲוַת מַטְרוֹנִיתָא עִם מַלְכָּא, הֲוָה נָפִיק וְעָאל קֳדָמֵיהוֹן מטטרו\"ן. וְהוּא קָבִּיל פּוּלְחַנְהוֹן לְקוּדְשָׁא בְּרִיךְ הוּא כְּנוּרָא. כַּד אִתְבַּטִיל נוּרָא וְאִתְגַּלִיאוּ, אִסְתַּלַּק זִיוָהּ, וְאִסְתַּלְּקָא מַטְרוֹנִיתָא מִן מַלְכָּא. הָא לָא הֲוָה שְׁלִים עַד דְּיֵיתֵי גִּיסָא אָחֳרָא, דְּלָא הֲוָה בְּגָלוּתָא מָנִיתָא.</p>"],[9520011430,"<p>וּשְׁמָהָן דְּאִתְקְרִיאַת יַד, הִיא מַבּוּעָא לְכֹלָּא, וְתִשְׁכַּח יַד הוי\"ה, (ישעיהו נ״ט:א׳) הֵן לָא קָצְרַת יַד הוי\"ה, דְּלָא אִדְכַּר יָדָא אֶלָּא בִּשְׁמָא דְּחַד.</p>\n<p>אֲתָא רִבִּי אֶלְעָזָר, וְשָׁאַל לְרִבִּי שִׁמְעוֹן אֲבוֹי, וּבְכָה וְאָמַר לֵיהּ, גַּלֵּי לִי הַאי רָזָא אַבָּא מָארִי. אָמַר לֵיהּ בְּהַאי קְרָא אִתְגְּלִי לָךְ, (שמות י״ז:ט״ז) כִּי יָד עַל כֵּס יָהּ מִלְחָמָה לַיְיָ, כֵּס בְּגִין הוי\"ה, שַׁלִּיט רַחֲמֵי עַל דִּינָא. צָבֵי לְמֵימַר, יְהֵא רַעֲוָא דִּיְהֵא לְעַלְמָא בְּאֲתַר גְּבוּרָת, יַד יְיָ רַבָּתָא קְרָבָא דְּהֲוַת בְּמִצְרַיִם, וְאִי לָאו הֲווּ בְּדִינֵי.</p>\n<p>וְיֵיתֵי מְשִׁיחָא, יֵיתֵי בְּחַדְתּוּ בִּידָא רַבָּתָא, וְיִגַּח קְרָבָא בַּעֲמָלֵק. (שמות י״ג:ט׳) בְּחוֹזֶק יָד הוֹצִיאֲךָ ה' מִמִּצְרָיִם, וְכַד יֵיתֵי שְׁמָא דְיַד בְּתוּקְפָא יְדָא לְחוּדֵיהּ, הוּא בְּעִידָנָא, דְּיַגִּיחַ קְרָבָא בַּעֲמָלֵק, לֵיתֵי מְשִׁיחָא. רִבִּי אֶלְעָזָר מְסַיֵּיעַ, (זכריה י״ד:ג׳) וְיָצָא יְיָ וְנִלְחַם בַּגּוֹיִם הָהֵם כְּיוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב. כ\"ס בְּגִין ידו\"ד.</p>\n<p>תָּא חֲזֵי, כַּמָּה הִיא יְדָא רַבָּתָא דְּלָא מָטָא לְהַאי יָדָא עִלָּאָה, לַאֲבָהָן רַבְרְבָא לָא אֲגְנִים. וּבְדָא יָדָא נָפְקוּ מִמִּצְרַיִם, בְּגִין דְּמִשְׁוְיָין שָׁוִין, מַנִּי ד' לְד', שָׁוִין דָּא דְּרָע, שְׁמָא דְּיָדָא רַבָּתָא, דְיִפוּק מִן אִינוּן שָׁוִין בְּאַתְוַותְהוֹן דְּמִנְיָינֵיהוֹן כְּמִנְיָינֵיהוֹן, דְּקִבְּלָא תְּרֵין יַד, תְּרֵין.</p>\n<p>כֵּיצַד לָא אִתְמְנָעוּ דָּא מִן דָּא, וְלָא שָׁוִין. אִתְפְּרַשׁ תְּרֵין אִלֵּין בְּרִיךְ הוּא דִּבְאַתְוַותְהוֹן סַיְיעָאן יַד בַּעֲלָהּ ה', תְּרֵין לְאָב מִנְיָנֵיהוֹן מִתְפָּרַשׁ. מֵאִלֵּין אִתְבְּרִיאוּ שְׁמַיָא וְאַרְעָא וּדְעִמֵּיהּ. וְאִינוּן סְפִירָא קַדְמָאָה, דְּהִיא כִּתְרָא עִלָּאָה. תִּנְיָנָא, (משלי ט״ו:ג׳) בְּכָל מָקוֹם עֵינֵי ה' צוֹפוֹת רָעִים וְטוֹבִים. תְּלִיתָאָה, הֵם מְסַיַּיעְתָּן לִשְׁמָא חַד ו' דְּעֲבַד כַּמָּה אַתְוָון בְּאַרְעָא דְמִצְרַיִם.</p>"],[9520011431,"<p><Nonei></i>וַיֹּאמֶר יַעֲקֹב אֶל יוֹסֵף אֵל שַׁדַּי נִרְאָה אֵלַי בְּלוּז בְּאֶרֶץ כְּנָעַן. רִבִּי אַבָּא אָמַר, לוּז דָּא יְרוּשָׁלַ ם עִלָּאָה, דְּאַשְׁרָאָה שְׁכִינְתָּא בֵּינָהָא. אָמַר יַעֲקֹב עִלָּאָה לְתַתָּא, הַב לִי בִּרְכָתָא דְּהוּא בָּעֵי, לְאַנְפִּישׁ יַתְכוֹן אֲנָא, וּלְמִיתַּן יַת אַרְעָא לִבְנֵיכוֹן. לוּז זוֹ יְרוּשָׁלַ ם עִלָּאָה, קוּדְשָׁא בְּרִיךְ הוּא, הַב רַבְרְבָא דְּהַוְויָן בְּרָכָה דָּא עַל יְדֵיהּ, בְּאַרְעָא רָבְיָיא, אֲבָל בְּרָא, לְאַרְעָא אָחֳרָא, לָא יְהֵא בִּרְכָתָא.</p>\n<p>רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (משלי כ״ז:י״ד) מְבָרֵךְ רֵעֵהוּ בְּקוֹל גָּדוֹל בַּבֹּקֶר הַשְׁכֵּם קְלָלָה תֵּחָשֶׁב לוֹ, קוּדְשָׁא בְּרִיךְ הוּא קָרָא לְיִשְׂרָאֵל אַחִים וְרֵעִים. מַאי בִּרְכָתָא יָהַב לוֹן, דִּיהוֹן הַאי עַמָּא דַּכְיָא תְּחוֹת יְדֵיהּ, וְלִמֶהֱוֵי עֲלֵיהוֹן נָטִיר.</p>\n<p>זַכָּאָה חוּלְקֵהוֹן דְּהַאי עַמָּא דַכְיָא, דְּהוּא עֲלֵיהוֹן, דְּאִקְרֵי בָנִים חֲבִיבִים יַתִּיר מֵעִלָּאָה, כְּתִיב, (דברים ד) בָּנִים אַתֶּם לַה', כֹּלָּא בְּדִיל דָּא. מַאי הוּא, בְּדִיל דְּאִשְׁתְּלִים שְׁמָא בְּחוֹתָמָא דִלְהוֹן, דְּאִינוּן גְּזִירִין.</p>\n<p>תָּא חֲזֵי, בְּאַנְפּוֹי דְּאֵינָשָׁא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְחַסְרָא יוּ\"ד מִנֵּיהּ, וְלָא אִשְׁתְּלִים. אֲתָא אַבְרָהָם וְחִבֵּב לְקוּדְשָׁא בְּרִיךְ הוּא, וְאָמַר לֵיהּ בָּךְ אִשְׁתְּלִים שְׁמָא, וְאִתְגְּזַר, וְאִשְׁתְּלִים שְׁמָא בְּיוּ\"ד דְּמִילָה. בְּאַנְפּוֹי דְּאֶנָּשָׁא שי\"ן דְּשד\"י, וְד', חָסֵר יו\"ד, אִשְׁתְּלִים בְּיו\"ד דְּמִילָה, וּכְדֵין אִקְרוּן בָּנִים לַה', בְּנִין קַדִּישִׁין.</p>\n<p>וְכַד מְסָאֲבִין לֵיהּ לְהַאי אָת קַיָּימָא קַדִּישָׁא, וְעֲאִיל לֵיהּ לִרְשׁוּ אָחֳרָא, סָלִיק מִנֵּיהּ הַאי קִדּוּשָׁא דְּחוֹתָמָא, וְהוּא כְּמָה דְחָרִיב עַלְמָא, וְסָאִיב חוֹתָמָא, דְּאִשְׁתְּלִים בֵּיהּ שְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְהָא הוּא חָרִיב עַלְמָא.</p>\n<p>רִבִּי אַבָּא הֲוָה אָזִיל מִקַּפּוֹטְקִיָּא, וְהֲוָה עִמֵּיהּ רִבִּי יוֹסֵי. עַד דְּהֲווּ אָזְלֵי, חָמוּ חַד בַּר נָשׁ דְּהֲוָה אָתֵי, וּרְשִׁימָא חַד בְּאַנְפּוֹי, אֲבָל וַוי לוֹן לְחַיָּיבַיָא, דִימוּתוּן בְּלָא תְּשׁוּבָה, דְּלָא יַעֲדֵי מִנֵּיהּ רְשִׁימָא, לָא בְּעַלְמָא דֵין, וְלָא בְּעַלְמָא דְאָתֵי:</p>"],[9520011432,"<p>וַיֹּאמֶר אֵלַי הִנְּנִי מַפְרְךָ וְהִרְבֵּיתִיךָ. רִבִּי אַבָּא פָּתַח וְאָמַר, הַאי קְרָא (ישעיהו כ״ט:כ״ב) לא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחוָרוּ. וְכִי אֵינִישׁ דְּאָמַר טַב לְבַּר נָשׁ כַּוָּותֵיהּ. אִי לָא יַשְׁלִים מַה דְּאָמַר, אַפּוֹהִי מִתְבַּיְישָׁן, עַל אַחַת כַּמָּה וְכַמָּה מִן עִלָּאֵי לְבַּר נָשׁ, דְּאִי לָא מַיְיתֵי כָּל טַב דְּאָמַר עַל בְּנוֹהִי, אַנְפּוֹהִי מִתְבַּיְישָׁן.</p>\n<p>אָמַר קוּדְשָׁא בְּרִיךְ הוּא לֵיהּ, אֲנָא יִשְׂרָאֵל עִלָּאָה, דְּאֲנָא מַפְשִׁינָךְ וְאַסְגִּינָךְ. הַאי בִּרְכָתָא דְּיָהִיב לִי, וְאֶתֵּן יַת אַרְעָא הָדָא לִבְרֵיכוֹן, לָא הֲוָה בְּאַרְעָא, לָא הֲוָה עִמְּהוֹן. כַּד יֵיתֵי קִיצָא דִמְשִׁיחָא וְיִשְׁתְּלִים, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, לא עַתָּה יֵבוֹשׁ יַעֲקֹב, כְּעַן (לא) אַנְפוֹי דְיַעֲקֹב דִּלְעֵילָא, לָא מִתְבַּיְישָׁן מִדַּאֲמַר לְהוֹן אֶתֵּן, אֲרֵי עַד כְּעַן לָא הֲווּ בִּידֵיהּ, וְהֲווּ אַנְפּוֹהִי מִתְבַּיְישָׁן, כְּעַן דִּילֵיהּ מִסְתַּיֵּיעַ מִן קֳדָם מָארֵי שְׁמַיָא וְאַרְעָא.</p>\n<p>כְּמָה דְאַמְרִינָן, אֲגָחְנָא דַּעֲמָלֵק, כַּד יִשְׁתְּלִים קִיצָא, לָא יְהֵא אֶלָּא בִּתְקוֹף יְדָא, כְּמָה דְּהֲוִית בְּיוֹם קְרָב, וְיָצָא ה' וְנִלְחַם בַּגּוֹיִם הָהֵם, דִּידֵיהּ וְלָא אָחֳרָא:</p>"],[9520011433,"<p>וְעַתָּה שְׁנֵי בָנְיךָ הַנּוֹלָדִים לְךָ, דָּא יִשְׂרָאֵל לְתַתָּא, דְּאַתְרֵיהוֹן בְּגָלוּתָא, בְּנוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִתְיְילִידוּ בֵּינִי עַמְמַיָא. תָּנָא אָמַר רִבִּי יוֹסֵי, יִשְׂרָאֵל כַּד יְהוֹן בְּאַרְעָא קַדִּישָׁא דְיִשְׂרָאֵל, דָּר בְּאַרְעָא, כַּד יֵיתֵי מְשִׁיחָא, יְהוֹן עִם אֲחוּהוֹן דִּילָווּן בָּתְרֵיהוֹן. דְּלָא אִתְקְרֵי גָּלוּת, אֶלָּא לְמַאן דְּאִיהוּ דָּר בְּאַרְעָא נוּכְרָאָה, אִינוּן אִתְקַרְיָין גָּלְיָין. (ויקרא כו)</p>\n<p>וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב, וא\"ו יְתֵירָה, תֵּיתֵי וא\"ו דְּאִסְתַּלְּקַת כַּד אִתְחָרִיב בֵּיתָא, וּתְהֵא סִיּוּעָא לְיַעֲקֹב, כַּד יְהֵא דָא, וִיהֵא לִבְרָא קַדִּישָׁא אַרְעָא אַחְסָנַת עָלַם, וִיהוֹן בְּנוֹהִי בְּאַרְעֲהוֹן, דְּדָארוּ מִקַּדְּמַת דְּנָא בְּאַרְעֲהוֹן, זַכָּאָה חוּלְקֵהוֹן.</p>\n<p>כְּעַן בָּרְיָא, דְּהֲוָה עַרְעָן לְהוֹן, תְּהוֹן אָזְלִין רַבְרְבִין דְּאִתְגְּלִיאוּ מִן לְבַר לְאַרְעָא וְאִתְנְשִׁיאוּ, וְאַנְפִּישׁוּ. וְיֵימָא יַעֲקֹב עִלָּאָה לְתַתָּא, בָּרֵי דִּילָךְ דְּאִינוּן לְבַר לְאַרְעָא דְּאִתְיְילִידוּ בְּגָלוּתָא, בְּכָל אַרְעָא וְאַרְעָא, עַד דְּאֲנָא אִיעוֹל לְמִצְרָאֵי, וְאַעֲבִיד לְהוֹן דִּינָא <Nonei></i>עַל חוֹבֵיהוֹן, לָאו אֲנָא מַסְקִית בְּרָךְ, דְּאִתְבְּרִיאוּ בְּגָלוּתָא, לְבַר לְאַרְעָא בְּאַרְעָא רְחִיקָא. וְאַף עַל גַּב דְּאִינוּן סַגִּיאִין, וְאִתְנְשִׁיאוּ, דִּילִי אִינוּן. כַּד חֲזֵיתִי דָּא גָּלוּתָא דִּלְהוֹן, וְאַסֵיתִי לְכֵיבֵיהוֹן, וְשָׁמְעִית קָלֵיהוֹן. רְאוּבֵן, (בראשית כ״ט:ל״ג) כִּי רָאָה ה' אֶת עָנְיִי. שִׁמְעוֹן, כִּי שָׁמַע ה' כִּי שְׂנוּאָה אָנֹכִי, וְחָשִׁיב בְּלִבָּךְ, כְּאִילּוּ יֶהֶוְיָין קֳדָמַי אִינוּן, וּמִדִּנְתוּב מִמִּצְרָאֵי, מִלְּמֶעְבַּד דִּינָא, נָסִיק יַתְהוֹן מֵאֲרַע גָּלוּתָא.</p>\n<p>רִבִּי אַבָּא אָמַר, מֵהָכָא (ישעיהו ס״ו:כ׳) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה'. צָבֵי לְמֵימַר, כַּד יְהֵא קוּדְשָׁא בְּרִיךְ הוּא בְּדִינָא בְּמִצְרָאֵי, בְּעִדָּנָא הַהִיא יֵיתוּן כָּל עַמְּמַיָא מִנְחָה, כַּד שְׁמָעוּ שְׁמוּעָה דְּקוּדְשָׁא בְּרִיךְ הוּא, הַיְינוּ (ישעיהו ב׳:ב׳) וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם.</p>\n<p>תָּנָא, אָמַר רִבִּי שִׁמְעוֹן, עָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְמֶיעְבַּד לְכָל זַכָּאָה וְזַכָּאָה, חוּפָּה בִּיְרוּשָׁלַ ם, (ירמיהו ט״ז:ט׳) קוֹל שָׂשׂוֹן וְקוֹל שִׂמְחָה קוֹל חָתָן וְקוֹל כַּלָּה, כַּד תִּיתוּב מַטְרוֹנִיתָא לְמַלְכָּא, וְעָבִיד לָהּ אֵרוּסִין, הֲדָא הוּא דִכְתִיב, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה וְגו' בְּיוֹם חֲתוּנָתוֹ וּבְיוֹם שִׂמְחַת לִבּוֹ. בְּיוֹם חֲתוּנָתוֹ זֶה מַתַּן תּוֹרָה, וּבְיוֹם שִׂמְחַת לִבּוֹ זֶה בִּנְיַן בֵּית הַמִּקְדָּשׁ, שֶׁיִּבָּנֶה בִּמְהֵרָה בְיָמֵינוּ:</p>\n<p>וּמוֹלַדְתְּךָ אֲשֶׁר הוֹלַדְתָּ אַחֲרֵיהֶם לְךָ יִהְיוּ, דָּא יִשְׂרָאֵל לְתַתָּא, לַאֲבָהָן דְּאִינוּן רְתִיכִין, תְּהֵא שְׁמָהַתְהוֹן בְּרָזָא דְּאִתְיַילִידוּ לְבָתַר דְּנָן, עַל שְׁמָא דַּאֲחֵיהוֹן יְהוֹן מַקְרִיבִין בְּאַחְסָנָא דִלְהוֹן.</p>\n<p>תָּאנָא, אָמַר רִבִּי שִׁמְעוֹן, וּמוֹלַדְתְּךָ, דָּא יְרוּשְׁלַם דִּלְתַתָּא, (ויקרא יח) מוֹלֶדֶת בַּיִת בְּפָרָשַׁת עֲרָיוֹת, יְרוּשָׁלַ ם לְתַתָּא, גּוּבְרִין דְּאִתְיְילִידוּ דָּא יְרוּשָׁלַ ם, בָּתַר דְּנָא, דִּיתוּבוּן עַלְמָא לְמָארֵי שְׁמַיָא בִּירוּשָׁלַם, כַּד גִּיּוֹרִין לָא אִתְקָרוּן אֶלָּא עַל שְׁמָהָן, דְּהוּא בַּר יִשְׂרָאֵל, וְלָא יִתְקָרוּן כַּד אֲבָהַתְהוֹן, גִּיּוֹרָא מִקַּפּוֹטְקִיָּא, אֶלָּא בְּהָא יִשְׂרָאֵל.</p>\n<p>לְךָ יִהְיוּ, צָבֵי לְמֵימַר, עַל שְׁמֵיהוֹן דְּיִשְׂרָאֵל יִתְקָרוּן, עַל שֵׁם אֲחֵיהוֹן יִקָּרְאוּ בְּנַחֲלָתָם, וְכַד תָּבוּ לָא יִתְחַסְנוּן אִלֵּין עִם יִשְׂרָאֵל בְּאַרְעָא, וְיִסַּב כָּל שִׁבְטָא וְשִׁבְטָא, דִּידֵיהּ וְגוּבְרִין מִנְּהוֹן, כָּל חָדָא לְפוּם מִנְיָינֵיהּ.</p>"],[9520011434,"<p>וַאֲנִי בְּבֹאִי מִפַּדַּן מֵתָה עָלַי רָחֵל בַּדֶּרֶךְ וְגו', רִבִּי אַבָּא פָּתַח, (ירמיהו ל״א:ט״ו) כֹּה אָמַר ה' קוֹל בְּרָמָה נִשְׁמָע וְגו', מַה כְּתִיב בַּתְרֵיהּ, כֹּה אָמַר ה' מִנְּעִי קוֹלֵךְ מִבֶּכִי וְעֵינַיִךְ מִדִּמְעָה כִּי יֵשׁ שָׂכָר לִפְעוּלָתֵךְ וְגו' וְשָׁבוּ בָנִים לִגְבוּלָם, לא אָמַר וְיָשׁוּבוּ, אֶלָּא וְשָׁבוּ, כְּבָר שָׁבוּ.</p>\n<p>תָּא חֲזֵי, אָמַר רִבִּי אֶלְעָזָר, בְּשַׁעְתָּא דִיהֵא דִינָא עַל טוּרָא, תִּתְעַטַּר מַטְרוֹנִיתָא עַל טוּרָא, וְהִיא סָבְרַת דִּבְנֵיהוֹן אָבְדִין בְּדִינָא, וְרָזָא (ישעיהו נ״ד:א׳) רָנִי עֲקָרָה לֹא יָלָדָה פִּצְחִי רִנָּה וְצַהֲלִי וְגו'. תָּנָא, סַגְיָין יְהוֹן בְּנִי כֻּרְסְיָיא מִן דִּידָהּ. הֲדָא הוּא דִכְתִיב, כִּי רַבִּים בְּנֵי שׁוֹמֵמָה מִבְּנִי בְעוּלָה, תִיתוּב מַטְרוֹנִיתָא לְבַעֲלָהּ, (זכריה י״ד:ט׳) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>מִן קַדְמַת דְּנָא, תֵּימָא מַטְרוֹנִיתָא לְקוּדְשָׁא בְּרִיךְ הוּא, בְּנַיָיא דִילִי אָן. יֵימָא לָהּ, בְּדִינָא. הִיא תִּסְבַּר דְּאָבְדִין בְּדִינָא, וּבָכָה עַל דִּינָא לִבְנַיָא דִידָהּ, כִּי אֲרֵי סַגִּי אִית לָךְ לְמֵיסַב מִנִּי בְּדִלְהוֹן, דְּהֲוַת עִמְּהוֹן, וְהָא תָּבוּ מֵאַרְעָא דְּשַׂנְאָה.</p>\n<p>וְכִי לָא הֲוָה יָדַע יוֹסֵף דְּמֵתָה אִמֵּיהּ, תַּמָן הֲוָה עִמָּהּ כַּד מֵתָה. אֶלָּא יֹאמַר יִשְׂרָאֵל עִלָּאָה, כַּד נֵיתֵי מִפְרָקְנֵיהוֹן דְּיִשְׂרָאֵל, תִּתְעַר מַטְרוֹנִיתָא, וְתִתְעַר כְּנֶסֶת יִשְׂרָאֵל, וְתִגַּח קְרָבָא עִם עַמָּמִין, וִימוּתוּן מִנְהוֹן, וְיִתְקָרְבוּן בִּזְעֵיר לְמֵיתֵי אַרְעָא. יֵימַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, כַּד הִיא בָּכָה. לָא תִדְחֲלִי, אַגְרָא לְהוֹן בְּנַיָיא דְּמִיתָן עַל שְׁמִי, אָחֳרָנִין הָא תָּבוּ, אִינוּן יְתוּבוּן לְחַיֵּי מֵיתַיָיא.</p>\n<p>מֵתָה עָלַי רָחֵל, מֵתָה עַל יִיחוּד שְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְעַל דָּא אִתְּמָר בְּעוֹד כִּבְרַת אֶרֶץ לָבֹא, דְּמִיתוּ עַל יִיחוּד שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לְבַר לְאַרְעָא, בְּאַרְעָא דָּא, לָא יָמוּת חַד מִנְּהוֹן.</p>\n<p>תָּנָא, אָמַר רִבִּי אַבָּא, עֲתִידִין יִשְׂרָאֵל לַאֲגָחָא קְרָבָא בְּאָרְחָא דְאֶפְרָת, וִימוּתוּן עַמָּא סַגְיָא מִנְּהוֹן, וּבָתַר כֵּן לְחַיֵּי מֵיתַיָא יְקוּמוּן. וְיַתִּיר שָׁלְטָנָא יְהֵא לְכוֹן דְּמִיתִין בְּאָרְחָא הָדֵין, מִכָּל דִּיהֵא קָדָמֵיהוֹן בִּיְרוּשָׁלַ ם.</p>\n<p>וְלָמָּה אִתְקְרֵי שְׁמָא דְּאַתְרָא קַדִּישָׁא, <Nonei></i>דְּאַתְרָא הָדֵין לָחֶם. בְּדִיל דְּהוּא מִן שְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ, דִּימוּתוּן תַּמָּן עַל שְׁמֵיהּ, י\"ד, דִּימוּתוּן תַּמָּן עַל שְׁמֵיהּ י\"ה, לֶחֶם בְּגָלוּתָא, בְּדִיל דְּהוּא מִן שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא:</p>"],[9520011435,"<p>וַיַּרְא יִשְׂרָאֵל אֶת בְּנֵי יוֹסֵף וַיּאמֶר מִי אֵלֶּה. רִבִּי אַבָּא פָּתַח, (ישעיהו מ״ט:כ״א) וְאָמַרְתְּ בִּלְבָבֵךְ מִי יָלַד לִי אֶת אֵלֶּה, מַאי קָא מַיְירֵי, יִשְׂרָאֵל לְתַתָּא, חָזֵי דְּיֵיתוּן בְּנוֹהִי דְיִשְׂרָאֵל קָדָמֵיהּ, כַּד יֵיתוּן (ישעיהו י״א:י״א) מֵעֵילָם וּמִשִּׁנְעָר וּמֵחֲמָת וּמֵאִיֵּי הַיָּם וְאַכְנָשׁוּ כֻּלְּהוּ וִיהוֹן סַגִּיאִין. תֵּימָא שְׁכִינְתָּא מֵאָן אִינוּן כֻּלְּהוֹן, וְלָא בְּהוֹן פְּסוּל מִבְּנִי נוּכְרָאָה. יִיִמְרוּן לֵיהּ, אֲנַחְנָא כֻּלָּנָא מִבֵּרַךְ, וְלֵית בְּנָא נוּכְרָאָה בַּהֲדָן, דְּיִתְפָּרְשׁוּן דָּא מִן דָּא וְכָרַת לְהוֹן כְּחֲדָא, וְיִתְגַּיְירוּן, יְתוּבוּן גִּיּוּרִין עִם יִשְׂרָאֵל, וִיהוֹן כְּחֲדָא.</p>\n<p>תָּנָא, קָשִׁים גֵּרִים לְיִשְׂרָאֵל כְּסַפַּחַת בְּעוֹר הַחַי, לְאַרְעֲהוֹן. כְּתִיב (ישעיה יא) כִּי יְרַחֵם ה' אֶת יַעֲקֹב וּבָחַר עוֹד בִּיְרוּשָׁלַ ם וְנִלְוָה הַגֵּר עֲלֵיהֶם וְנִסְפְּחוּ עַל בֵּית יַעֲקֹב, כַּד יְתוּבוּן לְאַרְעֲהוֹן בְּרָיָא, וִיהֶוְיָין רְחִימוּ בְהוֹן, (זכריה י״ד:ט׳) יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד, יִתְלַוּוּן גִּיּוֹרִין עִם יִשְׂרָאֵל וִיהֶוְויָין לְהוֹן כְּעוּמְקָא בְּבִשְׂרֵיהוֹן.</p>\n<p>וְכָל כָּךְ לָמָּה. תָּא שְׁמַע, אָמַר רִבִּי שִׁמְעוֹן, עַל תְּחוּמִין דְּאַרְעָא, דְּכָל חַד יְהֵא רַעֲוָא לְמֵידַר בְּאַרְעָא דְיִשְׂרָאֵל, וְתִסְתָּעַר דִּיּוּרִין. כְּתִיב, (ישעיהו נ״ד:ב׳) וִיתֵדוֹתַיִךְ חֲזֵקִי, צָבֵי לְמֵימַר, סִיכְיָא דְּהַוְיָין עִמָּךְ מֵעִקָּרָא, אַתְקִיף יַתְהוֹן, וְסַיַּיע יַתְהוֹן יַתִּיר מִשְׁאָר עַמָּמִין. כִּבְיָכוֹל דְּאַתְּ סָכֵי לְאִתְתַּקְּפָא יַתְהוֹן בְּכָל עַמְּמַיָא אָחֳרָא, וִיהוֹן סַגִּיאִין:</p>"],[9520011436,"<p>וַיֹּאמֶר יוֹסֵף אֶל אָבִיו בָּנַי הֵם אֲשֶׁר נָתַן לִי אֱלֹהִים בָּזֶה, רִבִּי שִׁמְעוֹן תָּאנִי מֵהָכָא, (דברים ד׳:מ״ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם משֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל, יֹאמַר יִשְׂרָאֵל לְתַתָּא, כַּד יִשְׂרָאֵל עֲלֵיהוֹן לְעֵילָא, בָּנַי אִינוּן, דְּיָהַב לִי קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא, כַּמָּה יַתְהוֹן וְנִימוּסֵיהוֹן קְשִׁיטִין, בְּנִימוּסֵי אוֹרַיְיתָא (דאתיהיבת להון. תא חזי, כד יהון ישראל תחות גדפי שכינתא, אורייתא) דִלְהוֹן אִתְקְרִיאַת זֶה, הֲדָא הוּא דִכְתִיב, (שמות ט״ו:ב׳) זֶה אֵלִי וְאַנְוֵהוּ, וּבְכָל עִדָּן דְּלָא הֲוָה דָּוִד מְמַלֵּל תְּחוֹת גַּדְפֵי שְׁכִינְתָּא דָא מִלְּתָא, אֶלָּא אִתְנַבֵּי מַה דְּלֶיהוֵי, אִתְקָרֵינָא זֹאת.</p>\n<p>רַב נַחְמָן אָמַר מֵהָכָא, (תהילים כ״ז:ג׳) אִם תַּחֲנְה עָלַי מַחֲנְה לא יִירָא לִבִּי וְגו' בְּזֹאת אֲנִי בּוֹטֵחַ, זֹאת דָּא אוֹרַיְיתָא תְּהֵא לֵייתֵי מְשִׁיחָא, וּבְגִין דָּא, (שיר השירים ב׳:י״ב) וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ. עַל מָה אִתְמַתְלַת אוֹרַיְיתָא, לְגוֹזָלָא. מַה גּוֹזָלָא קָלֵיהּ עָרֵב, אַף פִּתְגָמֵי אוֹרַיְיתָא קָלֵיהּ עָרֵב, וְדָא קָלָא יְהֵא לֵייתֵי מְשִׁיחָא, לְיוֹמָא דְּדִינָא.</p>\n<p>תָּנָא, הַנִּצָּנִים נִרְאוּ בָאָרֶץ עֵת הַזָּמִיר הִגִּיעַ וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ. הַנִּצָּנִים, דָּא אֲבָהָתָן דְּמֶרְכָּבָה, דְּמִן עַלְמָא יְקוּמוּן וְיִתְחֲזוּ.</p>\n<p>עֵת הַזָּמִיר הִגִּיעַ, תּוּשְׁבַּחְתָּא דִּישַׁבְּחוּן לֵיוָאֵי, כַּד יְתוּבוּן לְפוּלְחָנֵיהוֹן כִּדְבְּקַדְמִיתָא. וְקוֹל הַתּוֹר, אֲשֶׁר נָתַן לִי אֱלֹהִים בָּזֶה, פִּתְגָמֵי דְּאוֹרַיְיתָא, דְּאִינוּן עֲרֵבִין כְּקָלָא דְּתוֹרָא, דָּא זֶ\"ה זֹא\"ת תּוֹר שָׁוִין.</p>\n<p>מַאי קָא מַיְירֵי. וְרָזָא דְמִלְּתָא, בְּעִדָּנָא דְּלָא תֶהֶוְיָין תְּחוֹת גַּדְפֵי שְׁכִינְתָּא, א' דִּלְזֹאת נָחִית, וְהוּא מִתְּחוֹת לְכֹלָּא, וּסְלִיקַת ה', דְּזֶה אֵלִי וְאַנְוֵהוּ, מִדְּחָרַב בֵּיתָא, דְּה\"א, לָא יָכְלָא לָדוּר וּלְמֶהֱוֵי בֵּין עַמָּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, דְּה\"א קַדִּישָׁא חֲתוּכָא מִן שְׁמָא. ה\"א אֶלֶף, ה\"א עֲדִיפַת בִּקְדוּשָּׁה, א' עֲדִיפַת לְאַתְוָון. כַּד יְתוּבוּן יִשְׂרָאֵל לְאַרְעֲהוֹן, ה\"א קַדִּישָׁא דְּהוּא חֲתוּכָא מִן שְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא, תֵּיתוּב בָּזֶה וְיִפּוּק (מיומא דדינא, והא' תקבל) מִנְיָינָא תַּקַנְתָּא.</p>\n<p>רִבִּי אַבָּא פָּתַח וְאָמַר, (ישעיהו מ׳:י״ב) מִי מָדַד בְּשָׁעֳלוֹ מַיִם וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן, זֶה תּוֹר, שָׁוִין כִּבְיָכוֹל, ז' לְר', ר' לְת', ו' לְה', זַרְתָּא דְקוּדְשָׁא בְּרִיךְ הוּא, בְּשִׁית מְאָה וְשִׁבְעִין שְׁנִין, מֵהָכָא מִן שְׁמַיָא, וְעַד אַרְעָא, כֵּיצַד (ז\"ה) תּוֹ\"ר, זֶרֶת ו\"ה ה\"ו תר\"ז, אִתְקַדְּמַת ה' לְו'. וְאִתְקַּדְמַת ו' לְת', ת' לְר', ר' לְז', (שמות כ״ח:ט״ז) רָבוּעַ יִהְיֶה כָּפוּל זֶרֶת אָרְכּוֹ וְזֶרֶת רָחְבּוֹ כָּפוּל.</p>\n<p>וַיֹּאמֶר קָחֶם נָא אֵלַי וַאֲבָרַכֵם, יֹאמַר מִדַּהֲווֹ בְּפִתְגָּמֵי אוֹרַיְיתָא מִתְעַסְּקִין, (והוה) וְהוּא דָא מְכִילָתָא בֵּין חַכִּימַיְהוּ, אֲבָרַכִינוּן, וְרָזָא (בראשית ל״ב:כ״ח-כ״ט) וַיֹּאמֶר אֵלָיו מַה שְּׁמֶךָ וַיֹּאמֶר יַעֲקֹב. וַיֹּאמֶר <Nonei></i>לָמָּה זֶה תִּשְׁאַל לִשְׁמִי, וַיֹּאמֶר יַעֲקֹב, מִנְיָינָא דָא, לְמִנְיָינָא קַדְמִיתָא דְּקַמֵּיהּ, כְּדְפָרִישְׁנָא בְּאַתְרֵיהּ.</p>\n<p>וְרָזָא אָחֳרָא, וַיִּשְׁאַל יַעֲקֹב וְגו' וַיֹּאמֶר לָמָּה זֶה תִּשְׁאַל לִשְׁמִי וַיְבָרֶךְ אוֹתוֹ שָׁם, הָא לָא עָתִיד, אֶלָּא בִּזְכוּתָא דְזֶה, לְבָרְכֵהוֹן.</p>\n<p>וְרָזָא סַגִּיאָה תִּנְיָנָא, בְּאַתְרָה דְּהַאי קְרָא, אֲבָל לָא אָתֵינָא לְקַמָּן דְּלָא לְאַשְׁמוּעִינָן הַאי קְרָא דְּאָמַרְנָא, מִקַּמֵיהּ דְּאֲמִינָא לָךְ דְּאִתְקְרִיאַת אוֹרַיְיתָא זֶה. כְּתִיב, (שופטים ה׳:ה׳) זֶה סִינַי מִפְּנֵי ה' אֱלֹהֵי יִשְׂרָאֵל, כַּד אִתְיְיהִיבַת אוֹרַיְיתָא עַל יְדָא דְמשֶׁה, (שמות ל״ב:כ״ז) כִּי זֶה משֶׁה הָאִישׁ (שמות ט״ו:ב׳) זֶה אֵלִי וְאַנְוִהוּ, אוֹרַיְיתָא הֲוָה נָחֲתַת מִן קַמֵּי אֱלָהָא דְיִשְׂרָאֵל.</p>"],[9520011437,"<p>וְעֵינֵי יִשְׂרָאֵל כָּבְדוּ מִזֹּקֶן וְגו', וּבְגִין דָּא, לָא אַתְּ מַשְׁכַּח דְּכַוָּותֵיהּ, וְכַד יְהוֹן בְּגָלוּתָא כָּל זִמְנָא חֲרוּבָא הָדִין, סִיבוּ. לָא יָכְלִין לְמֶחזֵי אַפֵּי שְׁכִינְתָּא, עַד דְּתֵיתֵי רוּחָא אָחֳרָא בְּהוֹן.</p>\n<p>מִקַּדְּמַת דְּנָא אִסְתָּאִיבוּ בַּאֲרַע עַמְּמַיָא, וְלָא הֲווּ בְּנִימוּסֵי אוֹרַיְיתָא. כְּמָּה דִּיְהוֹן כָּהִיל לְמֵיהַךְ, וְתָבוּ עִדָּנָא סַגֵּי בֵּינִי נְכְרָאִין, דָּרָא בָּתַר דָּרָא, וְאוֹלִיפוּ מִן אָרְחֵיהוֹן, כַּד יְתוּבוּן אַפֵּי שְׁכִינְתָּא לְאַרְעֲהוֹן, בְּקַדְמִיתָא לָא יָכְלִין לְמֶחמֵי אַפִּי שְׁכִינְתָּא, עַד דְּיָהִיב קוּדְשָׁא בְּרִיךְ הוּא רוּחָא דִילֵיהּ לְהוֹן.</p>\n<p>רִבִּי חִיָּיא פָּתַח, (יחזקאל ל״ו:כ״ז) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם, לְבָתַר וְעָשִׂיתִי אֶת אֲשֶׁר בְּחוּקַּי תֵּלֵכוּ וּמִשְׁפָּטַי תִּשְׁמְרוּ וַעֲשִׂיתֶם, מִן בָּתַר דְּיָהַב רוּחִין בְּכוֹן וּקְדוּשָּׁה, בְּנִימוּסַי תֵּהֲכוּן וְתִתְהֲכוּן.</p>\n<p>לֹא יוּכַל לִרְאוֹת, רִבִּי אַבָּא פָּתַח וְאָמַר, (משלי ט״ז:ט״ו) בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים וּרְצוֹנוֹ כְּעָב מַלְקוֹשׁ, כַּד יִסְּבְּרוּן אַפֵּי שְׁכִינְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְיִתְעַסְּקוּן בְּאִינוּן רְתִיכִין דְּמִנְּהוֹן חֵיוָון דְּעָלְמָא.</p>\n<p>תָּא חֲזֵי, לָא תִשְׁכַּח בְּהַנֵּי קְרָאֵי כֻּלְּהוֹן לִישְׁנָא, אֶלָא לְאִינִישׁ, (תהילים ע״א:כ״ד) גַּם לְשׁוֹנִי כָּל הַיּוֹם תֶּהגֶה צִדְקָתֶךָ. וְלָא אַתְּ מַשְׁכַּח בְּהַנֵּי קְרָאֵי בְּקוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין כַּךְ יְתוּבוּן לְאַרְעֲהוֹן, וְיָהַב קוּדְשָׁא בְּרִיךְ הוּא רוּחַ חָכְמְתָא בְּהוֹן, לִישְׁנָא דִּלְהוֹן תֶּהֶוְיָין תָּדִיר בְּקוּדְשָׁא בְּרִיךְ הוּא. (עד כאן אינו מן הזהר):</p>"],[9520011438,"<p>וַיְחִי יַעֲקֹב וְגו', רִבִּי חִיָּיא פָּתַח וְאָמַר, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ וְגו', זַכָּאִין אִינוּן יִשְׂרָאֵל, יַתִּיר מִכָּל עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, דְּקוּדְשָׁא בְּרִיךְ הוּא קָרָא לוֹן צַדִּיקִים. לְאַחְסִין לוֹן יְרוּתַת עַלְמִין בְּעַלְמָא דְאָתֵי, לְאִתְעֲנָגָא בְּהַהוּא עַלְמָא, כְּמָה דִכְתִיב, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנֵּג עַל ה'. מַאי טַעְמָא. בְּגִין דְּמִתְדַּבְּקִין בְּגוּפָא דְמַלְכָּא, דִּכְתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>\n<p>רִבִּי יִצְחָק פָּתַח וְאָמַר, וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ, הַאי קְרָא רָזָא עִלָּאָה אִיהוּ בֵּין מְחַצְדֵי חַקְלָא, דְּהָא בְּרָזָא דְּאַגַּדְתָּא תָּנֵי רִבִּי שִׁמְעוֹן. דְּאַחְסָנַת יְרוּתָא עִלָּאָה דְּהַהִיא אֶרֶץ, לֵית מַאן דְּיָרִית לָהּ, בַּר הַהוּא דְאִקְרֵי צַדִּיק. (ס\"א דהאי ארץ, ולית מאן דירית לה, בר ההוא דאקרי צדיק, דהא צדיק ירית למטרוניתא ודאי) דְּהָא מַטְרוֹנִיתָא בֵּיהּ אִתְדַּבְּקַת לְאִתְבַּסְּמָא, וְצַדִּיק יָרִית לְמַטְרוֹנִיתָא וַדַּאי.</p>\n<p>אוּף הָכָא, בַּחֲבִיבוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, אָמַר, וְעַמֵּךְ כֻּלָּם צַדִּיקִים, וּבְגִין כָּךְ לְעוֹלָם יִירְשׁוּ אֶרֶץ, אִתְחֲזוּן לְיָרִית לְמַטְרוֹנִיתָא. מַאי טַעְמָא אִקְרוּן צַדִּיקִים, וּמַאי טַעְמָא יָרְתִין לְמַטְרוֹנִיתָא. בְּגִין דְּאִתְגַּזָּרוּ. כְּמָה דְתָנִינָן, כָּל מַאן דְּאִתְגְּזַר, וְעֲיִּיל בְּהַאי (ס\"א ברית קדישא ועייל בהאי) אַחְסָנָא, וְנָטִיר לְהַאי בְּרִית, עָאל וְאִתְדָּבַּק בְּגוּפָא דְמַלְכָּא, וְעָאל בְּהַאי צַדִּיק. וּבְגִינֵי כָּךְ אִקְרוּן צַדִּיקִים, וְעַל דָּא לְעוֹלָם יִירְשׁוּ אָרֶץ. מַאי אָרֶץ, דָּא אֶרֶץ הַחַיִּים.</p>\n<p>אַהֲדַר וְאָמַר, נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. נִצֶר מַטָּעַי, עֲנָפָא מֵאִינוּן עֲנָפִין, דְּנָטַע קוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא עַלְמָא. דִּכְתִיב, (בראשית ב׳:ח׳) וַיִּטַּע ה' אֱלהִים גַּן בְּעֵדֶן מִקֶּדֶם, וְהַאי אֶרֶץ חַד מִנַּיְיהוּ. בְּגִינִי כָּךְ, נִצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר.</p>\n<p>דָּבָר אַחֵר, וְעַמֵּךְ כֻּלָּם צַדִּיקִים, דָּא יַעֲקֹב וּבְנוֹי דְּנָחֲתוּ לְמִצְרַיִם בֵּין עַם קְשֵׁי קְדַל, וְאִשְׁתַּכָּחוּ כֻּלְּהוּ זַכָּאִין. וּבְגִין כָּךְ כְּתִיב, לְעוֹלָם <Nonei></i>יִירְשׁוּ אֶרֶץ דְּמִּתַּמָּן סְלִיקוּ לִירַית אַרְעָא קַדִּישָׁא.</p>\n<p>וַיְחִי יַעֲקֹב בְּאֶרֶץ מִצְרַיִם, אַמַּאי פַּרְשָׁתָא דָא סְתִימָא. רִבִּי יַעֲקֹב אָמַר, בְּשַׁעְתָּא דְּמִית יַעֲקֹב, אִסְתִּימוּ עֵינֵיהוֹן דְּיִשְׂרָאֵל. רִבִּי יְהוּדָה אָמַר, דִּכְדֵין נָחֲתוּ לְגָלוּתָא, וְאִשְׁתַּעְבִּידוּ בְּהוֹן.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, מַה כְּתִיב לְעֵילָא, וַיֵּשֶׁב יִשְׂרָאֵל בְּאֶרֶץ מִצְרַיִם בְּאֶרֶץ גּשֶׁן וַיֵּאָחֲזוּ בָהּ וַיִּפְרוּ וַיִּרְבּוּ מְאֹד. וּכְתִיב וַיְחִי יַעֲקֹב, דְּלָא אִתְחֲזֵי לְאַפְרָשָׁא בֵּין דָּא לְדָא. מָה אִינוּן קָיְימֵי בְּתַפְנוּקִין דְּמַלְכִין, וְקַבִּילוּ עִנּוּגָא וְכִסּוּפִין לְגַרְמַיְיהוּ. אוּף יַעֲקֹב נָמֵי, קַיַּים בְּתַפְנוּקֵי מַלְכִין, בְּעִנּוּגָא וְכִסּוּפָא לְגַרְמֵיהּ, לָא אִתְפְּרַשׁ דָּא מִן דָּא.</p>\n<p>וְהָכָא אִקְרֵי וַיְחִי. דְּהָא כָּל יוֹמוֹי לָא אִקְרֵי וַיְחִי, בְּגִין דְּכָל יוֹמוֹי בְּצַעֲרָא הֲווּ, בְּצַעֲרָא אִשְׁתַּכְּחָן, עֲלֵיהּ כְּתִיב, (איוב ג׳:כ״ו) לֹא שָׁלַוְתִּי וְלֹא שָׁקַטְתִּי וְלא נָחְתִּי וַיָּבֹא רֹגֶז. בָּתַר דְּנָחַת לְמִצְרַיִם, אִקְרֵי וַיְחִי. חָמָא לִבְרֵיהּ מַלְכָּא, חָמָא לְכָל בְּנוֹי זַכָּאִין צַדִּיקִין, וְכֻלְּהוּ בְּתַעֲנוּגֵי וְתַפְנוּקֵי עַלְמָא, וְהוּא יָתִיב בֵּינִיהוֹן כַּחֲמַר טַב דְּיָתִיב עַל דּוּרְדַּיֵּיהּ, כְּדֵין אִקְרֵי וַיְחִי יַעֲקֹב. וְלָא פָּרִישׁ בֵּין וַיִּפְרוּ וַיִּרְבּוּ מְאֹד לְוַיְחִי יַעֲקֹב, וְהָכִי אִתְחֲזֵי.</p>\n<p>שְׁבַע עֶשְׂרֵה שָׁנָה, מַאי טַעְמָא שְׁבַע עֶשְׂרֵה שָׁנָה. אֶלָּא אָמַר רַבִּי שִׁמְעוֹן, כָּל יוֹמוֹי דְּיַעֲקֹב בְּצַעֲרָא הֲווּ, בְּצַעֲרָא אַעֲבַר לוֹן בְּקַדְמִיתָא, כֵּיוָן דְּחָמָא לְיוֹסֵף, וְהֲוָה קָאִים קַמֵּיהּ, כַּד יַעֲקֹב מִסְתַּכֵּל בְּיוֹסֵף, הֲוָה אִשְׁתְּלִים בְּנַפְשֵׁיהּ, כְּאִילּוּ חָמָא לְאִמֵּיהּ דְּיוֹסֵף. דְּשַׁפִּירוּ דְּיוֹסֵף דָּמֵי לְשַׁפִּירוּ דְּרָחֵל. וְהֲוָה דָּמֵי בְּגַרְמֵיהּ כְּמָה דְּלָא אַעֲבַר עֲלֵיהּ צַעֲרָא בְּיוֹמוֹי.</p>\n<p>וְכַד יוֹסֵף אִתְפְּרַשׁ מִנֵּיהּ, כְּדֵין אִתְקְיַּים, לֹא שָׁלַוְתִּי וְלֹא שָׁקַטְתִּי וְלא נָחְתִּי וַיָּבֹא רֹגֶז. דְּדָא קַשְׁיָא לֵיהּ לְיַעֲקֹב מִכָּל מַה דְּעֲבַר, וּבְזִמְנָא דְּאִתְפְּרַשׁ יוֹסֵף מִנֵּיהּ, מַה כְּתִיב, (בראשית ל״ז:ב׳) יוֹסֵף בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה הָיָה רוֹעֶה וְגו'. וְכָל יוֹמִין דְּיַעֲקֹב, לָא הֲוָה לֵיהּ צַעֲרָא כְּהַאי, וְהֲוָה בָּכֵי כָּל יוֹמָא לְאִינוּן שְׁבַע עֶשְׂרֵה שָׁנָה דְיוֹסֵף.</p>\n<p>מַאי קָאֲתִיבוּ לֵיהּ, (בראשית מ״ו:ד׳) וְיוֹסֵף יָשִׁית יָדוֹ עַל עֵינֶיךָ, הָא לְךָ שְׁבַע עֶשְׂרֵה שָׁנָה אָחֳרָנִין, בְּעִנּוּגִין וְתַפְנוּקִין וַהֲנָאוֹת וְכִסּוּפִין. הֲדָא הוּא דִכְתִיב וַיְחִי יַעֲקֹב בְּאֶרֶץ מִצְרַיִם שְׁבַע עֶשְׂרֵה שָׁנָה וְגו'. תָּנָא, כָּל אִינוּן שְׁנִין, שְׁכִינְתָּא יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, עִמֵּיהּ אִשְׁתַּכְּחָא, וּבְגִין כָּךְ חַיִּים אִקְרוּן.</p>\n<p>תָּא חֲזֵי, כְּתִיב וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם, אִתְחֲזֵי דְּהָא בְּקַדְמִיתָא מִית הֲוָה הַהוּא רוּחָא דִילֵיהּ, וְלָא הֲוָה מִתְכַּוֵּין לְקַבְּלָא רוּחָא אָחֳרָא. דְּהָא רוּחָא דִלְעֵילָא, לָא שַׁרְיָא בְּרֵיקַנְיָא. אָמַר רִבִּי יוֹסֵי, שְׁכִינְתָּא לָא שַׁרְיָא, אֶלָּא בְּאֲתַר שְׁלִים, וְלָא בְּאֲתַר חָסֵר, וְלָא בְּאֲתַר פָּגִים, וְלָא בְּאֲתַר עָצִיב, אֶלָּא בְּאֲתַר דְּאִתְכַּוֵּון, בְּאֲתַר חֲדוּ. וּבְגִין כָּךְ, כָּל אִינוּן שְׁנִין דְּיוֹסֵף אִתְפְּרַשׁ מֵאֲבוֹי, וְיַעֲקֹב הֲוָה עָצִיב, לָא שַׁרְיָא בֵּיהּ שְׁכִינְתָּא.</p>\n<p>תָּנָא, אָמַר רִבִּי אֶלְעָזָר אָמַר רִבִּי אַבָּא, כְּתִיב, (תהילים ק׳:ב׳) עִבְדוּ אֶת ה' בְּשִׂמְחָה בֹּאוּ לְפָנָיו בִּרְנָנָה. לְאֲפָקָא, דְּלֵית פּוּלְחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא מִגּוֹ חֶדְוָה. דְּאָמַר רִבִּי אֶלְעָזָר, לֵית שְׁכִינְתָּא שַׁרְיָא מִגּוֹ עַצְבוּת, דִּכְתִיב (מלכים ב ג׳:ט״ו) וְעַתָּה קְחוּ לִי מְנַגֵּן וְהָיָה כְּנַגֵּן הַמְנַגֵּן. מְנַגֵּן מְנַגֵּן תְּלַת זִימְנֵי אַמַּאי. בְּגִין לְאַתְעָרָא רוּחָא מִשְׁלֵימוּתָא דְּכֹלָּא, דְּהוּא רוּחַ שְׁלֵימָא.</p>\n<p>אָמַר רִבִּי אַבָּא, תַּמָּן תָּנִינָן, מֵאַרְבַּע סִטְרִין כֹּלָּא אִשְׁתַּכַּח, וְכָל שָׁרָשִׁין דְּעִלָּאִין וְתַתָּאִין בְּהוּ אֲחִידָן. וְתָנָא דָּא עָיִיל וְדָא נָפִיק דָּא סָתִים וְדָא פָּרִישׁ, אִתְאֲחַד חַד בַּחֲבֶרְתָּהּ, וְאִינוּן אֲבָהָן דְּכֹלָּא.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, (דברים י׳:ט״ו) רַק בַּאֲבוֹתֶיךָ חָשַׁק ה', כְּתִיב בַּאֲבוֹתֶיךָ, מַמָּשׁ תְּלָתָא, וּמַשְׁמַע דִּכְתִיב רַק, רַק מַמָּשׁ, וּמֵאִלֵּין מִתְפָּרְשָׁן וּמִתְאַחֲדָן כָּל שְׁאָר אָחֳרָנִין, וְסָלְקִין שְׁמָא לְאִתְעַטְּרָא.</p>"],[9520011439,"<p>תָּנָא, אָמַר רִבִּי יוֹסֵי, מִן יוֹמָא דְּאִסְתַּלִּיק רִבִּי שִׁמְעוֹן מִן מְעַרְתָּא, מִלִּין (אלין) לָא אִתְכַּסְיָין מִן חַבְרַיָא, וְרָזִין עִלָּאִין הֲווּ מִסְתַּכְּלָן וְאִתְגַּלְּיָין מִבֵּינַיְיהוּ, כְּאִלּוּ אִתְיְיהִיבוּ הַהִיא שַׁעְתָּא בְּטוּרָא דְסִינַי. בָּתַר דְּשָׁכִיב כְּתִיב, (בראשית ח׳:ב׳) וַיִּסָּכְרוּ מַעְיְינוֹת <Nonei></i>תְּהוֹם וַאֲרוּבּוֹת הַשָּׁמַיִם, וְהֲווּ חַבְרַיָיא מְרַחֲשָׁן מִלֵּי, וְלָא מִתְקַיְימֵי בְּהוּ.</p>\n<p>דְּיוֹמָא חַד הֲוָה יָתִיב רִבִּי יְהוּדָה, אֲפִתְחָא דִטְבֶרְיָה, וְחָמָא תְּרֵי גְּמַלֵּי, דְּסָלְקֵי קַטְפִירָא מֵעֲלוֹי דְּכִתְפִין, נָפַל מָטוּלָא דְּקַטְפִירָא, וְאֲתוּ צִפֳּרֵי. וְעַד לָא מָטוּ עֲלַיְיהוּ, אִתְבַּקָּעוּ.</p>\n<p>לְבָתַר אָתוּ כַּמָּה צִפֳּרִין, וְהֲווּ אָזְלֵי עֲלַיְיהוּ, וְשָׁרוּ (נ\"א ושדיאו) לוֹן בְּטַרְטִישָׁא, וְלָא מִתְבַּקְּעִין. וְהֲווּ צָוְוחִין לוֹן, וְלָא הֲווּ מִתְפָּרְשָׁן. שָׁמְעוּ חַד קָלָא, עִטְרָא דְעִטְרִין בְּקִדְרִין שַׁרְיָא, וּמָרִיהּ לְבַר.</p>\n<p>עַד דְּהֲוָה יָתִיב, עָבַר חַד גַּבְרָא, אַשְׁגַּח בְּהוּ. אָמַר, לָא קִיֵּים דָּא, הָא דִכְתִיב, (בראשית ט״ו:י״א) וַיֵּרֶד הָעַיִּט עַל הַפְּגָרִים וַיַּשֵּׁב אוֹתָם אַבְרָם. אָמַר רִבִּי יְהוּדָה, וְהָא עֲבִידְנָא וְלָא אִתְפָּרְשָׁן. אַהֲדַר רֵישֵׁיהּ הַהוּא גַבְרָא וְאָמַר, עַד לָא מָרִיט דָּא רֵישֵׁיהּ דְּמָרֵיהּ, וְעַד לָא גָּלִישׁ לְמַטְרוֹנִיתָא. רָהַט אֲבַתְרֵיהּ תְּלַת מִלִּין, וְלָא אָמַר לֵיהּ. חָלַשׁ דַּעְתֵּיהּ דְּרִבִּי יְהוּדָה.</p>\n<p>יוֹמָא חַד, אִדְמוּךְ תְּחוֹת אִילָנָא, וְחָמָא בְּחֶלְמֵיהּ, ד' גַּדְפִין מִתְתַּקְנָן, וְסָלִיק רִבִּי שִׁמְעוֹן עֲלַיְיהוּ, וְסֵפֶר תּוֹרָה עִמֵּיהּ. וְלָא שָׁבִיק כָּל סִפְרֵי רָזִין עִלָּאִין וַאֲגַדְתָּא, דְּלָא סָלִיק לוֹן בַּהֲדֵיהּ. וְסָלִיק לְהוֹן (ס\"א וסליקן ליה) לִרְקִיעָא, וְחָמָא דְמִתְכַּסְיָא מֵעֵינָא, וְלָא אִתְגַּלְיָא.</p>\n<p>כַּד אִתְעַר, אָמַר, וַדַּאי מִדְּשָׁכִיב רִבִּי שִׁמְעוֹן, חָכְמְתָא אִסְתַּלְּקַת מֵאַרְעָא. וַוי לְדָרָא דְּהַאי אַבְנָא טָבָא, דְהֲווּ מִתְחֲזָן (ס\"א דמתאחדן) מִנֵּיהּ, וְסָמְכִין עֲלֵיהּ עִלָּאִין וְתַתָּאִין, אִתְאֲבִיד מִנַּיְיהוּ.</p>\n<p>אֲתָא לְגַבֵּיהּ דְּרִבִּי אַבָּא, סָח לֵיהּ. סָלִיק רִבִּי אַבָּא יְדוֹי עַל רֵישֵׁיהּ, וּבָכָה וְאָמַר, רִבִּי שִׁמְעוֹן רֵיחַיָיא דְּטַחֲנִין מִנֵּיהּ מַנָּא טָבָא כָּל יוֹמָא, וְלָקְטִין לֵיהּ. כְּמָה דִכְתִיב, (במדבר י״א:ל״ב) הַמַּמְעִיט אָסַף עֲשָׂרָה חֳמָרִים, וְהַשְׁתָּא רֵיחַיָּיא וּמַנָּא אִסְתַּלְּקוּ וְלָא אִשְׁתָּאַר בְּעַלְמָא מִינֵיהּ, בַּר כְּמָה דִכְתִיב, (שמות ט״ז:ל״ג) קַח צִנְצֶנֶת אַחַת וְתֶן שָׁמָּה מְלֹא הָעוֹמֶר מָן וְהַנַּח אוֹתוֹ לִפְנֵי ה' לְמִשְׁמֶרֶת. וְאִלּוּ בְּאִתְגַּלְּיָיא לָא כְּתִיב, אֶלָּא לְמִשְׁמֶרֶת, לְאַצְנָעוּתָא. הַשְׁתָּא מַאן יָכִיל לְגַלָּאָה רָזִין, וּמַאן יִנְדַע לוֹן.</p>\n<p>לָחִישׁ לֵיהּ לְרִבִּי יְהוּדָה בִּלְחִישׁוּ, (אמר ליה רבי אבא) וַדַּאי הַהוּא גַבְרָא דְּחָמִית, אֵלִיָּהוּ הֲוָה. וְלָא בָּעָא לְגַלָּאָה רָזִין, בְּגִין דְּתִנְדַע שְׁבָחָא דְּרִבִּי שִׁמְעוֹן, דְּהֲוָה בְּיוֹמוֹי, וְיִבְכּוֹן דָּרָא עֲלוֹי. אָמַר לֵיהּ, דַּי לְמִבְכֵּי בְּכִיָּה עֲלֵיהּ.</p>\n<p>רִבִּי יְהוּדָה הֲוָה בָּכֵי כָּל יוֹמָא עֲלוֹי, דְּהָא אַעֲרַא עִמֵּיהּ בְּאִדְרָא קַדִּישָׁא דְּרִבִּי שִׁמְעוֹן, וּשְׁאָר חַבְרַיָיא. אָמַר לֵיהּ, וַוי דְּלָא אִסְתַּלַּקְנָא הַהוּא יוֹמָא עִם אִינוּן תְּלָתָא דְּאִסְתַּלָּקוּ, וְלָא לֶחֱמֵי דָרָא דָא, דְּהָא אִתְהַפַּךְ.</p>\n<p>אָמַר לֵיהּ, רִבִּי אֵימָא לִי, כְּתִיב, (שמות כ״ט:מ״ד) וְהֵם יִקְחוּ אֶת הַזָּהָב וְאֶת הַתְּכֵלֶת וְאֶת הָאַרְגָּמָן וְאֶת תּוֹלַעַת הַשָּׁנִי וְאֶת הַשֵּׁשׁ, וְאִילּוּ כֶּסֶף לָא כְּתִיב. וְהָא כְּתִיב זָהָב וָכֶסֶף. אָמַר לֵיהּ וְהָא נָמֵי נְחשֶׁת, דְּכֶסֶף וּנְחשֶׁת בְּחֻשְׁבְּנָא הֲווּ, וְהָכָא לָא. אֶלָּא, אִי לָא דְּגַלֵּי בּוֹצִינָא קַדִּישָׁא בְּאַתְרֵיהּ, לָא אִצְטָרִיכְנָא לְגַלָּאָה.</p>"],[9520011440,"<p>פָּתַח וְאָמַר, (חגי ב׳:ח׳) לִי הַכֶּסֶף וְלִי הַזָּהָב נְאֻם ה', הַיְינוּ דִכְתִיב, (תהילים קט״ו:ט״ז) הַשָּׁמַיִם שָׁמַיִם לַה'.</p>\n<p>בְּכַמָּה אֲתַר אִסְתַּכַּלְנָא בְּאִלֵּין מָאנֵי דְּקוּדְשָׁא, דִּכְתִיב, (ויקרא טו) בִּגְדֵי קֹדֶשׁ הֵם, וּכְתִיב, (שמות כ״ח:ד׳) וְעָשׂוּ בִּגְדֵי קֹדֶשׁ. מַאי קְדוּשָּׁה הָכָא. אֶלָּא הָכִי תָּנִינָן, קְדוּשָּׁה אִינוּן בְּכָל אֲתַר. וּכְתִיב בִּגְדֵי קֹדֶשׁ הֵם. וְעָשִׂיתָ בִּגְדֵי קֹדֶשׁ, כְּגַוְונָא דִלְעֵילָא.</p>\n<p>דְּתַנְיָא כֹּהֵן גָּדוֹל לְעֵילָא, כֹּהֵן גָּדוֹל לְתַתָּא, לְבוּשִׁין דִּיקָר לְעֵילָא, לְבוּשִׁין דִּיקָר לְתַתָּא. וּמַה דְּלָא אָמַר כֶּסֶף וּנְחשֶׁת, לְאֲתַר אָחֳרָא אִסְתַּלִּיקוּ. דִּכְתִיב (שמות כ״ז:י״ח) כָּל עַמּוּדֵי הֶחָצֵר סָבִיב מְחוּשָׁקִים כָּסֶף וְגו', וּכְתִיב וְאַדְנֵיהֶם נְחשֶׁת. דְּאִינוּן מָאנֵי שִׁמּוּשָׁא, לְאִשְׁתַּמָּשָׁא מַשְׁכְּנָא בְּהוּ.</p>\n<p>אֲבָל הָכָא בְּאִלֵּין לְבוּשִׁין דִּיקָר, לָא בָּעֵי לְאִשְׁתַּמָּשָׁא בְּהוּ בַּר נָשׁ אָחֳרָא, בַּר מִכַּהֲנָא רַבָּא, דִּרְבוּ מְשַׁח קוּדְשָׁא עַל רֵישֵׁיהּ. דִּכְתִיב (שמות כ״ח:ב׳) וְעָשִׂיתָ בִּגְדֵי קֹדֶשׁ לְאַהֲרֹן אָחִיךָ לְכָבוֹד וּלְתִפְאָרֶת. דִּבְאִינוּן לְבוּשִׁין דָּמֵי לְגַוְונָא דִלְעֵילָא.</p>"],[9520011441,"<p>תַּנְיָא. וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת. אָמַר רִבִּי יְהוּדָה, וַוי לְעַלְמָא, דְּהָא בְּנֵי נָשָׁא לָא חָמָאן וְלָא שְׁמָעָן, וְלָא <Nonei></i>יָדְעִין דְּהָא כָּל יוֹמָא וְיוֹמָא, קָלָא דְּכָרוֹזָא אִשְׁתְּמַע, בְּמָאתָן וְחַמְשִׁין עָלְמִין.</p>\n<p>תָּנָא עַלְמָא חָדָא, אִשְׁתְּמוֹדַע לְעֵילָא. וְכַד כָּרוֹזָא נָפִיק, הַהוּא עַלְמָא מִזְדַּעְזְעָא וּמִתְחַלְחְלָא. נָפְקֵי (קסב ע\"ב) תְּרֵין צִפֳּרִין, דְּאִסְתַּלָּקוּ מֵהַהוּא עַלְמָא, דִּמְדוֹרֵיהוֹן תְּחוֹת אִילָנָא דְּחֵיזוּ דְחַיֵּי וּמוֹתָא בֵּיהּ.</p>\n<p>נָפְקָא חַד צִפּוֹרָא לִסְטַר דָּרוֹמָא וְחַד צִפּוֹרָא לִסְטַר צָפוֹנָא, וְחַד צִפּוֹרָא כַּד נָהִיר יְמָמָא, וְחַד כַּד אִתְחֲשַׁךְ יְמָמָא. כָּל חַד וְחַד קָרֵי וּמַכְרְזָא, מַה דְּשָׁמְעִין מֵהַהוּא כָּרוֹזָא.</p>\n<p>לְבָתַר בָּעוּ לְאִסְתַּלָּקָא לְאַתְרַיְיהוּ, וּמִשְׁתַּמְטֵי רַגְלַיְיהוּ בְּנוּקְבָא דִתְהוֹמָא רַבָּא, וּמִתְלַכְּדָן בְּגַוֵּיהּ, עַד דְּאִתְפְּלִיג לֵילְיָא. כַּד אִתְפְּלִיג לֵילְיָא, כָּרוֹזָא קָרֵי, (קהלת ט׳:י״ב) וְכַצִּפֳּרִים הָאֲחֻזוֹת בַּפָּח כָּהֵם יוּקָשִׁים בְּנֵי הָאָדָם.</p>\n<p>אָמַר רִבִּי יְהוּדָה, בְּשַׁעְתָּא דְּמִתְלַכְּדָן רַגְלוֹי דִּבְנֵי נָשָׁא, וְיוֹמוֹי אִתְקְרִיבוּ, הַהוּא יוֹמָא, אִתְקְרֵי יוֹם ה', לְאֲתָבָא רוּחֵיהּ לֵיהּ. תָּנָא בְּהַהִיא שַׁעְתָּא, פַּקְדָא הַהוּא כִּתְרָא קַדִּישָׁא, עַל רוּחֵיהּ. וּמַאן אִיהוּ, דִּכְתִיב, (תהילים צ׳:י׳) יְמֵי שְׁנוֹתֵינוּ בָהֶם שִׁבְעִים שָׁנָה. וְהִיא כִּתְרָא שְׁבִיעָאָה דְּכֹלָּא.</p>\n<p>וְאִם מִסִּטְרָא דִגְבוּרָה קָאֳתֵי, כְּתִיב, וְאִם בִּגְבוּרוֹת שְׁמֹנִים שָׁנָה דְּכִתְרָא דִּגְבוּרָה תְּמִינָאָה הֲוֵי, מִכָּאן וּלְהָלְאָה, לֵית אֲתַר לְאִתְמְשַׁךְ, כְּמָה דְאַתְּ אָמֵר, וְרָהְבָּם עָמָל וָאָוְן. בְּאֲתַר דְּלָא הֲוֵי יְסוֹדָא, בִּנְיָינָא לָא אִתְקְיַּים.</p>\n<p>אָמַר רִבִּי יְהוּדָה, זַכָּאִין אִינוּן צַדִּיקַיָא, כַּד קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאֲתָבָא רוּחֵיהּ לֵיהּ, וּלְשָׁאֲבָא הַהוּא רוּחָא בְּגַוֵּיהּ. דְּתַנְיָא, בְּשַׁעְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאֲתָבָא רוּחֵיהּ לֵיהּ, אִי זַכָּאָה הוּא הַהוּא רוּחָא, מַה כְּתִיב, (קהלת י״ב:ז׳) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלהִים אֲשֶׁר נְתָנָהּ.</p>\n<p>וְאִי לָא אִשְׁתַּכַּח זַכָאָה, וַוי לְהַהוּא רוּחָא, דְּבָעֵי לְאִסְתַּחָאָה בְּנוּרָא דְּדָלִיק, וּלְאִתְתַּקָּנָא בְּגִין לְאִשְׁתָּאֲבָא בְּגוּפָא דְמַלְכָּא וְאִי לָא אִתְתַּקָּנַת, וַוי לְהַהוּא רוּחָא, דְמִתְגַּלְגְּלָא כְּאַבְנָא בְּקוֹסְפִיתָא, דִּכְתִיב, (שמואל א כ״ה:כ״ט) וְאֶת נֶפֶשׁ אֹיְבֶיךָ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע. תַּנְיָא, אִי הַהוּא רוּחָא זָכֵי, כַּמָּה טָבִין גְּנִיזִין לֵיהּ בְּהַהוּא עַלְמָא. דִּכְתִיב, (ישעיהו ס״ד:ג׳) עַיִן לא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>\n<p>אָמַר רִבִּי יוֹסֵי, כַּד הַהוּא בַּר נָשׁ אִתְקְרִיבוּ יוֹמוֹי, תְּלָתִין יוֹמִין מַכְרִיזֵי עֲלוֹי בְּעַלְמָא וְאֲפִילּוּ צִפֳּרֵי שְׁמַיָא מַכְרִיזִין עֲלוֹי. וְאִי זַכָּאָה הוּא, תְּלָתִין יוֹמִין מַכְרִיזִין עֲלוֹי בֵּין צַדִּיקַיָא, בְּגִינְתָא דְעֵדֶן.</p>\n<p>תָּנָא, כָּל אִינוּן תְּלָתִין יוֹמִין, נִשְׁמָתֵיהּ נָפְקַת מִנֵּיהּ בְּכָל לֵילְיָא, וְסָלְקַת וְחָמַאת דּוּכְתָּהּ בְּהַהוּא עַלְמָא, וְהַהוּא בַּר נָשׁ לָא יָדַע, וְלָא אַשְׁגַּח, וְלָא שַׁלִּיט בְּנִשְׁמָתֵיהּ, כָּל אִינוּן תְּלָתִין יוֹמִין כְּמָה דְּהֲוָה בְּקַדְמִיתָא. דִּכְתִיב, (קהלת ח׳:ח׳) אֵין אָדָם שַׁלִּיט בָּרוּחַ לִכְלא אֶת הָרוּחַ וְגו'. אָמַר רִבִּי יְהוּדָה, מִכַּד שָׁרָאן אִינוּן תְּלָתִין יוֹמִין, צַלְמָא דְּבַּר נָשׁ אִתְחֲשַׁךְ, וְדִיוּקְנָא דְאִתְחֲזֵי בְּאַרְעָא אִתְמְנָעַת.</p>"],[9520011442,"<p>רִבִּי יִצְחָק הֲוָה יָתִיב יוֹמָא חַד אֲפִתְחָא דְּרִבִּי יְהוּדָה, וְהֲוָה עָצִיב. נָפִיק רִבִּי יְהוּדָה, אַשְׁכְּחֵיהּ לְתַרְעֵיהּ, דְּהֲוָה יָתִיב וְעָצִיב. אָמַר לֵיהּ (צ\"ל מה) מַאן יוֹמָא דֵין מִשְּׁאָר יוֹמִין.</p>\n<p>אָמַר לֵיהּ, אָתֵינָא לְגַבָּךְ, לְמִבְעֵי מִינָךְ תְּלַת מִלִּין, חַד, דְּכַד תֵּימָא מִלֵּי דְאוֹרַיְיתָא, וְתַדְכַּר מֵאִינוּן מִלִּין דְּאֲנָא אֲמִינָא, דְּתֵימָא לוֹן מִשְּׁמִי, בְּגִין לְאַדְכָּרָא שְׁמִי. וְחַד דְּתִזְכֵּי לְיוֹסֵף בְּרִי בְּאוֹרַיְיתָא. וְחַד, דְּתֵיזִיל לְקִבְרִי כָּל ז' יוֹמִין, וְתִבְעֵי בָּעוּתִיךְ עָלַי.</p>\n<p>אָמַר לֵיהּ מִנַּיִן לָךְ. אָמַר לֵיהּ, הָא נִשְׁמָתִי אִסְתַּלְּקַת מִינִי בְּכָל לֵילְיָא, וְלָא אַנְהִיר לִי בְּחֶלְמָא כְּמָה דְּהֲוָה בְּקַדְמִיתָא. וְעוֹד דְּכַד אֲנָא מַצְלֵינָא וּמָטִינָא לְשׁוֹמֵעַ תְּפִלָּה, אַשְׁגַּחְנָא בְּצוּלְמִי דִילִי בְּכוֹתְלָא, וְלָא חָמִינָא לֵיהּ. וְאֲמִינָא דְּהוֹאִיל וְצַלְמָא אִתְעֲבַר וְלָא אִתְחֲזֵי, דְּהָא כָּרוֹזָא נָפִיק וְכָרִיז. דִּכְתִיב, (תהילים ל״ט:ז׳) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ, כָּל זִמְנָא דְּצוּלְמָא דְּבַר נָשׁ לָא יִתְעֲבַר מִנֵּיהּ, יִתְהַלֶּךְ אִישׁ, וְרוּחֵיהּ אִתְקַיְּימָא בְּגַוֵּיהּ. אִתְעֲבַר צוּלְמָא דְבַר נָשׁ וְלָא אִתְחֲזֵי, אִתְעֲבַר מֵהַאי עָלְמָא.</p>\n<p>אָמַר לֵיהּ, וּמֵהָכָא, דִּכְתִיב, (איוב ח׳:ט׳) כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. אָמַר לֵיהּ, כָּל אִלֵּין מִלִּין דְּאַתְּ בָּעֵי עֲבִידְנָא. אֲבָל בָּעִינָא מִינָךְ <Nonei></i>דִּבְהַהוּא עַלְמָא, תְּבָרִיר דּוּכְתָּאי גַּבָּךְ, כְּמָה דַהֲוֵינָא בְּהַאי עַלְמָא. בָּכָה רִבִּי יִצְחָק וְאָמַר, בְּמָטוּ מִינָךְ, דְּלָא תִּתְפָּרֵשׁ מִנָּאי כָּל אִלֵּין יוֹמִין.</p>\n<p>אֲזְלוּ לְגַבֵּיהּ דְּרִבִּי שִׁמְעוֹן, אַשְׁכְּחוּהוּ דְּהֲוָה לָעֵי בְּאוֹרַיְיתָא, זָקִיף עֵינוֹי רִבִּי שִׁמְעוֹן, וְחָמָא לְרִבִּי יִצְחָק, וְחָמָא לְמַלְאַךְ הַמָּוֶת דְּרָהִיט קַמֵּיהּ, וְרָקִיד קַמֵּיהּ. קָם רִבִּי שִׁמְעוֹן, אָחִיד בִּידֵיהּ דְּרִבִּי יִצְחָק. אָמַר, גּוֹזַרְנָא, מַאן דְּרָגִיל לְמֵיעַל, יֵעוּל. וּמַאן דְּלָא רָגִיל לְמֵיעָאל, לָא יֵיעוּל. עָאלוּ רִבִּי יִצְחָק וְרִבִּי יְהוּדָה, קָטִיר מַלְאַךְ הַמָּוֶת לְבַר.</p>\n<p>אַשְׁגַּח רִבִּי שִׁמְעוֹן, וְחָמָא דְּעַד כְּעַן לָא מָטָא עִדָּנָא, דְּהָא עַד תְּמַנְיָא שַׁעְתֵּי דְיוֹמָא הֲוָה זִמְנָא. אוֹתְבֵיהּ קַמֵּי רִבִּי שִׁמְעוֹן, וְהֲוָה לָעֵי לֵיהּ בְּאוֹרַיְיתָא. אָמַר רַבִּי שִׁמְעוֹן לְרִבִּי אֶלְעָזָר בְּרִיהּ, תִּיב אֲפִתְחָא וּמַה (צ\"ל ומאן) דְּתֶחמֵי, לָא תִשְׁתָּעֵי בַּהֲדֵיהּ. וְאִי יִבְעֵי לְמֵיעָאל הָכָא, אוֹמֵי אוֹמָאָה דְּלָא לֵיעוֹל.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן לְרִבִּי יִצְחָק, חָמִית דִּיוּקְנָא דְּאֲבוּךְ יוֹמָא דָא, אוֹ לָא. דְּהָא תָּנִינָן, בְּשַׁעְתָּא דְבַר נָשׁ אִסְתַּלַּק מֵעַלְמָא, אֲבוֹי וְּקְרֵיבוֹי מִשְׁתַּכְּחִין תַּמָּן עִמֵּיהּ, וְחָמָא לוֹן וְאִשְׁתְּמוֹדַע לוֹן, וְכָל אִינוּן דְּהֲוָה מְדוֹרֵיהּ גַּבַּיְיהוּ בְּהַהוּא עַלְמָא בְּדַרְגָּא חַד, כֻּלְּהוּ מִתְכַּנְּשֵׁי וּמִשְׁתַּכְּחֵי עִמֵּיהּ, וְאָזְלִין עִם נִשְׁמָתֵיהּ, עַד אֲתַר דְּתִשְׁרֵי בְּאַתְרֵיהּ. אָמַר, עַד כְּעָן לָא חָמֵינָא.</p>\n<p>אַדְּהָכִי קָם רִבִּי שִׁמְעוֹן וְאָמַר, מָארֵי דְעַלְמָא, אִשְׁתְּמוֹדַע רִבִּי יִצְחָק לְגַבָּן, וּמֵאִנּוּן שִׁבְעָה עַיְינִין דְּהָכָא הוּא. הָא אֲחִידְנָא בֵּיהּ, וְהַב לִי. נָפַק קָלָא וְאָמַר, כּוּרְסְיָיא (ס\"א טסיסה) דְמָארֵיהּ קְרִיבָא בְּגַדְפוֹי דְּרִבִּי שִׁמְעוֹן, הָא דִידָךְ הוּא, וְעִמָּךְ תַּיְיתֵיהּ בְּזִימְנָא דְתִיעוֹל לְמִשְׁרֵי בְּכוּרְסְיָךְ. אָמַר רִבִּי שִׁמְעוֹן, וַדַּאי.</p>\n<p>אַדְּהָכִי, חָמָא רִבִּי אֶלְעָזָר דְּהֲוָה אִסְתַּלִּיק מַלְאַךְ הַמָּוֶת. וְאָמַר, לֵית קוּפְטְרָא דְּטִיפְסָא, בְּאֲתַר דְּרִבִּי שִׁמְעוֹן בֶּן יוֹחָאי שְׁכִיחַ. אָמַר רִבִּי שִׁמְעוֹן לְרִבִּי אֶלְעָזָר בְּרֵיהּ, עוּל הָכָא, וְאָחִיד בֵּיהּ בְּרִבִּי יִצְחָק, דְּהָא חָמֵינָא בֵּיהּ דְּמִסְתָּפֵי. עָאל רִבִּי אֶלְעָזָר, וְאָחִיד בֵּיהּ. וְרִבִּי שִׁמְעוֹן אַהֲדַר אַנְפֵּיהּ וְלָעֵי בְּאוֹרַיְיתָא.</p>\n<p>נַיִים רִבִּי יִצְחָק, וְחָמָא לְאֲבוֹי. אָמַר לֵיהּ, בְּרִי, זַכָּאָה חוּלָקָךְ בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי. דְּהָא בֵּין טַרְפֵּי אִילָנָא דְחַיֵּי דְּגִנְתָא דְעֵדֶן, אִתְיְהִיב (את יתיב) אִילָנָא רַבָּא וְתַקִּיף בִּתְרֵין עָלְמִין, רִבִּי שִׁמְעוֹן בֶּן יוֹחָאי הוּא. דְּהָא הוּא אָחִיד לָךְ בְּעַנְפוֹי, זַכָּאָה חוּלָקָךְ בְּרִי.</p>\n<p>אָמַר לֵיהּ אַבָּא, וּמָה אֲנָא הָתָם. אָמַר לֵיהּ, תְּלַת יוֹמִין הֲווּ דְּחָפוּ אִדְרָא דְּמִשְׁכָּבָךְ. וְתַקִּינוּ לָךְ כֵּיוַן פְּתִיחָן, לְאַנְהָרָא לָךְ מֵאַרְבַּע סִטְרִין דְּעַלְמָא. וְאֲנָא חָמֵינָא דּוּכְתֵּיךְ וְחָדֵינָא, דַּאֲמֵינָא זַכָּאָה חוּלָקָךְ בְּרִי. בַּר דְּעַד כְּעָן, בְּרָךְ לָא זָכֵי בְּאוֹרַיְיתָא.</p>\n<p>וְהָא הַשְׁתָּא הֲוֵי זְמִינִין לְמֵיתֵי גַּבָּךְ, תְּרֵיסַר צַדִּיקַיָא דְחַבְרַיָיא, וְעַד דַּהֲוֵינָא נָפְקֵי, אִתְעַר קָלָא בְּכֻלְּהוּ עַלְמִין, מַאן חַבְרִין (ס\"א שבילין) דְּקָיְימִין הָכָא, אִתְעֲטָרוּ, בְּגִינֵיהּ דְּרִבִּי שִׁמְעוֹן. שְׁאֶלְתָּא שָׁאִיל, וְאִתְיְיהִיב לֵיהּ.</p>\n<p>וְלָא דָא בִּלְחוֹדוֹי, דְּהָא שִׁבְעִין דּוּכְתֵּי מִתְעַטְּרָן הָכָא דִילֵיהּ. וְכָל דּוּכְתָּא וְדוּכְתָּא, פָּתְחִין פְּתִיחָן לְשִׁבְעִין עָלְמִין. וְכָל עַלְמָא וְעַלְמָא אִתְפַּתַּח לְע' רְהִיטִין. וְכָל רְהִיטָא וּרְהִיטָא, אִתְפַּתַּח לְשִׁבְעִין כִּתְרִין עִלָּאִין. וּמִתַּמָּן אִתְפַּתָּחוּ אָרְחִין לְעַתִּיקָא סְתִימָאָה דְּכֹלָּא, לְמֶחֱמֵי בְּהַהוּא נְעִימוּתָא עִלָּאָה דְּנָהֲרָא, וּמְהַנְיָא לְכֹלָּא. כְּמָה דְאַתְּ אָמֵר, (תהילים כ״ז:ד׳) לַחֲזוֹת בְּנוֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. מַהוּ וּלְבַקֵּר בְּהֵיכָלוֹ. הַיְינוּ דִכְתִיב, (במדבר י״ב:ז׳) בְּכָל בֵּיתִי נְאֱמָן הוּא.</p>"],[9520011443,"<p>אָמַר לֵיהּ, אַבָּא, כַּמָּה זִמְנָא יְהִיבוּ לִי בְּהַאי עַלְמָא, אָמַר לֵיהּ, לֵית לִי רְשׁוּתָא וְלָא מוֹדָעֵי לֵיהּ לְבַר נָשׁ. אֲבָל בְּהִלּוּלָא רַבָּא דְּרִבִּי שִׁמְעוֹן, תְּהֵא מְתַקֵּן פָּתוֹרֵיהּ. כְּמָא דְאַתְּ אָמֵר, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה בָּעֲטָרָה שֶׁעִטְּרָה לוֹ אִמוֹ בְּיוֹם חֲתֻנָּתוֹ וּבְיוֹם שִׂמְחַת לִבּוֹ.</p>\n<p>אַדְּהָכִי אִתְעַר רִבִּי יִצְחָק, וְהֲוָה חָיִיךְ, וְאַנְפּוֹי נְהִירִין. חָמָא רִבִּי שִׁמְעוֹן, וְאִסְתַּכֵּל בְּאַנְפּוֹי. אָמַר לֵיהּ, מִלָּה חַדְתָּא שְׁמַעְתָּא. אָמַר לֵיהּ, וַדַּאי. סָח לֵיהּ, אִשְׁתַּטַּח קַמֵּיהּ דְּרִבִּי שִׁמְעוֹן.</p>\n<p>תָּאנָא, מֵהַהוּא יוֹמָא, הֲוָה <Nonei></i>רִבִּי יִצְחָק אָחִיד לִבְרֵיהּ בִּידֵיהּ, וְלָעֵי לֵיהּ בְּאוֹרַיְיתָא, וְלָא הֲוָה שַׁבְקֵיהּ. כַּד הֲוָה עָאל קַמֵּיהּ דְּרִבִּי שִׁמְעוֹן, אוֹתְבֵיהּ לִבְרֵיהּ לְבַר, וְיָתִיב קַמֵּיהּ דְּרִבִּי שִׁמְעוֹן, וְהֲוָה קָרֵי קַמֵּיהּ (ישעיהו ל״ח:י״ד) ה' עָשְׁקָה לִי עָרְבֵנִי.</p>\n<p>תָּנָא, בְּהַהוּא יוֹמָא תַּקִּיפָא וּדְחִילוּ דְבַר נָשׁ, כַּד מָטֵי זִמְנֵיהּ לְאִסְתַּלָּקָא מֵעַלְמָא, אַרְבַּע סִטְרִין דְּעַלְמָא קָיְימִין בְּדִינָא תַּקִּיפָא, וּמִתְעָרִין דִּינִין מֵאַרְבַּע סִטְרֵי עָלְמָא. וְאַרְבַּע קִשּׁוּרִין נָצָאן, וּקְטָטוּתָא אִשְׁתַּכַּח בֵּינַיְיהוּ, וּבָעְיָין לְאִתְפְּרָשָׁא כָּל חַד לְסִטְרוֹי.</p>\n<p>כָּרוֹזָא נָפִיק וּמַכְרְזָא בְּהַהוּא עַלְמָא, וְאִשְׁתְּמַע בְּמָאתָן וְשִׁבְעִין עָלְמִין. אִי זַכָּאָה הוּא, כֻּלְּהוּ עָלְמִין חָדָאן לְקָדָמוּתֵיהּ. וְאִי לָאו, וַוי לְהַהוּא בַּר נָשׁ וּלְחוּלָקֵיהּ.</p>\n<p>תָּנָא, בְּהַהוּא זִמְנָא דְּכָרוֹזָא כָּרִיז, כְּדֵין נָפַק חַד שַׁלְהוֹבָא מִסְּטַר צָפוֹן, וְאָזְלָא וְאִתּוֹקַד בִּנְהַר דִּינוּר, וּמִתְפָּרְשָׁא לְאַרְבַּע סִטְרֵי עַלְמָא, וְאוֹקִיד נִשְׁמַתְהוֹן דְּחַיָּיבַיָא.</p>\n<p>וְנָפַק הַהוּא שַׁלְהוֹבָא, וְסָלְקָא וְנָחֲתָא בְּעַלְמָא. וְהַהוּא שַׁלְהוֹבָא מָטָא בְּגַדְפוֹי דְתַרְנְגוֹלָא אוּכְמָא, וּבָטַשׁ בְּגַדְפוֹי, וְקָרֵי בְּפִתְחָא בֵּין תַּרְעֵי.</p>\n<p>זִמְנָא קַדְמָאָה קָרֵי וְאָמַר, (מלאכי ג׳:י״ט) הִנֵּה יוֹם ה' בָּא בּוֹעֵר כַּתַּנּוּר וְגו'. זִמְנָא תִּנְיָינָא קָרֵי וְאָמַר, (עמוס ד׳:י״ג) כִּי הִנֵּה יוֹצֵר הָרִים וּבוֹרֵא רוּחַ וּמַגִּיד לְאָדָם מַה שֵּׂחוֹ. וְהַהִיא שַׁעֲתָּא, יָתִיב בַּר נָשׁ בְּעוֹבָדוֹי, דְּסָהֲדִין קַמֵּיהּ, וְהוּא אוֹדֵי עֲלַיְיהוּ. זִמְנָא תְּלִיתָאָה, כַּד בָּעְיָין לְאֲפָקָא נִשְׁמָתֵיהּ מִנֵּיהּ, קָרֵי תַּרְנְגוֹלָא וְאָמַר, (ירמיהו י׳:ז׳) מִי לֹא יִירָאֲךָ מֶלֶךְ הַגּוֹיִם כִּי לְךָ יָאָתָה וְגו'.</p>\n<p>אָמַר רִבִּי יוֹסֵי, תַּרְנְגוֹלָא אוּכְמָא לְמַאי נַפְקָא. אָמַר לֵיהּ רִבִּי יְהוּדָה, כָּל מַה דְּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא, כֻּלְּהוּ רָמִיז בְּחָכְמָה, בַּר דִּבְנֵי נָשָׁא לָא יָדְעֵי. הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ד) מָה רַבּוּ מַעֲשֶׂיךָ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְאָה הָאָרֶץ קִנְיָנֶיךָ, וּמִשּׁוּם דְּאִתְעֲבִידוּ בְּחָכְמָה, כֻּלְּהוּ רְמִיזִין בְּחָכְמָה.</p>\n<p>וְתַרְנְגוֹלָא אוּכְמָא, תָּנִינָן, לֵית דִּינָא שַׁרְיָא אֶלָּא בְּאֲתַר דְּהוּא זִינִיהּ. וְאוּכְמָא מִסִּטְרָא דְּדִינָא קָאָתֵי. וּבְגִין כָּךְ, בְּפַלְגוּת לֵילְיָא מַמָּשׁ, כַּד רוּחָא דְסִטְרָא דְּצָפוֹן אִתְעַר, חַד שַׁלְהוֹבָא נָפִיק, וּבָטַשׁ תְּחוֹת גַּדְפוֹי דְתַרְנְגוֹלָא, וְקָרֵי. וְכָל שֶׁכֵּן בְּתַרְנְגוֹלָא אוּכְמָא, דְּאִתְכַּוֵּון יַתִּיר מֵאַחֲרָא.</p>\n<p>אוּף הָכָא, בְּשַׁעְתָּא דְּדִינָא דְבַר נָשׁ יִתְעַר, שָׁארֵי וְקָרֵי לֵיהּ, וְלֵית דְּיָדַע לֵיהּ, בַּר הַהוּא בַּר נָשׁ דְּשָׁכִיב. דְּתָנִינָן, בְּשַׁעְתָּא דְּבַר נָשׁ שָׁכִיב, וְדִינָא שַׁרְיָא עֲלֵיהּ לְנַפְקָא מֵהַאי עַלְמָא, אִתּוֹסַף רוּחָא עִלָּאָה בֵּיהּ, מַה דְּלָא הֲוָה בְּיוֹמוֹי. וְכֵיוָן דְּשַׁרְיָא עֲלוֹי וְאִתְדָּבַּק בֵּיהּ, חָמֵי מַה דְּלָא זָכָה בְּיוֹמוֹי, מִשּׁוּם דְּאִתּוֹסַף בֵּיהּ הַהוּא רוּחָא. וְכַד אִתּוֹסַף בֵּיהּ וְחָמָא, כְּדֵין נָפִיק מֵהַאי עַלְמָא, הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ט) תּוֹסֶף רוּחָם יִגְוָעוּן וְאֶל עֲפָרָם יְשׁוּבוּן. כְּדֵין כְּתִיב, (שמות ל״ג:כ׳) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי, בְּחַיֵּיהוֹן לָא זָכָאן, בְּמִיתַתְהוֹן זָכָאן.</p>\n<p>תָּאנָא, בְּשַׁעְתָּא דְּבַר נָשׁ מִית, אִתְיְהִיב לֵיהּ רְשׁוּתָא לְמֶחֱמֵי, וְחָמֵי גַבֵּיהּ קְרִיבוֹי וְחַבְרוֹי מֵהַהוּא עָלְמָא, וְאִשְׁתְּמוֹדַע לְהוּ. וְכֻלְּהוּ גְּלִיפִין בְּדִיוּקְנֵיהוֹן כְּמָה דְּהֲווּ בְּהַאי עַלְמָא. אִי זַכָּאָה הַהוּא בַּר נָשׁ, כֻּלְּהוּ חָדָאן קַמֵּיהּ, וּמַקְדְּמֵי לֵיהּ שְׁלָם.</p>\n<p>וְאִי זַכָּאָה לָא הֲוֵי, לָא אִשְׁתְּמוֹדְעָן גַּבֵּיהּ, בַּר מֵאִינוּן חַיָּיבַיָא, דְּטָרְדִין לוֹן בְּכָל יוֹמָא בַּגֵּיהִנָּם. וְכֻלְּהוּ עֲצִיבִין, וּפָתְחִין בְּוַוי וּמְסַיְּימִין בְּוַוי. וְסָלִיק עֵינוֹי, וְחָמָא לוֹן כְּטִיסָא דְּמִסְתַּלְּקָא מִן נוּרָא, אוּף הָכִי, הוּא פָּתַח, וַוי.</p>\n<p>תַּנְיָא, בְּשַׁעְתָּא דְּנָפַק נִשְׁמָתֵיהּ דְּבַר נָשׁ, אָזְלִין כֻּלְּהוּ קְרִיבוֹי וְחַבְרוֹי דְּהַהוּא עַלְמָא עִם נִשְׁמָתֵיהּ, וּמַחְזְיָין לֵיהּ אַתְרָא דְעִדּוּנָא, וְאַתְרָא דְּעוֹנָשָׁא. אִי זַכָּאָה הֲוִי, חָמֵי דוּכְתֵּיהּ, וְסָלִיק וְיָתִיב, וְאִתְעֲדַן בְּעִדּוּנָא עִלָּאָה דְּהַהוּא עָלְמָא. וְאִי לָא הֲוֵי זַכָּאָה, אִשְׁתְּאָרַת הַהִיא נִשְׁמָתָא בְּהַאי עַלְמָא, עַד דְּאִטָמִיר גּוּפָא בְּאַרְעָא. כֵּיוָן דְּאִטָמַר, כַּמָּה גַרְדִּינִין דְּנִמּוּסִין אַחֲדָן בֵּיהּ, עַד דְּמָטָא לְדוּמָ\"ה, וְעָאלִין לֵיהּ בְּמָדוֹרוֹי דְּגֵיהִנֹּם.</p>\n<p>אָמַר רִבִּי יְהוּדָה, כָּל ז' יוֹמִין, נִשְׁמָתָא אָזְלָא מִבֵּיתֵיהּ לְקִבְרֵיהּ, וּמִקִּבְרֵיהּ לְבֵיתֵיהּ, וְאִתְאַבָּלַת עֲלוֹי <Nonei></i>דְגוּפָא. דִּכְתִיב, (איוב י״ד:כ״ב) אַךְ בְּשָׂרוֹ עָלָיו יִכְאָב וְנַפְשׁוֹ עָלָיו תֶּאֱבָל. אָזְלָא וְיָתְבָא בְּבֵיתֵיהּ, חָמֵי לְכֻלְּהוּ עֲצִיבִין וּמִתְאַבְּלָא.</p>\n<p>תָּנָא, בָּתַר ז' יוֹמִין, גּוּפָא הֲוֵי כְּמָה דְּהֲוָה, וְנִשְׁמָתֵיהּ עָאלַת לְדוּכְתָּא, עָאלַת לִמְעַרְתָּא דְכָפֵלְתָּא, חָמַאת מַה דְּחָמַאת, וְעָאלַת לְאֲתַר דְּעָאלַת, עַד דְּמָטַת לְגַּן עֵדֶן, וְעַרְעָת לִכְרוּבִים, וְשָׁנַן דְּחַרְבָּא דִּי בְּגַּן עֵדֶן דִּלְתַתָּא. אִי זַכָּאָה הוּא דְּתֵיעוּל, עָאלַת.</p>\n<p>תָּאנָא, אַרְבַּע סַמְכִין זְמִינִין, וְחַד דִּיוּקְנָא דְגוּפָא בִּידַיְיהוּ, (שמות ר\"י ע\"א) מִתְלַבְּשָׁא בֵּיהּ בְּחֶדְוָותָא וְיָתִיבַת בְּהַהוּא מָדוֹרָא דְּגַּן עֵדֶן דִּלְתַתָּא, עַד זִמְנָא דְאִתְגְּזַר עֲלָהּ. לְבָתַר כְּרוֹזָא קָרֵי.</p>\n<p>וְעַמּוּדָא דִתְלַת גְּוָונֵי אִזְדַּמַּן, וְהַהוּא עַמּוּדָא אִתְקְרֵי, מְכוֹן הַר צִיּוֹן דִּכְתִיב, (ישעיהו ד׳:ה׳) וּבָרָא ה' עַל מְכוֹן הַר צִיּוֹן וְעַל מִקְרָאֶיהָ עָנָן יוֹמָם וְעָשָׁן וְגו'. סָלְקָא בְּהַהוּא עַמּוּדָא לְפִתְחָא דְצֶדֶק, דְּצִיּוֹן וִירוּשָׁלַם בֵּיהּ.</p>\n<p>אִי זָכֵי לְסַלְקָא יַתִּיר, טַב חוּלָקֵיהּ וְעַדְבֵיהּ, לְאִתְדַּבְּקָא בְּגוֹ גוּפָא דְמַלְכָּא. וְאִי לָא זָכֵי לְסַלְּקָא יַתִּיר, כְּתִיב, (ישעיהו ד׳:ג׳) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַם קָדוֹשׁ יֵאָמֶר לוֹ. וְאִי זָכֵי לְסַלְקָא יַתִּיר, זַכָּאָה הוּא. דְּזָכֵי לִיקָרָא דְמַלְכָּא, וּלְאִתְעַדְּנָא בְּעִדּוּנָא עִלָּאָה, דִּלְעֵילָא מֵאֲתַר דְּאִקְרֵי שָׁמַיִם. דִּכְתִיב, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנֵּג עַל ה', עַל ה' דַּיְיקָא. זַכָּאָה חוּלָקֵיהּ דְּמַאן דְּזָכֵי לְחֶסֶד דָּא, דִּכְתִיב, (תהילים ק״ח:ה׳) כִּי גָדוֹל מֵעַל שָׁמַיִם חַסְדֶּךָ.</p>\n<p>וְכִי עַל הַשָּׁמַיִם הוּא, וְהָא כְּתִיב, (תהילים נ״ז:י״א) כִּי גָדוֹל עַד שָׁמַיִם חַסְדֶּךָ. אָמַר רִבִּי יוֹסֵי, אִית חֶסֶד, וְאִית חֶסֶד. חֶסֶד עִלָּאָה, וְחֶסֶד תַּתָּאָה. חֶסֶד עִלָּאָה מֵעַל שָׁמַיִם הוּא. חֶסֶד תַּתָּאָה, הוּא דִכְתִיב, (ישעיהו נ״ה:ג׳) חַסְדֵּי דָוִד הַנֶּאֱמָנִים, וּבְהַנֵּי כְּתִיב עַד שָׁמַיִם.</p>"],[9520011444,"<p>תַּנְיָא, אָמַר רִבִּי יִצְחָק, כְּתִיב, (תהילים קי״ג:ט׳) אֵם הַבָּנִים שְׂמֵחָה הַלְּלוּיָה, אִמָּא יְדִיעָא, הַבָּנִים מַאן אִינוּן. אָמַר רִבִּי שִׁמְעוֹן, הָא תָּנִינָן, תְּרֵין בְּנִין אִית לְקוּדְשָׁא בְּרִיךְ הוּא, חַד דְּכַר וְחַד נוּקְבָא. דְּכַר, יַהֲבֵיהּ לְיַעֲקֹב, דִּכְתִיב, (שמות ד) בְּנִי בְּכוֹרִי יִשְׂרָאֵל, וּכְתִיב, (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאֵר. בַּת, יַהֲבָהּ לְאַבְרָהָם, דִּכְתִיב, (בראשית כ״ד:א׳) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל, בַּת הָיְתָה לוֹ לְאַבְרָהָם, וּבַכֹּל שְׁמָה.</p>\n<p>וְאִמָא רְבִיעָא עֲלַיְיהוּ, דְּיָנְקָא לְהוּ, וְעַל הַאי כְּתִיב, (דברים קד) לא תִקַּח הָאֵם עַל הַבָּנִים. וְתָנִינָן, לָא יַסְגֵּי בַּר נָשׁ חוֹבוֹי לְתַתָּא, בְּגִין דְּיִסְתַּלַּק אִמָּא מֵעַל בְּנִין. וּכְתִיב, (ויקרא י״ח:ז׳) אִמְּךָ הִיא לא תְגַלֵּה עֶרְוָתָהּ, וַוי לְמַאן דְּגָלֵי עֶרְיָיתָא.</p>\n<p>וְכַד תָּיְיבִין בְּנֵי עַלְמָא, וְאַסְגִּין בִּזְכוּתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאִמָּא תָבַת וְכַסְיָא עַל בְּנִין, כְּדֵין אִתְקְרֵי תְּשׁוּבָה. מַאי תְּשׁוּבָה. דָּא תְּשׁוּבָה דְאִמָּא, דְּתָבַת בְּקִיּוּמָהָא, וּכְדֵין (שמות פ\"ג ע\"א) כְּתִיב, (תהילים קי״ג:ט׳) אֵם הַבָּנִים שְׂמֵחָה, אֵם הַבָּנִים וַדַּאי. וְעַל דָּא, לָא לִפָּטַר אִינִישׁ מִפְּרִיָּה וּרְבִיָּה, עַד דְּאוֹלִיד בֵּן וּבַת.</p>\n<p>תַּנְיָא אָמַר רִבִּי יִצְחָק, כְּתִיב, (תהילים כ״ז:ד׳) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ, תִּיאוּבְתָּא דְצַדִּיקַיָא לְמֶחֱמֵי דָא, (ז\"ח ל\"ג נעם ה') וְאַתְּ אֲמַרְתְּ עַל ה'. אָמַר רִבִּי שִׁמְעוֹן, כֹּלָּא חַד. מַשְׁמַע דִּכְתִיב נֹעַם ה', דְּאַתְיָא מֵעַתִּיקָא קַדִּישָׁא לְהַאי שָׁמַיִם. וְתִיאוּבְתָּא דְצַדִּיקַיָא כָּךְ הוּא וַדַּאי, וְעַל הַשָּׁמַיִם כְּתִיב, אָז תִּתְעַנֵּג עַל ה'. זַכָּאָה חוּלָקֵיהּ מַאן דְּזָכֵי. וַדַּאי זְעִירִין אִינוּן.</p>"],[9520011445,"<p>תָּנִינָן, אָמַר רַבִּי שִׁמְעוֹן, כְּתִיב, (שיר השירים א׳:ו׳) בְּנֵי אִמִּי נִחֲרוּ בִי שָׂמוּנִי נוֹטֵרָה אֶת הַכְּרָמִים, בְּנֵי אִמִּי, כְּמָה דִכְתִיב, (איכה ב׳:א׳) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ, דְּכַד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֶחְרָבָא בֵּיתֵיהּ דִּלְתַתָּא, וּלְאַגְלָאָה יִשְׂרָאֵל בֵּינֵי עַמְמַיָא. אַעֲבַר קוּדְשָׁא בְּרִיךְ הוּא מִקַּמֵּיהּ לְהַאי אֶרֶץ, וְאִתְרַחֲקָא מִנִּיהּ. כְּדִכְתִיב, (שמות ב׳:ד׳) וַתֵּתַצַּב אֲחוֹתוֹ מֵרָחוֹק. וְכַד הַאי אֶרֶץ אִתְרַחֲקָא מִשָּׁמַיִם דִּלְעֵילָא, הַאי אֶרֶץ דִּלְתַתָּא אִתְחָרְבָא, וְיִשְׂרָאֵל אִתְפַּזְּרוּ בֵּינִי עַמְמַיָא, אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, מַאן גָּרִים לִי הַאי וּמַאן עָבִיד לִי הַאי, בְּנֵי אִמִּי דְּנִחֲרוּ בִי, וְאִתְרַחֲקוּ מִנִּי, בְּנִי אִמִּי וַדַּאי.</p>\n<p>רִבִּי יוֹסֵי הֲוָה אָזִיל בְּאָרְחָא, וְהֲוָה עִמֵּיהּ רִבִּי חִיָּיא בַּר רַב. עַד דְּהֲווּ אָזְלֵי, אָמַר רִבִּי יוֹסֵי לְרִבִּי חִיָּיא, חֲמֵיתָא מַה דְּאֲנָא חָמִית. אָמַר לֵיהּ, חָמֵינָא גַּבְרָא חַד בְּנַהֲרָא, וְצִפֳּרָא חַד עַל <Nonei></i>רֵישֵׁיהּ, וְעִלְעָא בְּפוּמֵיהּ דְּצִפּוֹרָא, וְאָכְלָא וְרָפְסָא בְּרַגְלוֹי, וְהַהוּא גְּבַר רָמֵי קָלִין וְצָוַוח, וְלָא יְדַעְנָא מַאי קָאֲמַר.</p>\n<p>אָמַר, נִקְרַב גַּבֵּיהּ וְנִשְׁמַע. אָמַר, מִסְתָּפִינָא לְמִקְרַב. אָמַר לֵיהּ, וְכִי בַּר נָשׁ הוּא בְּאֲתַר דָא, אֶלָּא רְמִיזָא דְחָכְמְתָא דְּרָמִיז לָן קוּדְשָׁא בְּרִיךְ הוּא. קְרִיבוּ גַבֵּיהּ, שָׁמְעוּ דְּהֲוָה אָמַר, עוֹטְרָא עוֹטְרָא, תְּרֵין בְּנִין שַׁרְיָין לְבַר, (ס\"א שריאו לברא) לָא נָח וְלָא נַיְיחָא, עַד דְּצַפְרָא בְּקִיסְרָא רְמִיו.</p>\n<p>בָּכָה רִבִּי יוֹסֵי וְאָמַר, הַיְינוּ דְתָנִינָן, בְּנֵי אִמִּי נִחֲרוּ בִי וְגו', מַאי טַעְמָא. בְּגִין דְּכַרְמִי שֶׁלִּי לֹא נָטָרְתִּי.</p>\n<p>אָמַר, וַדַּאי גָלוּתָא אִתְמְשַׁךְ, וְעַל דָּא (ס\"א די) צִפֳּרֵי שְׁמַיָא לָא אַעֲדִיוּ, עַד דִּי שָׁלְטָנוּתָא דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת אַעֲדִיאוּ מִן עַלְמָא. וְאֵימָתַי, עַד דְּיִמְטֵי יוֹמָא דְקוּדְשָׁא בְּרִיךְ הוּא אִתְעַר דִּינוֹי בְּעַלְמָא. דִּכְתִיב, (זכריה י״ד:ז׳) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה' לא יוֹם וְלֹא לָיְלָה.</p>\n<p>עַד דְּהֲווּ אָזְלִין, שָׁמְעוּ חַד קָלָא דְּהֲוָה אָמַר, אוֹקִידָא דְּקוּפְטִירָא מָטָא בְּדִינוֹי, נָפַק חַד שַׁלְהוֹבָא, וְאוֹקִיד לְהַהוּא צִפּוֹרָא. אָמַר, וַדַּאי, כְּמָה דִכְתִיב, (דניאל ז׳:י״א) וִיהִיבַת לִיקֵדַת אֶשָּׁא.</p>"],[9520011446,"<p>אָמַר רִבִּי יוֹסֵי, לָא אַגְלֵי קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, אֶלָּא בְּזִמְנָא דְּלָא אִשְׁתַּכַּח מְהֵימְנוּתָא בֵּינַיְיהוּ. כַּד אִתְמְנַע מְהֵימְנוּתָא בֵּינַיְיהוּ, כִּבְיָכוֹל, הָכִי אִשְׁתַּכַּח בְּכֹלָּא. דִּכְתִיב, (ישעיהו כ״ח:י״ח) וְכִפֶּר בְּרִיתְכֶם אֶת מָוֶת.</p>\n<p>אָמַר רִבִּי חִיָּיא, מַאי דִכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוֶת לָנֶצַח. אָמַר לֵיהּ, כַּד יִתְעַר קוּדְשָׁא בְּרִיךְ הוּא יְמִינָא דִילֵיהּ, אִתְמְנַע מוֹתָא מִן עַלְמָא. וְלָא יִתְעַר הַאי יְמִינָא, אֶלָּא כַּד יִתְעָרוּן יִשְׂרָאֵל בִּימִינָא דְקוּדְשָׁא בְּרִיךְ הוּא, וּמַאי נִיהוּ תּוֹרָה, דִּכְתִיב בָּהּ, (דברים ל״ג:כ״א) מִימִינוֹ אֵשׁ דָּת לָמוֹ. בְּהַהוּא זִמְנָא, (תהילים קי״ח:י״ז) יְמִין ה' עוֹשָׂה חָיִל וְגו', לא אָמוּת כִּי אֶחְיֶה וַאֲסַפֵּר מַעֲשֵׂי יָהּ.</p>"],[9520011447,"<p>תָּנָא, הַהוּא זַכָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בֵּיהּ, וְכָרוֹזָא קָרֵי עֲלֵיהּ, ל' יוֹמִין, בֵּינֵי צַדִּיקַיָיא בְּגִנְתָא דְעֵדֶן. כֻּלְּהוּ צַדִּיקַיָא חָדָאן, כֻּלְּהוּ צַדִּיקַיָיא אַתְיָין, וּמְעַטְּרָן דּוּכְתֵּיהּ דְּהַהוּא צַדִּיקָא, עַד דְּיֵיתֵי לְמֵידַר דִּיּוּרֵיהּ בֵּינַיְיהוּ.</p>\n<p>וְאִי חַיָּיבָא הוּא, כָּרוֹזָא קָרֵי עֲלֵיהּ בַּגֵּיהִנָּם תְּלָתִין יוֹמִין (עליה), וְכֻלְּהוּ חַיָּיבַיָא, כֻּלְּהוּ עֲצִיבִין.</p>\n<p>כֻּלְּהוּ פָּתְחִין וַוי, דְּהָא דִינָא חַדְתָּא אִתְעַר הַשְׁתָּא, בְּגִינֵיהּ דִּפְלַנְיָא. כַּמָּה גַרְדִינִין דְּנִמּוּסִין מִזְדַּמְּנִין לְקֳבְלֵיהּ, וּלְאַקְדָּמָא לֵיהּ וַוי. אוֹי לָרָשָׁע אוֹי לִשְׁכֵנוֹ. וְכֻלְּהוּ פָּתְחִין וְאָמְרִין, (ישעיהו ג׳:י״א) אוֹי לְרָשָׁע רָע כִּי גְמוּל יָדָיו יֵעָשֶׂה לוֹ. מַאי (טעמא) גְּמוּל יָדָיו. אָמַר רִבִּי יִצְחָק. לְאַכְלָלָא (לאפקא) מַאן דְּזָנֵי בִּידוֹי, לְאֲפָקָא וּלְחַבְּלָא זַרְעֵיהּ בְּרֵיקַנְיָא (ס\"ט ע\"א).</p>\n<p>דְּהָא תָּנִינָן, כָּל מַאן דְּאַפִּיק זַרְעֵיהּ בְּרֵיקַנְיָא, אִקְרֵי רָע, וְלָא חָמֵי אַפֵּי שְׁכִינְתָּא. דִּכְתִיב, (תהילים ה׳:ה׳) כִּי לא אֵל חָפֵץ רֶשַׁע אַתָּה לא יְגוּרְךָ רָע. וּכְתִיב, (בראשית ל״ח:ז׳) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע. אוּף הָכָא, אוֹי לְרָשָׁע רָע. וַוי לְהַהוּא חַיָּיבָא דְּאִיהוּ רַע, דְּעֲבַד גַּרְמֵיהּ רַע. כִּי גְמוּל יָדָיו יֵעָשֶׂה לוֹ, לְאַכְלָלָא מַאן דְּזָנֵי בִּידוֹי, לְאֲפָקָא וּלְחַבְּלָא זַרְעֵיהּ בְרֵיקַנְיָא, וּלְהַאי טָרְדִין בְּהַהוּא עַלְמָא יַתִּיר מִכֹּלָּא.</p>\n<p>תָּא חֲזֵי, דְּהָא כְּתִיב אוֹי לְרָשָׁע (רע), כֵּיוָן דִּכְתִיב אוֹי לְרָשָׁע, אַמַּאי רָע. אֶלָא כְּמָה דְּאֲמִינָא, דְּעֲבַד גַּרְמֵיהּ רָע. וּכְתִיב לֹא יְגוּרְךָ רָע. וְכֻלְּהוּ סָלְקִין, וְהַאי לָא סָלִיק. וְאִי תֵימָא, שְׁאָר חַיָּיבִין דְּקָטְלוּ בְּנֵי נָשָׁא. תָּא חֲזֵי, כֻּלְּהוּ סָלְקִין וְהוּא לָא סָלִיק. מַאי טַעְמָא, אִינוּן קְטִילוּ בְּנֵי נָשָׁא אָחֳרָא, וְהַאי קָטִיל בְּנוֹי מַמָּשׁ, אוֹשִׁיד דָּמִין סַגִּיאִין. תָּא חֲזֵי, בִּשְׁאָר חַיָּיבֵי עַלְמָא, לָא כְּתִיב וַיֵּרַע בְּעֵינֵי ה', וְכָאן כְּתִיב, וַיֵּרַע בְּעֵינֵי ה' אֲשֶׁר עָשָׂה. מַאי טַעְמָא, מִשּׁוּם דִּכְתִיב וְשִׁחֵת אַרְצָה.</p>\n<p>תְּנַן, אָמַר רִבִּי יְהוּדָה, לֵית לָךְ חוֹבָא בְּעַלְמָא דְּלָא אִית לֵיהּ תְּשׁוּבָה, בַּר מֵהַאי. וְלֵית לָךְ חַיָּיבַיָא דְּלָא חָמָאן אַפֵּי שְׁכִינְתָּא, בַּר מֵהַאי. דִּכְתִיב לא יְגוּרְךָ רָע, כְּלַל. אָמַר רִבִּי יִצְחָק, זַכָּאִין אִינוּן צַדִּיקַיָיא, בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי. עֲלַיְיהוּ כְּתִיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. מַאי לְעוֹלָם יִירְשׁוּ אָרֶץ, אָמַר רִבִּי יְהוּדָה, כְּמָה דִכְתִיב, (תהלים קטו) אֶתְהַלֵּךְ לִפְנֵי ה' בְּאַרְצוֹת הַחַיִּים:</p>"],[9520011448,"<p>וַיְחִי יַעֲקֹב (שייך ויקרא ק\"ד ע\"ב) בְּגַוַּיְיהוּ. (בד\"ק נמצא בח\"ג בדף נ' עמוד קצ\"ט) עַל דָּא לִבָּעֵי לֵיהּ לְבַר נָשׁ דְּלָא לְאִתְעַרְבָא צוּלְמָא דִילֵיהּ <Nonei></i>בְּצוּלְמָא דְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת, בְּגִין דְּהַאי קַדִּישָׁא וְהַאי מְסָאֲבָא.</p>\n<p>תָּא חֲזֵי, מַה בֵּין יִשְׂרָאֵל לְעַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. דְּיִשְׂרָאֵל כַּד אִשְׁתַּכַּח בַּר נָשׁ מִית הוּא מְסָאַב לְכָל גּוּפָא, וּבֵיתָא מְסָאֲבָא. וְגוּפָא דְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת לָא מַסְאִיב לְאָחֳרָא, וְגוּפֵיהּ (נ\"א וביתא) לָא מְסָאֲבָא כַּד אִיהוּ מִית. מַאי טַעְמָא.</p>\n<p>יִשְׂרָאֵל בְּשַׁעְתָּא דְאִיהוּ מִית כָּל קִדּוּשֵׁי דְּמָארֵיהּ מִתְעַבְרָן מִנֵּיהּ, אִתְעֲבַר מִנֵּיהּ הַאי צוּלְמָא קַדִּישָׁא, וְאִתְעֲבַר מִנֵּיהּ הַאי רוּחַ קוּדְשָׁא, אִשְׁתָּאַר גּוּפָא מְסָאֲבָא.</p>\n<p>אֲבָל עוֹבֵד כּוֹכָבִים וּמַזָּלוֹת עוֹבֵד עֲבוֹדָה זָרָה, לֵית הָכִי. דִּבְחַיֵּי מְסָאַב בְּכָל סִטְרִין, צוּלְמָא דִילֵיהּ מְסָאֲבָא, וְרוּחָא דִילֵיהּ מְסָאֲבָא. וּבְגִין דְּסוֹאֲבוּתֵי אִלֵּין שַׁרְיָין בְּגַוֵּיהּ, אָסִיר לְמִקְרַב לְגַבֵּיהּ. כֵּיוָן דְּמִית, נָפְקֵי כָּל אִלֵּין מְסָאֲבוּתָא וְאִשְׁתָּאַר גּוּפָא בְּלָא מְסָאֲבוּתָא לְסוֹאֲבָא.</p>\n<p>וְאַף עַל גַּב דְּגוּפָא דִּלְהוֹן מְסָאַב, בֵּין בְּחַיֵּיהוֹן וּבֵין בְּמִיתַתְהוֹן. אֲבָל בְּחַיֵּיהוֹן דְּכָל אִינוּן מְסָאֲבִין אִשְׁתַּכְּחֵי לְגַבַּיְיהוּ, אִית לוֹן חֵילָא לְסוֹאֲבָא לְאַחֲרִינִי, בְּמִיתַתְהוֹן דְּנָפְקֵי כָּל אִינוּן מְסָאֲבִין מִנַּיְיהוּ, לָא יָכְלִין לְסָאֲבָא. וּדְיִשְׂרָאֵל, יָכִיל לְסָאֲבָא לְאַחֲרִינֵי. בְּגִין דְּכָל קַדִּישִׁין נָפְקִין מִנֵּיהּ וְשָׁרָא עֲלֵיהּ סִטְרָא אָחֳרָא.</p>\n<p>תָּא חֲזֵי, הַאי צֶלֶם קַדִּישָׁא, כַד אָזִיל בַּר נָשׁ וְאִתְרַבֵּי, וְאִתְעֲבִיד מֵהַאי פַּרְצוּפָא דִיוּקְנָא דִילֵיהּ. אִתְעֲבִיד צוּלְמָא אָחֳרָא, וּמִתְחַבְּרָן כְּחֲדָא. וְדָא נָטִיל לְדָא, בְּשַׁעְתָּא דְּאִשְׁתַּכְּחוּ תְּרֵין צוּלְמִין, נָטִיר הוּא בַּר נָשׁ, וְגוּפָא דִילֵיהּ בְּקִיּוּמָא, וְרוּחֵיהּ שַׁרְיָא בְּגַוֵּיהּ.</p>\n<p>בְּשַׁעְתָּא דְּקָרִיבוּ יוֹמוֹי, מִתְעַבְרָן מִנֵּיהּ, וְדָא סָלִיק לְדָא, וְאִשְׁתָּאַר בַּר נָשׁ בְּלָא נְטִירוּ. כְּדֵין, (שיר השירים ב׳:י״ז) עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים, תְּרֵי.</p>\n<p>תָּא חֲזֵי, כַּד אִתְעַר דִּינָא בְּעַלְמָא, דְּקוּדְשָׁא בְּרִיךְ הוּא יָתִיב עַל כָּרְסֵי דְּדִינָא לְמֵידַן עַלְמָא, בָּעֵי בַּר נָשׁ לְאַתְעָרָא (בדינא) תְּשׁוּבָה, דְּיֵיתוּב מֵחִיּוּבָא (נ\"א מחובוי). דְּהָא הַהוּא יוֹמָא, פִּתְקִין כְּתִיבוּ, וּמִשְׁתַּכְּחֵי כֻּלְּהוּ בְּאַחְמָתָא הָא כְתִיבִין. אִי זָכֵי בַּר נָשׁ דְּיֵיתוּב קַמֵּי מָארֵיהּ, קָרְעִין פִּתְקִין דְּעֲלֵיהּ.</p>\n<p>לְבָתַר קוּדְשָׁא בְּרִיךְ הוּא זַמִּין קַמֵּיהּ דְבַּר נָשׁ, יוֹמָא דְכִפּוּרֵי יוֹמָא דִתְשׁוּבָה. אִי תָב מֵחֶטְאוֹי טַב. וְאִי לָא, פַּקִּיד מַלְכָּא לְמִחְתַּם פִּתְקִין. וַוי, דְּהָא תְּשׁוּבָה בַּעְיָא לְאִסְתַּלָּקָא מִנֵּיהּ.</p>\n<p>אִי זָכֵי בִּתְשׁוּבָה, וְלָא שְׁלֵימָתָא כְּדְקָא יְאוּת, תַּלְיָין לֵיהּ עַד הַהוּא יוֹמָא בַּתְרָאָה דַּעֲצֶרֶת, דְּהוּא תְּמִינָאָה לֶחָג. וְאִי עֲבַד תְּשׁוּבָה שְׁלֵימָתָא לְקַמֵּי מָארֵיהּ, אִתְקְרָעוּ. וְאִי לָא זָכֵי, אִינוּן פִּתְקִין נָפְקִין מִבֵּי מַלְכָּא, וְאִתְמַסְּרָן בִּידוֹי דְּסַנְטִירָא, וְדִינָא מִתְעֲבִיד, וּפִתְקִין לָא מְהַדְּרָן תוּ לְבֵי מַלְכָּא.</p>\n<p>כְּדֵין צוּלְמִין אִתְעֲבָרוּ מִנִּיהּ, וְלָא מִשְׁתַּכְּחִין עִמֵּיהּ. כֵּיוָן דְּמִתְעַבְרָן מִנֵּיהּ, הָא וַדַּאי טוּפְסְקָא דְמַלְכָּא יַעֲבֹר עֲלֵיהּ, וְיִטְעוֹם כַּסָּא דְמוֹתָא. וּבְהַהוּא לֵילְיָא דְּחַגָּא בַּתְרָאָה, סַנְטֵירִין זְמִינִין, וּפִתְקִין נָטְלִין, בָּתַר דְּנַטְלֵי לוֹן, צוּלְמִין מִתְעַבְרָן, וְלָא מִשְׁתַּכְּחִין (נ\"א ואי משתכחין גריעין יעבר עלוי מרעין וכו') בְּהוּ יָדֵי. וְאִי מִשְׁתַּכְּחִין בְּהוּ יָדֵי (יעדי), דִּינָא גְרִיעָא, אוֹ יַעֲבֹר עֲלוֹי דִּינָא מַרְעִין בִּישִׁין, בִּגְרִיעוּתָא דִּלְהוֹן, וְהָא אוֹקִימְנָא לְהָא.</p>\n<p>וּבְסִפְרֵי קַדְמָאֵי אַמְרֵי יַתִּיר, כַּד רֵישָׁא אִגְרַע, וְיִשְׁתַּכַּח גּוּפָא. בְּרֵיהּ, אוֹ אִנְתְתֵיהּ יִשְׁתַּכָּחוּ וְהוּא יִסְתַּלֵּק. וְהָנִי מִילֵי, כַּד לָא אַהֲדַר כָּל הַהוּא זִמְנָא בִּתְיוּבְתָּא. אֲבָל אִי אַהֲדַר, טַעֲמָא דְמוֹתָא יִטְעַם, וְיִתְּסֵי.</p>\n<p>וְאִי גוּפָא לָא אִתְחֲזֵי, וְיִשְׁתַּכַּח רֵישָׁא. אִינוּן סָלְקִין, וְהוּא אִתְקַיֵּים. וְהָנֵי מִילֵי, כַּד בְּרֵיהּ זְעֵירָא בִּרְשׁוּתֵיהּ.</p>\n<p>וְאִי יְדוֹי פְּגִימוּ, עֲבִידְתָּא דִידוֹי פְּגִימִין. רַגְלוֹי, מַרְעִין רָדְפִין עֲלֵיהּ. עָרַק צוּלְמָא וְאַהֲדַר, עָרַק וְאַהֲדַר. עֲלֵיהּ כְּתִיב, (דברים כ״ח:ס״ז) בַּבֹּקֶר תֹּאמַר מִי יִתֵּן עֶרֶב, וְהַאי כַּד נָהֲרָא סִיהֲרָא, וְלֵילְיָא אִתְתַּקַּן בִּנְהוֹרָא.</p>\n<p>אֲבָל זַכָּאֵי חֲסִידֵי, בְּכָל יוֹמָא וְיוֹמָא מִסְתַּכְּלֵי בְּלִבַּיְיהוּ, כְּאִלּוּ הַהוּא יוֹמָא מִסְתַּלְּקֵי מֵעַלְמָא, וְעָבְדִין תְּיוּבְתָּא שְׁלֵימָתָא קַמֵּי מָארֵיהוֹן, וְלָא יִצְטָרְכוּן לְמִלָּה אָחֳרָא. זַכָּאָה חוּלְקֵהוֹן בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי.</p>"],[9520011449,"<p>תָּא חֲזֵי, (ישעיהו מ״ג:ז׳) כָּל הַנִּקְרָא בִּשְׁמִי, כַּמָּה עִלָּאִין עוֹבָדֵי מַלְכָּא קַדִּישָׁא, דְּהָא בְּאִינוּן עוֹבָדֵי (נ\"א בריין) דְאִיהוּ עָבִיד לְתַתָּא קָטִיר לוֹן בְּמִלִּין עִלָּאִין דִּלְעֵילָא, וְכַד נָטְלִין לוֹן לְתַתָּא וְעָבְדֵי בְּהוּ עוֹבָדָא, אִתְעַר הַהוּא עוֹבָדָא דִלְעֵילָא דְּקָטִיר בָּהּ. כְּגוֹן אֵזוֹבָא, עֵץ אֶרֶז, וְהָא אוֹקִימְנָא <Nonei></i>מִלֵּי.</p>\n<p>וְאִית מִנַּיְיהוּ דְּאֲחִידָן בִּשְׁמָא קַדִּישָׁא, כְּגוֹן (ויקרא כד ע\"א) לוּלָב, וְאֶתְרוֹג, הֲדָס, וַעֲרָבָה, דְּכֻלְּהוּ אֲחִידָן בִּשְׁמָא קַדִּישָׁא לְעֵילָא. וְעַל דָּא תָּנִינָן, לְאַחֲדָא לוֹן, וּלְמֶעְבַּד בְּהוּ עוֹבָדָא, בְּגִין לְאִתְעָרָא חֶדְוָה הַהוּא דְאָחִיד בֵּיהּ. וְעַל דָּא תָּנִינָן, בְּמִלִּין וְעוֹבָדָא בָּעְיָין לְאַחֲזָאָה מִלָּה, בְּגִין לְאִתְעָרָא מִלָּה אָחֳרָא.</p>\n<p>הֲדָא הוּא דִכְתִיב, כָּל הַנִּקְרָא בִּשְׁמִי וְלִכְבוֹדִי (בראתיו), לְאַתְעָרָא יְקָרִי. בְּרָאתִיו, לְיַיחֲדָא לִי. יְצַרְתִּיו, לְמֶעְבַּד בֵּיהּ עוֹבָדָא (נ\"א חילא). אַף עֲשִׂיתִיו, לְאַתְעָרָא בֵּיהּ חֵילָא דִּלְעֵילָא.</p>\n<p>דָּבָר אַחֵר, כָּל הַנִּקְרָא בִּשְׁמִי, הַיְינוּ דִכְתִיב (ויקרא כ״ג:מ׳) פְּרִי עֵץ הָדָר. וְלִכְבוֹדִי בְּרָאתִיו, הַיְינוּ כַּפּוֹת תְּמָרִים. יְצַרְתִּיו, הַיְינוּ וַעֲנַף עֵץ עָבוֹת. אַף עֲשִׂיתִיו, הַיְינוּ וְעַרְבֵי נָחַל.</p>\n<p>וְתִקּוּנָא דְהַאי דְאָמַר קְרָא, (ויקרא כ״ג:מ׳) וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן, דַּיְיקָא. דְּהוּא חֲמִישָׁאָה עַל עָשׂוֹר.</p>\n<p>אֲבָל בַּיּוֹם הָרִאשׁוֹן, הַהוּא יוֹם רִאשׁוֹן מַאן הוּא. אֶלָּא יוֹם דְּנָפִיק רִאשׁוֹן, לְנַטְלָא (ד\"א לכלא) בְּמַבּוּעוֹי דְּמַיִין נְבִיעִין, וְאֲנַן בָּעְיָין לְאַמְשָׁכָא לֵיהּ לְעָלְמָא.</p>\n<p>מְתַל לְמַלְכָּא דְּקָטַר בְּנֵי נָשָׁא בְּקִטְרוֹי, אִמֵּיהּ מַטְרוֹנִיתָא אָתַת, וַאֲפִיקַת לוֹן לְחֵירוּת, וּמַלְכָּא אַשְׁגַּח לִיקָרָא דִילָהּ, וְיָהַב לוֹן בִּידָהָא. אַשְׁכָּחַת לוֹן כַּיְיפִין וְצַחִין, אֲמָרַתְּ, הָא אֲפִיקַת לוֹן לְחֵירוּ, אַיְיתֵי לוֹן מֵיכְלָא וּמִשְׁתַּיָּיא.</p>\n<p>כָּךָ, הָא יוֹם הַכִּפּוּרִים אַפִּיק לְכֹלָּא לְחֵירוּ, וְאֲנַן כַּפְנִי מְזוֹנָא קָאִימְנָא, וְצַחִינָן לְמִשְׁתַּיָּא, הִיא אַעֲטָרַת לְמַלְכָּא בְּעִטְּרוֹי. בְּהַאי יוֹמָא יְדַעְנָא, דְּהָא מַיִין נְבִיעִין עִמָּהּ שַׁרְיָין, שָׁאִילְנָא לְמִשְׁתַּיָּיא, לְמַאן דְּאַפִּיק לוֹן לְחֵירוּ. וְעַל דָּא קָרִינָן לֵיהּ יוֹם רִאשׁוֹן.</p>\n<p>דָּא בְּסִפְרָא דְּאַגַּדְתָּא וְשַׁפִּיר הוּא. אֲבָל בְּהַאי יוֹמָא, לְאַבְרָהָם שֵׁירוּתָא דְּכֹלָּא, אִי בַּעֲנָנֵי יְקָר הוּא שֵׁירוּתָא, אִי בְּמַיָא הוּא שֵׁירוּתָא. דְּאַבְרָהָם שָׁארֵי לְמֶחְפְּרִי בֵּיִרִי דְמַיָא.</p>\n<p>פְּרִי עֵץ הָדָר, דָּא בֵּירָא דְיִצְחָק, דְּיִצְחָק אַהֲדַר לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא וְקָרָא לֵיהּ עֵץ הָדָר. פְּרִי דְּהַאי עֵץ הָדָר יְדִיעָא. כַּפּוֹת תְּמָרִים, דִּכְתִיב, (תהילים צ״ב:י״ג) צַדִּיק כַּתָּמָר יִפְרָח, וְלָא אִשְׁתַּכַּח בֵּינַיְיהוּ פִּירוּדָא. וְעַל דָּא לָא כְּתִיב וְכַפּוֹת, אֶלָּא כַּפּוֹת. בְּגִין דְּלָא סָלִיק דָּא בְּלָא דָא, וּבְהַאי אִתְמַלְיָיא הַאי בְּאֵר, מִבְּאֵר מַיִם עִלָּאִין נְבִיעִין, הַהוּא אִתְמַלֵּי בְּקַדְמִיתָא, וּמִנֵּיהּ אִתְמַלְיָיא בֵּירָא, עַד דְּאִיהוּ נְבִיעוּ לְכֹלָּא.</p>\n<p>וַעֲנַף עֵץ עָבוֹת, דָּא עֲנָפָא דְאִילָנָא רַבְרְבָא, דְּאַתְקִיף וְאִשְׁתַּרְשָׁא בְּשָׁרְשׁוֹי, אִתְעֲבִיד אִילָנָא עִלָּאָה עַל כֹּלָּא, דְּאָחִיד בְּכָל סִטְרֵיהּ, עָנָף דְּאִיהוּ עֵץ עָבוֹת, עֵץ דְּאָחִיד לֶעָבוֹת, דְּהָא מֵהַאי נָטַל יְסוֹדָא דְעַלְמָא, וְאִתְמַלְּיָא לַאֲרָקָא בְּבֵירָא, הַאי הוּא עַלְמָא אֲרָקָא דְּשַׁקְיוּתָא.</p>\n<p>וְעַרְבֵי נַחַל, תְּרֵי אִינוּן, תְּרֵין נַחֲלִין דְמַיָּיא אִתְכְּנִישׁ בְּהוּ, לַאֲרָקָא לַצַּדִּיק. דָּבָר אַחֵר, וְעַרְבֵי נַחַל, אִלֵּין אִינוּן גְּבוּרָן, דְּאֲחִידָן בֵּיהּ בְּיִצְחָק, דְּאַתְיָין מִסִּטְרָא דְהַהוּא נַחַל עִלָּאָה, וְלָא מִסִּטְרָא דְאַבָּא. בְגִין כָּךְ, כֹּלָּא יָאֵי, וְלָא בְּסִימָא לְפֵירִין, וְלָא עָבִיד פֵּירִין.</p>\n<p>וְעַרְבֵי נַחַל, תְּרֵין קְיָימִין, דְּגוּפָא קָיְימָא עֲלַיְיהוּ, אֲבָל וְעַרְבֵי נַחַל וַדַּאי, כְּמָה דְאִתְּמָר, וְאִלֵּין אִינוּן כֻּלְּהוּ לַאֲרָקָא מַיָּיא לְבֵירָא.</p>\n<p>דָּבָר אַחֵר, וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן פְּרִי עֵץ הָדָר, דָּא אַבְרָהָם. כַּפֹּת תְּמָרִים, דָּא יִצְחָק. וַעֲנַף עֵץ עָבוֹת, דָּא יַעֲקֹב. וְעַרְבֵי נָחַל, אִלֵּין אִינוּן תְּרֵין דַּרְגִּין דְּאֲמָרָן.</p>\n<p>וּמַאן דְּמַתְנֵי הַאי, בְּגִין דְּעֵץ עָבוֹת דָּא יַעֲקֹב, דְּאָחִיד לְכֻלְּהוּ חֲלָקִין, וַדַּאי דָּא יַעֲקֹב. אֲבָל הָא אוֹקִימְנָא, פְּרִי עֵץ הָדָר דָּא בֵּירָא דְּיִצְחָק, דָּא גְבוּרָה תַּתָּאָה. כַּפֹּת תְּמָרִים. כַּפֹּת חָסֵר, קִשּׁוּרָא דְאִתְקַשַּׁר בְּבֵירָא, כְּמָא דְאַתְּ אָמֵר, (דניאל ג׳:כ״א) כְּפִיתוּ בְּסַרְבָּלֵיהוֹן, בְּגִין דְּאִלֵּין לָא סָלְקִין דָּא בְּלָא דָא. וַעֲנַף עֵץ עָבוֹת, עֲנָפָא הוּא עִלָּאָה, דְּאִתְעֲבִיד עֵץ עָבוֹת, וְאָחִיד לְכָל סִטְרָא, כְּמָה דְּאִתְּמָר. עַרְבֵי נַחַל דָּא יִצְחָק, בְּכָל סִטְרֵי, דְּאֲחִידָן בְּסִטְרָא דְנַחֲלָא, וְלָא בְּסִטְרָא דְאַבָּא. דְּתָנִינָן, אַף עַל גַּב דִּבְהַאי נַחַל דִּינָא לָא אִשְׁתַּכַּח בֵּיהּ, דִּינִין מִתְעָרִין מִנֵּיהּ.</p>\n<p>וְרַב הַמְנוּנָא סָבָא פָּרִישׁ, וְעַרְבֵי נַחַל, אִינוּן תְּרֵין קָיְימִין דְּקָאֲמָרָן, דְּמַיָּיא נָפְקֵי מִנַּיְיהוּ, וְשַׁפִּיר. אֲבָל תָּא חֲזֵי, הָא חָזִינָן דִּתְרֵין דַּרְגִּין אִלֵּין דְּקָיְימֵי עַל דַּרְגָּא דְצַדִּיק, אִיבָּא וּכְנִישׁוּ רַבְרְבָא (ס\"א דברכאן) נָפְקֵי מִנַּיְיהוּ, וְעַרְבֵי נַחַל לָא נָפְקֵי מִנַּיְיהוּ, אִיבָּא, וְלָא טַעְמָא, וְלָא רֵיחָא. וְהָא אוֹקִימְנָא וְכֹלָּא שַׁפִּיר.</p>\n<p>וְעַל דָּא אֶתְרוֹג <Nonei></i>בִּשְׂמָאלָא, לָקֳבֵיל לִבָּא. לוּלָב בִּימִינָא, כַּפֹּת בְּכֹלָּא, וְקָטִיר בְּכֹלָּא. דְּהָא צַדִּיק כַּפּוֹת הוּא בְּכָל סִטְרִין, וְקָטִיר בְּכֹלָּא, וְדָא הוּא קִשּׁוּרָא דִּמְהֵימְנוּתָא.</p>\n<p>וּבְסִפְרָא דְּאַגַּדְתָּא שַׁפִּיר קָאֲמַר, דְּכָל אִלֵּין אִינוּן אוּשְׁפִּיזִין, דְּזַמִּינִין עַמָּא קַדִּישָׁא בְּהַאי יוֹמָא, דְּבַעְיָין לְאַשְׁכָּחָא לְהוּ, כֵּיוָן דְּזַמִּין לוֹן. וּבְהוּ בָּעֵי בַּר נָשׁ לְמַלְכָּא בָּעוּתֵיהּ. זַכָּאִין אִינוּן יִשְׂרָאֵל דְּיָדְעִין אָרְחוֹי דְמַלְכָּא קַדִּישָׁא, וְיָדְעִין אָרְחוֹי דְאוֹרַיְיתָא, לְמֵהַךְ בְּאוֹרַח קְשׁוֹט, לְמִזְכֵּי בְּהוּ בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי.</p>\n<p>בְּיוֹמָא דָא נָפְקֵי יִשְׂרָאֵל, בְּסִימָנִין רְשִׁימִין מִגּוֹ מַלְכָּא, בְּגִין דְּאִינוּן נָצְחִין דִּינָא. וּמַאי סִימָנִין אִינוּן, סִימָנֵי מְהֵימְנוּתָא, חוֹתָמָא דְמַלְכָּא עִלָּאָה. לִתְרֵי בְּנִי נָשָׁא, דְּעָאלוּ קֳדָם מַלְכָּא לְדִינָא, וְלָא יָדְעֵי עַלְמָא מַאן מִנַּיְיהוּ נָצַח. נָפַק חַד לִגְיוֹן מִבֵּי מַלְכָּא, שְׁאִילוּ לוֹ. אָמַר לוֹן, מַאן דְּיִפּוּק וּבִידוֹי סִימָנִין דְּמַלְכָּא, הוּא נָצַח.</p>\n<p>כָּךָ, כּוּלֵי עַלְמָא עָאלִין לְדִינָא, קֳדָם מַלְכָּא עִלָּאָה, וְדָאִין לוֹן מִיּוֹמָא דְרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים, עַד חֲמֵשׁ סָרֵי יוֹמִין לְיַרְחָא. וּבֵין כָּךְ אִשְׁתַּכָּחוּ יִשְׂרָאֵל זַכָּאִין כֻּלְּהוּ בִּתְיוּבְתָּא. טָרְחִין בְּסֻכָּה וְלוּלָב וְאֶתְרוֹג, וְלָא יָדְעֵי מַאן נָצַח דִּינָא. מַלְאֲכֵי עִלָּאֵי שָׁאֲלוּ מַאן נָצַח דִּינָא. קוּדְשָׁא בְּרִיךְ הוּא אָמַר לְהוּ, אִינוּן דְּמַפְקֵי בִּידַיְיהוּ סִימָנִין דִּילִי, אִינוּן נָצְחִין דִּינָא.</p>\n<p>בְּהַאי יוֹמָא, נָפְקֵי יִשְׂרָאֵל בִּרְשִׁימוּ דְמַלְכָּא, בְּתוּשְׁבַּחְתָּא דְּהַלֵּילָא. עָאלִין בַּסֻּכָּה, אֶתְרוֹג בִּשְׂמָאלָא, לוּלָב בִּימִינָא. חָמָאן כֻּלְּהוּ, דְּיִשְׂרָאֵל רְשִׁימִין בִּרְשִׁימִין דְּמַלְכָּא קַדִּישָׁא. פָּתְחֵי וְאָמְרֵי, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלהָיו.</p>\n<p>עַד כָּאן חֶדְוָותָא דְכֹלָּא, חֶדְוָותָא דְאוּשְׁפִּיזִין, וְאֲפִילּוּ אוּמּוֹת הָעוֹלָם חָדָאן בְּחֶדְוָותָא, וּמִתְבָּרְכִין מִנָּהּ. וְעַל דָּא (מקריבין) קָרְבָּנִין בְּכָל יוֹמָא עֲלַיְיהוּ, לַאֲטָלָא עֲלַיְיהוּ שְׁלָם, וְיִתְבָּרְכוּן מִינָן. מִכָּאן וּלְהָלְאָה, יוֹמָא חַד, דְּמַלְכָּא עִלָּאָה, דְּחָדֵי בְּהוּ בְּיִשְׂרָאֵל. דִּכְתִיב, (במדבר כ״ט:ל״ה) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. דְּהָא יוֹמָא דָא מִן מַלְכָּא בִּלְחוֹדוֹי, חֶדְוָותָא דִילֵיהּ בְּיִשְׂרָאֵל. לְמַלְכָּא דְּזַמִּין אוּשְׁפִּיזִין וְכוּ'.</p>"],[9520011450,"<p>רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (שיר השירים ב׳:א׳) אֲנִי חֲבַצֶּלֶת הַשָּׁרוֹן שׁוֹשַׁנַּת הָעֲמָקִים, כַּמָּה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּקוּדְשָׁא בְּרִיךְ הוּא מְשַׁבַּח לָהּ, וְהִיא מְשַׁבַּחַת לֵיהּ תָּדִיר, וְכַמָּה מְשַׁבְּחִין וּמְזַמְּרִין אַזְמִינַת לֵיהּ תָּדִיר לְקוּדְשָׁא בְּרִיךְ הוּא. זַכָּאָה חוּלְקֵהוֹן דְּיִשְׂרָאֵל, דְּאֲחִידָן בֵּיהּ בְּעַדְבָא דְחוּלָקָא קַדִּישָׁא. כְּמָה דִכְתִיב, (דברים ל״ב:ט׳) כִּי חֵלֶק ה' עַמּוֹ וְגו'.</p>\n<p>אֲנִי חֲבַצֶּלֶת הַשָּׁרוֹן, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּקַיְימָא בְּשַׁפִּירוּ דְּנוֹי בְּגִנְתָא דְעֵדֶן. הַשָּׁרוֹן, דְּהִיא שָׁרָה וּמְשַׁבַּחַת לְמַלְכָּא עִלָּאָה.</p>\n<p>דָּבָר אַחֵר אֲנִי חֲבַצֶּלֶת הַשָּׁרוֹן, דְּבָעְיָא לְאַשְׁקָאָה מִשַּׁקְיוּ דְנַחֲלָא עֲמִיקָא, מַבּוּעָא דְּנַחֲלִין. כְּמָא דְאַתְּ אָמֵר, (ישעיהו ל״ה:ז׳) וְהָיָה הַשָּׁרָב לְאַגַּם. (נ\"א (ישעיהו ל״ג:ט׳) והיה השרון כערבה) שׁוֹשַׁנַּת הָעֲמָקִים, דְּקָיְימָא בַּעֲמִיקְתָא דְּכֹלָּא. מַאן אִינוּן עֲמָקִים. כְּמָא דְאַתְּ אָמֵר, (תהילים ק״ל:א׳) מִמַּעֲמַקִּים קְרָאתִיךָ ה'. חֲבַצֶּלֶת הַשָּׁרוֹן. חֲבַצֶּלֶת, מֵהַהוּא אֲתַר, דְּשַׁקְיוּ דְּנַחֲלִין נָפְקִין וְלָא פָּסְקִין לְעָלְמִין. שׁוֹשַׁנַּת הָעֲמָקִים, שׁוֹשַׁנָּה מֵהַהוּא אֲתַר דְּאִקְרֵי עֲמִיקָא דְכֹלָּא, סָתִים מִכָּל סִטְרִין.</p>\n<p>תָּא חֲזֵי, בְּקַדְמִיתָא יְרוּקָא כַּחֲבַצֶּלֶת, דְּטַרְפִּין דִּילָהּ יְרוּקִין. לְבָתַר שׁוֹשַׁנַּת, סוּמְקָא בִּגְוָונִין חִוְורִין. שׁשַׁנָּה בְּשִׁית טַרְפִּין, שֹׁשַׁנַּת, דְּאִשְׁתְּנִיאַת מִגּווָֹנָא לְגווָֹנָא, וְשַׁנִּיאַת גְּוַונָהָא.</p>\n<p>שֹׁשַׁנַּת, בְּקַדְמִיתָא חֲבַצֶּלֶת, בְּעִדָּנָא דְּבָעְיָא לְאִזְדַּוָּוגָא בֵּיהּ בְּמַלְכָּא, אִקְרֵי חֲבַצֶּלֶת. בָּתַר דְּאִתְדַּבְּקַת בֵּיהּ בְּמַלְכָּא בְּאִינוּן נְשִׁיקִין, אִקְרֵי שֹׂשַׁנַּת. בְּגִין דִּכְתִיב, (שיר השירים ה׳:י״ג) שִׂפְתוֹתָיו שׁוֹשַׁנִּים. שׁשַׁנַּת הָעֲמָקִים דְּהִיא מְשַׁנְיָיא גְּוָונָהָא, זִמְנִין לְטַב, וְזִמְנִין לְבִישׁ, זִמְנִין לְרַחֲמֵי, זִמְנָא לְדִינָא.</p>\n<p>(בראשית ג׳:ו׳) וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל וְכִי תַּאֲוָה הוּא לָעֵינַיִם. תָּא חֲזֵי, דְּהָא בְּנֵי נָשָׁא לָא מִסְתַּכְּלִין, וְלָא יָדְעִין, וְלָא מַשְׁגִּיחִין. בְּשַׁעְתָּא דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם, וְאוֹקִיר לֵיהּ בִּיקִירוּ עִלָּאָה, בָּעָא מִנֵּיהּ לְאִתְדַּבְּקָא בֵּיהּ בְּגִין דְּיִשְׁתַּכַּח יְחִידָאי, וּבְלִבָּא יְחִידָאי, וּבַאֲתַר דִּדְבֵקוּתָא יְחִידָאי, דְּלָא <Nonei></i>אִשְׁתַּנֵּי, וְלָא מִתְהַפֵּךְ לְעָלְמִין. בְּהַהוּא קִשּׁוּרָא יְחִידָא, דְּכֹלָּא בֵּיהּ אִתְקַשַּׁר. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ט׳) וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן.</p>\n<p>לְבָתַר סָטוּ מֵאָרְחָא דִמְהֵימְנוּתָא, וְשָׁבְקוּ אִילָנָא יְחִידָאי, עִלָּאָה מִכָּל אִילָנִין. וְאָתוּ לְאִתְדַּבְּקָא בְּאֲתַר דְּמִשְׁתַּנֵּי, וּמִתְהַפֵּךְ מִגּווָֹנָא לְגווָֹנָא וּמִטַּב לְבִישׁ וּמִבִּישׁ לְטַב. וְנַחֲתֵי מֵעֵילָא לְתַתָּא, וְאִתְדַּבָּקוּ לְתַתָּא בְּשִׁנּוּיִין סַגִּיאִין. וְשָׁבְקוּ אִילָנָא יְחִידָאָה, עִלָּאָה מִכָּל אִילָנִין. הֲדָא הוּא דִכְתִיב, (קהלת ז׳:כ״ט) אֲשֶׁר עָשָׂה הָאֱלֹהִים אֶת הָאָדָם יָשָׁר וְגו'.</p>\n<p>וַדַּאי כְּדֵין אִתְהַפַּךְ לִבַּיְיהוּ, בְּהַהוּא סִטְרָא מַמָּשׁ, זִמְנִין לְטַב, זִמְנִין לְבִישׁ, זִמְנִין לְרַחֲמֵי, זִמְנִין לְדִינָא. בְּהַאי מִלָּה דְּאִתְדַּבָּקוּ בָּהּ וַדַּאי, (קהלת ז׳:כ״ט) בִקְשׁוּ חִשְׁבוֹנוֹת רַבִּים, וְאִתְדַּבָּקוּ בְּהוּ.</p>\n<p>אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אָדָם, שְׁבַקְתְּ חַיֵּי וְאִתְדָּבַּקְתְּ בְּמוֹתָא. חַיֵּי, דִּכְתִיב וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן, דְּאִקְרֵי חַיִּים. דְּמַאן דְּאָחִיד בֵּיהּ, לָא טָעִים מוֹתָא לְעָלְמִין. אִתְדָּבַּקְתְּ בְּאִילָנָא אָחֳרָא, הָא וַדַּאי מוֹתָא הוּא לְקִבְלָךְ. הֲדָא הוּא דִכְתִיב, (משלי ה׳:ה׳) רַגְלֶיהָ יוֹרְדוֹת מָוֶת, וּכְתִיב, (קהלת ז׳:כ״ו) וּמוֹצֵא אֲנִי מַר מִמָּוֶת אֶת הָאִשָּׁה. וַדַּאי בְּאֲתַר דְּמוֹתָא אִתְדָּבַּק, וְשָׁבַק אֲתַר דְּחַיֵּי. בְּגִין כָּךְ אִתְגְּזַר עֲלֵיהּ וְעַל כָּל עַלְמָא מוֹתָא.</p>\n<p>אִי הוּא חָטָא, כָּל עַלְמָא מַה חָטוּ. אִי תֵימָא, דְּכָל עַלְמָא אָכְלֵי מֵאִילָנָא דָא, וְאִתְרַמֵּי לְכֹלָּא. לָאו הָכִי. אֶלָּא בְּשַׁעְתָּא דְאָדָם קָאִים עַל רַגְלוֹי, חָמֵי לֵיהּ בִּרְיָין כֻּלְּהוּ, וּדְחִילוּ מִקַּמֵּיהּ, וְהֲווּ נָטְלִין אֲבַתְרֵיהּ, כְּעַבְדִין בָּתַר מַלְכָּא. וְהוּא אָמַר לוֹן, אֲנָא וְאַתּוּן, (תהילים צ״ה:ו׳) בֹּאוּ נִשְׁתַּחֲוֶה וְנִכְרָעָה וְגו'. וְאֲזְלוּ כֻּלְּהוּ אֲבַתְרֵיהּ. כֵּיוָן דְּחָזוּ דְּאָדָם סְגִיד לְהַאי אֲתַר, וְאִתְדָּבַּק בֵּיהּ, כֻּלְּהוּ אִתְמַשְּׁכוּ אֲבַתְרֵיהּ וְגָרִים מוֹתָא לְכָל עָלְמָא.</p>\n<p>וּכְדֵין אִשְׁתַּנֵּי אָדָם לְכַמָּה גְּוָונִין, זִמְנִין דִּינָא, זִמְנִין רַחֲמֵי זִמְנִין מוֹתָא, זִמְנִין חַיֵּי. וְלָא קָאִים בְּקִיּוּמָא תָּדִיר בְּחַד מִנַּיְיהוּ, בְּגִין דְּהַהוּא אֲתַר גָּרִים לֵיהּ. וְעַל דָּא אִקְרֵי, חֶרֶב הַמִּתְהַפֶּכֶת, הַמִּתְהַפֶּכֶת מִסִּטְרָא דָא לְסִטְרָא דָא, מִטַּב לְבִישׁ, מֵרַחֲמֵי לְדִינָא, מִשְּׁלָם לְקָרָבָא, מִתְהַפֶּכֶת הִיא בְּכֹלָּא. טַב וְרַע דִּכְתִיב, (בראשית ב׳:ט׳) וְעֵץ הַדַּעַת טוֹב וָרָע.</p>\n<p>וּמַלְכָּא עִלָּאָה, לְרַחֲמָא עַל עוֹבָדוֹי, אוֹכַח לֵיהּ, וְאָמַר לֵיהּ, וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ וְגו', וְהוּא לָא קַבִּיל מִנֵּיהּ, וְאִתְמְשַׁךְ בָּתַר אִתְּתֵיהּ, וְאִתְתָּרַךְ לְעָלְמִין. דְּהָא אִתְּתָא לְאַתְרָא (ס\"א לאתר דא) סַלְקָא וְלָא יַתִּיר, וְאִתְּתָא גָרִים מוֹתָא לְכֹלָּא.</p>\n<p>תָּא חֲזֵי, לְעַלְמָא דְאָתֵי כְּתִיב, (ישעיהו ס״ה:כ״ב) כִּי כִּימֵי הָעֵץ יְמֵי עַמִּי, כִּימֵי הָעֵץ, הַהוּא דְאִשְׁתְּמוֹדָעָא, בֵּיהּ זִמְנָא, כְּתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ וְגו' (עד כאן נדפס בויקרא):</p>"],[9520011451,"<p>וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת. תָּאנָא, אָמַר רִבִּי חִיָּיא, כְּתִיב וַיְחִי יַעֲקֹב בְּאֶרֶץ מִצְרַיִם שְׁבַע עֶשְׂרֵה שָׁנָה, הָתָם בְּקִיּוּמֵיהּ יַעֲקֹב, וְהָכָא בְּמִיתָתֵיהּ יִשְׂרָאֵל. דִּכְתִיב, וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת. אָמַר רִבִּי יוֹסֵי, הָכִי הוּא וַדַּאי, דְּהָא לָא כְּתִיב וַיִּקְרַב יוֹם יִשְׂרָאֵל לָמוּת, אֶלָּא יְמֵי, וְכִי בְּכַמָּה יוֹמֵי מִית בַּר נָשׁ, וְהָא בְּשַׁעְתָא חָדָא, בְּרִגְעָא חָדָא, מִית וְנָפִיק מֵעַלְמָא.</p>\n<p>אֶלָּא הָכִי תָּאנָא, כַּד קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְאֲתָבָא רוּחֵיהּ לֵיהּ, כָּל אִינוּן יוֹמִין דְּקָאִים בַּר נָשׁ בְּהַאי עַלְמָא, אִתְפַּקְדָּן קַמֵּיהּ, וְעָאלִין בְּחוּשְׁבְּנָא. וְכַד אִתְקְרִיבוּ קַמֵּיהּ לְמֵיעַל בְּחוּשְׁבְּנָא, מִית בַּר נָשׁ. וְאָתִיב קוּדְשָׁא בְּרִיךְ הוּא רוּחֵיהּ לֵיהּ, הַהוּא הֶבֶל דְּאַפִּיק וְנָפַח בֵּיהּ, אוֹתְבֵיהּ לְגַבֵּיהּ.</p>\n<p>זַכָּאָה חוּלָקֵיהּ דְּהַהוּא בַּר נָשׁ, דְּיוֹמוֹי אִתְקְרִיבוּ גַּבֵּי מַלְכָּא בְּלָא כִּסּוּפָא, וְלָא דָחֵי יוֹמָא מִנַּיְיהוּ לְבַר, דְּיִשְׁכַּח בְּהַהוּא יוֹמָא, דְּאִתְעֲבִיד בֵּיהּ חוֹבָא. בְּגִין כָּךְ, כְּתִיב בְּצַדִּיקַיָא, קְרִיבָה. (והיך יקרבון) מִשּׁוּם דְּקָרִיבוּ יוֹמוֹי קַמֵּי מַלְכָּא, בְּלָא כִּסּוּפָא.</p>\n<p>וַוי לְרַשִּׁיעַיָא, דְּלָא כְּתִיב בְּהוּ קְרִיבָה, וְהֵיךְ יִקְרְבוּן יוֹמֵי קַמֵּי מַלְכָּא, דְּהָא כָּל יוֹמוֹי בְּחוֹבֵי עַלְמָא אִשְׁתַּכָּחוּ. ובְגִינֵי כָּךְ לָא יִקְרְבוּן קַמֵּי מַלְכָּא, וְלָא יִתְמַנּוּן קַמֵּיהּ, וְלָא יִדָּכְרוּ לְעֵילָא, אֶלָּא אִינוּן שְׁצֵיאָן מִגַּוַּויְיהוּ. עֲלַיְיהוּ כְּתִיב, (משלי ד׳:י״ט) דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה לֹא יָדְעוּ בַּמֶּה יִכָּשֵׁלוּ.</p>\n<p><Nonei></i>וְהָכָא וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל וַדַּאי, בְּלָא כִסּוּפָא, בִּשְׁלֵימוּתָא, בְּחֶדְוָותָא שְׁלִים. וּבְגִינֵי כָּךְ, יְמֵי יִשְׂרָאֵל, דְּהֲוָה שְׁלִים יַתִּיר יִשְׂרָאֵל מִיַּעֲקֹב. וְאִי תֵימָא, וְהָא כְּתִיב, (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם, שְׁלִים. שְׁלִים הֲוָה, וְלָא שְׁלִים בְּדַרְגָּא עִלָּאָה כְּיִשְׂרָאֵל.</p>\n<p>תַּנְיָא, אָמַר רִבִּי יוֹסֵי, בְּשַׁעְתָּא דְיוֹמוֹי דְּבַר נָשׁ אִתְפַּקִּידָן קַמֵי מַלְכָּא, אִית זַכָּאָה דְּאִתְפַּקְּדָן יוֹמוֹי וּרְחִיקִין מִקַּמֵּי מַלְכָּא. וְאִית זַכָּאָה, דְּכַד מִתְפַּקְּדָן יוֹמוֹי, קְרִיבִין וּסְמִיכִין לְמַלְכָּא, וְלָא מִתְרַחֲקִין. בְּלָא כִסּוּפָא עָאלִין, וְקָרִיבִין לְמַלְכָּא. זַכָּאָה חוּלְקֵהוֹן. הֲדָא הוּא דִכְתִיב, וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת.</p>"],[9520011452,"<p>וַיִּקְרָא לִבְנוֹ לְיוֹסֵף, אָמַר רִבִּי יִצְחָק, וְכִי שְׁאָר שִׁבְטִין לָאו בְּנוֹי אִינוּן. אֶלָּא אָמַר רִבִּי אַבָּא, יוֹסֵף בְּנוֹ הֲוָה יַתִּיר מִכֻּלְּהוּ. דְּתָנִינָן, בְּשַׁעְתָּא דְּאִנְתְּתֵיהּ דְּפוֹטִיפַר דְּחָקַת לֵיהּ לְיוֹסֵף, מַה כְּתִיב, (בראשית ל״ט:י״א) וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ וְאֵין אִישׁ מֵאַנְשֵׁי הַבַּיִת. הַאי קְרָא הָכִי מִבָּעֵי לֵיהּ, וְאֵין אִישׁ בַּבַּיִת. מַהוּ מֵאַנְשֵׁי הַבַּיִת. אֶלָּא לְאַכְלָלָא דִּיוּקְנָא דְיַעֲקֹב, דְּהֲוָה תַּמָּן וְאִשְׁתַּכַּח תַּמָּן. וּבְגִינֵי כָּךְ מֵאַנְשֵׁי הַבַּיִת, אֲבָל אִישׁ אָחֳרָא הֲוָה תַּמָּן. כֵּיוָן דְּסָלִיק יוֹסֵף עֵינוֹי, וְחֲמָא דִיוּקְנָא דַאֲבוֹי, יְתִיב בְּקִיּוּמֵיהּ, וְתָב לַאֲחוֹרָא.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, (בראשית ל״ט:ח׳) וַיְמָאֵן וַיֹּאמֶר אֶל אֵשֶׁת אֲדֹנָיו. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אַתְּ אֲמַרְתְּ וַיְמָאֵן, וַיֹּאמֶר. חַיֶּיךָ, וַיְמָאֵן וַיֹּאמֶר אָחֳרָא, יֵיתֵי לְבָרְכָא לִבְנָךְ, וְיִתְבָּרְכוּן בֵּיהּ. הֲדָא הוּא דִכְתִיב, וַיְמָאֵן אָבִיו וַיֹּאמֶר יָדַעְתִּי בְּנִי יָדַעְתִּי.</p>\n<p>כֵּיוָן דְּאָמַר יָדַעְתִּי בְּנִי, אַמַּאי אָמַר, יָדַעְתִּי אָחֳרָא. אֶלָּא אָמַר, יָדַעְתִּי בְּנִי, בְּזִמְנָא דְּקָיְימַת בְּגוּפָךְ דְּאַתְּ בָּרִי, כַּד חָמִית דִּיוּקְנָא דִילִי, וְתָבַת בְּקִיּוּמָךְ. וּבְגִינֵי כָּךְ כְּתִיב, יָדַעְתִּי בְּנִי, יָדַעְתִּי. עַל מַה דְּאֲמַרְתְּ דְּדָא הוּא בּוּכְרָא, גַּם הוּא יִהְיֶה לְעָם וְגַם הוּא יִגְדָּל, וְהָכָא בְּגִין כָּךְ כְּתִיב, וַיִּקְרָא לִבְנוֹ לְיוֹסֵף, לִבְנוֹ לְיוֹסֵף מַמָּשׁ.</p>\n<p>דָּבָר אַחֵר, וַיִּקְרָא לִבְנוֹ לְיוֹסֵף, דְּבְדִיוּקְנָא חַד הֲווּ מִתְחַזְּיָין. דְּכָל מַאן דְּחָמֵי לְיוֹסֵף, הֲוָה אַסְהִיד דִּבְרֵיהּ דְּיַעֲקֹב הֲוָה. רִבִּי יוֹסֵי אָמַר, כֹּלָּא הָכִי הוּא. וְעוֹד דְּיוֹסֵף זָן לֵיהּ וְלִבְנוֹי בְּסִבוּתֵיהּ, וּבְגִינֵי כָּךְ בְּנוֹ מַמָּשׁ, יַתִּיר מִכֻּלְּהוּ. וַיִּקְרָא לִבְנוֹ לְיוֹסֵף, אַמַּאי לְיוֹסֵף וְלָא לְאָחֳרָא. מִשּׁוּם דִּרְשׁוּתָא הֲוָה בִּידֵיהּ לְסַלְקֵיהּ מִתַּמָּן.</p>\n<p>רִבִּי יוֹסֵי אָמַר, כֵּיוָן דְּיַעֲקֹב הֲוָה יָדַע דִּבְנוֹי יִשְׁתַּעְבְּדוּן בְּגָלוּתָא תַּמָּן בְּמִצְרַיִם, אַמַּאי לָא אִתְקַבַּר תַּמָּן בְּגִין דְּיָגִין זְכוּתֵיהּ עַל בְּנוֹי. אַמַּאי בָּעָא לְאִסְתַּלְּקָא מִתַּמָּן. וְהָא כְּתִיב, (תהילים ק״ג:י״ג) כְּרַחֵם אָב עַל בָּנִים, אָן הוּא רַחְמָנוּתָא.</p>\n<p>אֶלָּא הָכִי תָּאנָא, בְּשַׁעְתָּא דְּהֲוָה נָחִית יַעֲקֹב לְמִצְרַיִם, הֲוָה דָחִיל. הֲוָה אָמַר, דִּילְמָא חַס וְשָׁלוֹם יִשְׁתֵּצוּן בָּנַי בֵּינִי עַמְּמַיָא, וְדִילְמָא קוּדְשָׁא בְּרִיךְ הוּא יְסַלֵּק שְׁכִינְתֵּיהּ מִינִי כְּקַדְמִיתָא. מַה כְּתִיב, (בראשית ל״ה:ט׳) וַיֵּרָא אֱלהִים אֶל יַעֲקֹב וְגו'. (בראשית מ״ו:ג׳) (ויאמר אלהים לישראל) אַל תִּירָא מֵרְדָה מִצְרַיְמָה כִּי לְגוֹי גָדוֹל אֲשִׂימְךָ שָׁם. וּמַה דְּאֲמַרְתְּ דִּילְמָא אֲסַלֵּק שְׁכִינָתִּי מִבֵּינָךְ, אָנֹכִי אֵרֵד עִמְּךָ מִצְרָיְמָה.</p>\n<p>אָמַר עוֹד, דָּחִילְנָא דִּילְמָא אִתְקַבַּר תַּמָּן, וְלָא אֶזְכֶּה עִם אֲבָהָתַי. אָמַר לֵיהּ וְאָנֹכִי אֲעַלְךָ גַּם עָלה. אֲעַלְךָ, מִמִּצְרַיִם. גַּם עָלה, לְאִתְקַבְּרָאָה בְּקִבְרָא דַּאֲבָהָתָךְ.</p>\n<p>בְּגִינֵי כָּךְ, בָּעָא לְסַלְקָא גַרְמֵיהּ מִמִצְרַיִם. חַד, דְּלָא יַעַבְדוּן מִנֵּיהּ דַּחֲלָא, דְּהָא חָמָא דְקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְאִתְפְּרָעָא מִדַּחֲלֵיהוֹן. וְחַד, דְּחָמָא דִשְׁכִינְתָּא יְשַׁוֵּי מְדוֹרֵיהּ בֵּין בְּנוֹי בְּגָלוּתָא. וְחַד, בְּגִין דִּיהֵא גּוּפֵיהּ דַּיָּיר בֵּין גּוּפַיְיהוּ דַּאֲבָהָתוֹי לְאִתְכְּלָלָא בֵּינַיְיהוּ, וְלָא יִתְמַנֵּי עִם חַיָּיבַיָא דְמִצְרָאֵי.</p>\n<p>וְתָנִינָן, גּוּפָא דְיַעֲקֹב, אִתְמְשִׁיךְ מִשּׁוּפְרוֹי דְּאָדָם הָרִאשׁוֹן, וְהֲוָה דִּיוּקְנִיהּ דְּיַעֲקֹב, דִּיוּקְנָא עִלָּאָה קַדִּישָׁא. דִּיוּקְנָא דְּכוּרְסְיָא קַדִּישָׁא, וְלָא בָּעָא לְאִתְקְבָרָא בֵּינִי חַיָּיבַיָא. וְרָזָא דְמִלָּה, דְּבַאֲבָהָן לֵית פִּירוּדָא כְּלַל. וְעַל דָּא כְּתִיב וְ שָׁכַבְתִּי עִם אֲבוֹתַי.</p>\n<p>וַיִּקְרָא לִבְנוֹ לְיוֹסֵף, בְּנוֹ, בְּחַד דִּיוּקְנָא דְאַנְפִּין, בְּגִין דְּבִרְעוּתָא דְרוּחָא וְלִבָּא, אוֹלִיד לֵיהּ יַתִּיר מִכֻּלְּהוּ. תָּא חֲזֵי, מַה כְּתִיב, (בראשית ל׳:ט״ו) הַמְעַט קַחְתֵּךְ אֶת אִישִׁי, דְּכָל רְעוּתָא דְיַעֲקֹב בְּרָחֵל הֲוָה, וּבְגִין כָּךְ <Nonei></i>וַיִּקְרָא לִבְנוֹ לְיוֹסֵף.</p>\n<p>תָּאנָא, רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (דברים כ״ט:כ״ח) הַנִּסְתָּרוֹת לַה' אֱלֹקֵינוּ וְגו'. הַנִּסְתָּרוֹת לַה' אֱלקֵינוּ, תָּא חֲזֵי, כַּמָּה אִית לֵיהּ לְבַר נָשׁ לְאִזְדַּהֲרָא מֵחוֹבוֹי, וּלְאִסְתַּכָּלָא דְּלָא יַעֲבָר עַל רְעוּתֵיהּ דְּמָארֵיהּ. דְּתָנִינָן, כָּל מַה דְּבַר נָשׁ עָבִיד בְּהַאי עַלְמָא, בְּסִפְרָא כְּתִיבוּ אִינוּן עוֹבָדִין, וְעָאלִין בְּחוּשְׁבְּנָא קַמֵי מַלְכָּא קַדִּישָׁא, וְכֹלָּא אִתְגַּלְּיָיא קַמֵּיהּ. הֲדָא הוּא דִכְתִיב, (ירמיהו כ״ג:כ״ד) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לא אֶרְאֶנּוּ נְאֻם ה'. אִי הָכִי, אֵיךְ לָא יִסְתַּמַּר בַּר נָשׁ מִלְּמֵיחַב קַמֵּיהּ דְּמָארֵיהּ. וְתָנִינָן, אֲפִילּוּ הַהוּא (מאן) מַה דְּחָשִׁיב בַּר נָשׁ וְאִסְתַּלַּק בִּרְעוּתֵיהּ, כֹּלָּא אִשְׁתַּכַּח קַמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְלָא אִתְאֲבִיד מִנֵּיהּ.</p>\n<p>תָּא חֲזֵי, בְּהַהוּא לֵילְיָא דְּעָאלַת לֵאָה לְגַבֵּיהּ דְּיַעֲקֹב, וְיַהֲבַת לֵיהּ אִינוּן סִימָנִין דְּיָהַב יַעֲקֹב לְרָחֵל, סָלִיק בִּרְעוּתֵיהּ דְּאִיהִי רָחֵל, וְשַׁמַּשׁ שִׁמּוּשָׁא בָּהּ. וְהַהִיא טִפָּה קַדְמִיתָא דְּיַעֲקֹב הֲוַת. דִּכְתִיב, (בראשית מ״ט:ג׳) כֹּחִי וְרֵאשִׁית אוֹנִי, וְסָבַר דְּאִיהִי רָחֵל. קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ גָלֵי עֲמִיקְתָּא וּמְסַתַּרְתָּא, וְיָדַע מַה בַּחֲשׁוֹכָא, סָלִיק הַהוּא רְעוּתָא לְאַתְרֵיהּ, וּבְכֵירוּתָא דִרְאוּבֵן אִסְתַּלַּק לְיוֹסֵף. מָאי טַעְמָא, מִשּׁוּם דְּהָא דְרָחֵל הֲוַת, הַהִיא טִפָּה קַדְמִיתָא דְנָפְקַת מִיַּעֲקֹב. וּבְגִין דְּהֲוַת דִּילָהּ, הַהוּא בְּכֵירוּתָא מַמָּשׁ דִּרְאוּבֵן, יָרִית יוֹסֵף. וְרָחֵל יָרְתָה לְהַהוּא דִילָהּ.</p>\n<p>וּבְגִין כָּךְ, רָזָא דְמִלָּה, לָא אִסְתַּלַּק רְאוּבֵן בִּשְׁמָא כִּשְׁאָר שִׁבְטִין. אֶלָּא רְאוּבֵן. כְּלוֹמַר חֲמוּ בַּר, רְאוּ בֵּן סְתָם. וְהַאי בֵּן לָא אִתְיְדַע שְׁמֵיהּ, וְעַל דָּא לָא קַרְיָא לֵאָה בְּנֵי בְּהַאי שְׁמָא, וְלָא אִקְרֵי רְאוּ בְּנִי, דְּהָא לֵאָה יָדְעַת עוֹבָדָא.</p>\n<p>וְתָנִינָן, גָּלֵי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּיַעֲקֹב לָאו רְעוּתֵיהּ לְמֵיחַב קַמֵּיהּ בְּהַאי, וְלָא אִסְתַּכַּל בִּרְעוּתָא בְּאִתְּתָא אָחֳרָא בְּהַהִיא שַׁעְתָּא, כִּשְׁאָר חַיָּיבֵי עַלְמָא. וְעַל כָּךְ כְּתִיב, (בראשית ל״ה:כ״ב-כ״ג) וַיִּהְיוּ בְּנֵי יַעֲקֹב שְׁנֵים עָשָׂר. דְּהָא בְּנַיְיהוּ דִּשְׁאָר חַיָּיבֵי עַלְמָא דְּעָבְדִין הַהוּא עוֹבָדָא, בִּשְׁמָא אָחֳרָא אִקְרוּן. וְהָא יְדִיעָא מִלָּה דָא לְגַבֵּי חַבְרַיָא, וּבְגִינֵי כָּךְ וַיִּקְרָא לִבְנוֹ לְיוֹסֵף, בְּנוֹ מַמָּשׁ, מִשֵּׁירוּתָא וְסִיּוּמָא (ד\"א ל\"ג בריה) בְּנוֹ הֲוָה.</p>\n<p>תָּאנָא, אָמַר רִבִּי יוֹסֵי, בַּמֶּה אוֹמֵי לֵיהּ יַעֲקֹב לְיוֹסֵף, דִּכְתִיב שִׂים נָא יָדְךָ תַּחַת יְרֵכִי. אֶלָּא בְּהַהוּא אָת קַיָּימָא, דְּהֲוָה רָשִׁים בְּבִשְׂרֵיהּ, דְּדָא חֲשִׁיבוּתָא דְּאֲבָהָן יַתִּיר מִכֹּלָּא. וְהַאי בְּרִית, רָזָא דְיוֹסֵף אִיהוּ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּאַבְרָהָם וּבְיַעֲקֹב כְּתִיב, שִׂים נָא יָדְךָ תַּחַת יְרֵכִי, תְּחוֹת יֻרִכִי, כְּלוֹמַר, בְּהַהוּא אֲתַר דִּרְמִיזָא בִּשְׁמָא קַדִּישָׁא, וְאַפִּיק זַרְעָא קַדִּישָׁא מְהֵימְנָא לְעַלְמָא. בְּיִצְחָק לא כְּתִיב, בְּגִין דְּנָפִיק מִנֵּיהּ עֵשָׂו.</p>\n<p>תוּ, מַאי טַעְמָא הָכָא, שִׂים נָא יָדְךָ תַּחַת יְרֵכִי אַל נָא תִקְבְּרֵנִי בְּמִצְרָיִם. אֶלָּא אָמַר לֵיהּ יַעֲקֹב לְיוֹסֵף, בְּהַאי רְשִׁימָא קַדִּישָׁא אוֹמֵי לִי, דְּאַפִּיק זַרְעָא קַדִּישָׁא מְהֵימְנָא לְעַלְמָא, וְאִתְנְטִיר, וְלָא אִסְתָּאַב לְעָלְמִין. דְּלָא יִתְקַבַּר בֵּין אִינוּן מְסָאֲבִין, דְּלָא נָטְרוּ לֵיהּ לְעָלְמִין. דִּכְתִיב בְּהוּ, (יחזקאל כ״ג:כ׳) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם וְזִרְמַת סוּסִים זִרְמָתָם.</p>\n<p>וְאִי תֵימָא, הָא יוֹסֵף דְּנָטִיר לֵיהּ עַל כֹּלָּא, אַמַּאי אִתְקַבַּר בֵּינַיְיהוּ. אֶלָּא תָּנִינָן, כְּתִיב, (יחזקאל א׳:ג׳) הָיֹה הָיָה דְּבַר ה' אֶל יְחֶזְקֵאל בֶּן בּוּזִי הַכֹּהֵן בְּאֶרֶץ כַּשְׂדִּים עַל נְהַר כְּבָר, וְהָא תָּנִינָן, דִּשְׁכִינְתָּא לָא שַׁרְיָא אֶלָּא בְּאַרְעָא דְיִשְׂרָאֵל. אַמָּאי הָכָא שְׁכִינְתָּא. אֶלָּא עַל נְהַר כְּבָר כְּתִיב, וּכְתִיב וַתְּהִי עָלָיו שָׁם יַד ה'. אוּף הָכָא, יוֹסֵף בְּמַיָא אִתְרַמֵי אֲרוֹנָא דִילֵיהּ. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אִי יוֹסֵף אִסְתַּלַּק מֵהָכָא, גָּלוּתָא לָא אִתְקְיַּים. אֶלָּא תְּהֵא קְבוּרְתֵּיהּ בְּאֲתַר דְּלָא יִסְתָּאַב, וְיִסְבְּלוּן בְּנֵי יִשְׂרָאֵל גָּלוּתָא.</p>\n<p>תָּאנָא, אָמַר רִבִּי יוֹסֵי, חָמָא יַעֲקֹב דְּהָא בְּכֹלָּא אִתְתַּקַּן לְכָרְסְיָא קַדִּישָׁא בַּאֲבָהָן (כאבהן). אָמַר, אִי הָכִי יִתְקַבַּר, הֵיךְ גּוּפָא דָא אֲחִידָא בַּאֲבָהָתָא, וְאֲפִילּוּ מְעַרְתָּא דְּאִתְקַּבַּר תַּמָּן אִקְרֵי כָפֵילְתָּא. בְּגִין דְּכָל מִלָּה דְּכָפֵילְתָּא הוּא תְּרֵין וְחַד, אוּף מְעַרְתָּא תְּרֵין וְחַד.</p>\n<p>וְתָּא חֲזֵי, אַבְהָתָא זָכוּ לְאִתְקַבְּרָא תַּמָּן, אִינוּן וְזִוּוּגַיְיהוּ. יַעֲקֹב <Nonei></i>הוּא וְלֵאָה, מַאי טַעְמָא רָחֵל לָא, וְהָא כְּתִיב, (בראשית כ״ט:ל״א) וְרָחֵל עֲקָרָה, דְּאִיהִי עִקָּרָא דְבֵיתָא. אֶלָּא, לֵאָה זָכְתָה בֵּיהּ, לְאֲפָקָא שִׁית שִׁבְטִין מִגִּזְעָא קַדִּישָׁא בְּעַלְמָא יַתִּיר. וּבְגִינֵי כָּךְ, אִתְיַיהֲבַת עִמֵּיהּ לְזִוּוּגָא בִּמְעַרְתָּא.</p>\n<p>אָמַר רִבִּי יְהוּדָה לֵאָה כָּל יוֹמָהָא, הֲוַת בְּפָרָשַׁת אוֹרְחִין קַיָּימָא, וּבָכַת בְּגִינֵיהּ דְּיַעֲקֹב, כַּד שָׁמְעַת דְּאִיהוּ צַדִּיקָא. וּצְלוֹתָא אַקְדָמַת לֵיהּ. וְהַיְינוּ דִּכְתִיב, (בראשית כ״ט:י״ז) וְעֵינֵי לֵאָה רַכּוֹת, כְּמָה דְאוֹקִימְנָא, דְּמַקְדָּמַת וְיָתְבַת בְּפָרָשַׁת אוֹרְחִין לְמִשְׁאַל.</p>\n<p>רָחֵל לָא נָפְקַת לְאוֹרְחִין לְעַלְמָא. בְּגִינֵי כָּךְ זָכְתָה לֵאָה לְאִתְקַבְּרָא עִמֵּיהּ. וְרָחֵל קַיֶּמֶת קְבוּרָתָהּ בְּפָרָשַׁת אוֹרְחִין וְאִתְקְבָרַת תַּמָּן. הֲדָא הוּא דִכְתִיב, וַאֲנִי בְּבֹאִי מִפַּדָּן מֵתָה עָלַי רָחֵל. מַהוּ עָלַי. עָלַי וַדַּאי, כְּלוֹמַר בְּגִינִי. בְּאֶרֶץ כְּנָעַן בַּדֶּרֶךְ, בְּגִינִי מִיתַת בַּדֶּרֶךְ, דְּלָא נָפְקַת בְּגִינִי לְעָלְמִין כַּאֲחָתָהּ.</p>\n<p>בְגִין כָּךְ, לֵאָה דְּנָפְקַת וּבָכַת בְּפָרָשַׁת אוֹרְחִין בְּגִינֵיהּ דְּיַעֲקֹב, זָכְתָה לְאִתְקְבָרָא עִמֵּיהּ. רָחֵל דְּלָא בָּעַאת לְמֵיפַק וּלְמִשְׁאַל בַּהֲדֵיהּ, בְגִין כָּךְ קְבוּרָתָה בְּפָרָשַׁת אוֹרְחִין. וְרָזָא דְמִלָּה, הָא אוֹקִימְנָא וְאִתְּמָר, דָּא בְּאִתְגַּלְיָא, וְדָא בְּאִתְכַּסְּיָא.</p>\n<p>וְתָּא חֲזֵי, דְּתַנְיָא, דִּמְעִין סַגִּיאִין שָׁדִיאַת הַהִיא צַדֶּקֶת לֵאָה, בְּגִין לְמֶהֱוֵי חוּלָקֵיהּ דְּיַעֲקֹב, וְלָא בְּהַהוּא רָשָׁע דְּעֵשָׂו. וְהַיְינוּ דְּתָנִינָן, כָּל בַּר נָשׁ דְּאוֹשִׁיד דִּמְעִין קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, אַף עַל גַּב דְּאִתְגְּזַר עֲלֵיהּ עוֹנָשָׁא, יִתְקָרַע, וְלָא יָכִיל הַהוּא עוֹנָשָׁא לְשַׁלְּטָאָה בֵּיהּ. מְנָלָן, מִלֵּאָה, דְּהָא לֵאָה אִתְגְּזַר לְמֶהֱוֵי חוּלָקָא דְעֵשָׂו, וְהִיא בְּבָעוּתָא אַקְדִימַת לֵיהּ לְיַעֲקֹב, וְלָא אִתְיְיהִיבַת לֵיהּ לְעֵשָׂו.</p>\n<p>אָמַר רִבִּי חִיָּיא, וְשָׁכַבְתִּי עִם אֲבוֹתַי וְגו'. רִבִּי יִצְחָק פָּתַח וְאָמַר, (קהלת א׳:ג׳) מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ שֶׁיַּעֲמֹל תַּחַת הַשָּׁמֶשׁ. בְּכַמָּה אֲתַר אִתְּמָר דְּאִסְתַּכַּלְנָא בְּמִלּוֹי דִּשְׁלֹמֹה וְאִתְחֲזֵי מִלּוֹי סְתִימִין, אֲבָל כֻּלְּהוּ מִלֵּי דִּשְׁלֹמֹה, כֻּלְּהוּ אִקְרוּן בְּחָכְמָתָא.</p>"],[9520011453,"<p>דְּתַנְיָא כְּתִיב, (מלכים א ה׳:י׳) וַתֵּרֶב חָכְמַת שְׁלֹמֹה, בְּיוֹמוֹי דִשְׁלֹמֹה מַלְכָּא, קָיְימָא סִיהֲרָא בְּאַשְׁלָמוּתָא. וְהַיְינוּ דִכְתִיב, וַתֵּרֶב חָכְמַת שְׁלֹמֹה מֵחָכְמַת כָּל בְּנֵי קֶדֶם. תַּמָּן תָּנִינָן, מַאן אִינוּן בְּנִי קֶדֶם, הָא אוּקְמוּהָ. אֲבָל חָכְמַת בְּנֵי קֶדֶם, הִיא חָכְמְתָא דְּיָרְתוּ מֵאַבְרָהָם.</p>\n<p>דְּתַנְיָא כְּתִיב, (בראשית כ״ה:ה׳) וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק. מַאי אֶת כָּל אֲשֶׁר לוֹ. דָּא חָכְמְתָא עִלָּאָה דְּהֲוָה יָדַע בִּשְׁמָא קַדִּישָׁא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּמַשְׁמַע אֶת כָּל אֲשֶׁר לוֹ, דְּהֲוָה דִילֵיהּ. כִּדְתָנִינָן בְּהַהִיא בַּת דְּהֲוַת לֵיהּ לְאַבְרָהָם, וּבַכֹּל שְׁמָהּ.</p>\n<p>וְלִבְנֵי הַפִּילַּגְשִׁים אֲשֶׁר לְאַבְרָהָם נָתַן אַבְרָהָם מַתָּנוֹת וְגו'. דְּיָהַב לְהוּ מִילִין יְדִיעָאן, בְּכִתְרִין תַּתָּאִין, וּבְאָן אֲתַר אַשְׁרֵי לוֹן, אֶל אֶרֶץ קֶדֶם. וּמִתַּמָּן יָרִיתוּ בְּנִי קֶדֶם חָכְמָתָא, וְהַיְינוּ דִכְתִיב מֵחָכְמַת כָּל בְּנֵי קֶדֶם.</p>\n<p>תָּאנָא, יוֹמָא חַד הֲוָה אָתֵי רִבִּי שִׁמְעוֹן מִקַּפּוֹטְקִיָּא לְלוֹד, וְהֲוָה עִמֵּיהּ רִבִּי אַבָּא וְרִבִּי יְהוּדָה. רִבִּי אַבָּא הֲוָה לָאֵי, וְהֲוָה רָהִיט אֲבַתְרֵיהּ דְּרִבִּי שִׁמְעוֹן דְּהֲוָה רָכִיב. אָמַר רִבִּי אַבָּא, וַדַּאי (הושע י״א:י׳) אַחֲרֵי ה' יֵלֵכוּ כְּאַרְיֵה יִשְׁאָג.</p>\n<p>נָחַת רִבִּי שִׁמְעוֹן, אָמַר לֵיהּ, וַדַּאי כְּתִיב, (דברים ט׳:ט׳) וָאֵשֵׁב בָּהָר אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה, וַדַּאי חָכְמְתָא לָא מִתְיַישְׁבָא, אֶלָּא כַּד בַּר נָשׁ יָתִיב וְלָא אָזִיל, אֶלָּא קָאִים בְּקִיּוּמֵיהּ. וְהָא אוֹקִימְנָא מִלֵּי עַל מַה כְּתִיב וָאֵשֵׁב. הַשְׁתָּא בְּנַיְיחָא תַּלְיָיא מִילְתָא. יָתְבוּ.</p>\n<p>אָמַר רִבִּי אַבָּא, כְּתִיב וַתֵּרֶב חָכְמַת שְׁלמֹה מֵחָכְמַת כָּל בְּנֵי קֶדֶם וּמִכָּל חָכְמַת מִצְרַיִם. מַאי הִיא חָכְמַת שְׁלמֹה וּמַאי הִיא חָכְמַת מִצְרַיִם וּמַאי הִיא חָכְמַת כָּל בְּנִי קֶדֶם. אָמַר לֵיהּ, תָּא חֲזֵי, בְּכַמָּה אֲתַר אוּקְמוּהָ בְּהַהוּא שְׁמָא, דְּסִיהֲרָא כַּד אִתְבָּרְכָא מִכֹּלָּא, כְּתִיב וַתֵּרֶב. בְּיוֹמוֹי דִשְׁלֹמֹה, דְּאִתְרְבִיאַת וְאִתְבָּרְכַת וְקָיְימָא בְּאַשְׁלָמוּתָא.</p>\n<p>וְתָנִינָן, אֶלֶף טוּרִין מִתְרַבְרְבִין קַמָּהּ, וְכֻלְּהוּ נְשִׁיבָא חַד הֲווּ לְקַמָּהּ. אֶלֶף נַהֲרִין סַגִּיאִין לָהּ, וּבִגְמִיעָא חָדָא גָּמְעָא לוֹן.</p>\n<p>טוּפְרָהָא מֵאַחֲדָא לְאֶלֶף וְשִׁבְעִין עֵיבַר. <Nonei></i>יְדָהָא אֲחִידָן לְאַרְבַּע וְעֶשְׂרִין (וחמש) אֶלֶף עֵיבַר, לֵית דְּנָפִיק מִנָּהּ לִסְטַר הַאי, וְלֵית דְּנָפִיק מִנָּהּ לִסְטַר אָחֳרָא. כַּמָּה וְכַמָּה אֶלֶף תְּרֵיסִין, מִתְאַחֲדִין בְּשַׂעֲרָהָא.</p>\n<p>חַד עוּלֵימָא, דְאוֹרְכֵּיהּ מֵרֵישָׁא דְעַלְמָא לִסְיָיפֵי דְעַלְמָא, נָפִיק בֵּין רַגְלָהָא. בְּשִׁתִּין פּוּלְסֵי דְנוּרָא מִתְלַבֵּשׁ, בְּגַוְונֵי דָא אִתְמַנָא עַל תַּתָּאֵי (מתחות) מֵאַרְבַּע סִטְרָהָא. דָּא אִיהוּ נַעַר, דְּאָחִיד שִׁית מְאָה וּתְלַת עֲשַׂר מַפְתְּחָן עִלָּאִין מִסִּטְרָא דְאִמָּא. וְכֻלְּהוּ מַפְתְּחָן עִלָּאִין, בְּשִׁנְּנָא דְחַרְבָּא דַּחֲגִיר בְּחַרְצֵיהּ תַּלְיָין.</p>\n<p>הַהוּא נַעַר, קָרוּן לֵיהּ חֲנוֹךְ בֶּן יֶרֶד, בְּאִינוּן בְּרִיָּיתֵי, דִּכְתִיב, (משלי כ״ב:ו׳) חֲנוֹךְ לַנַּעַר עַל פִּי דַרְכּוֹ. וְאִי תֵימָא מַתְנִיתִין הִיא, וְלָא בְּרָיְּיתָא. בְּמַתְנִיתָּא דִילָן אוֹקִימְנָא מִילֵי, וְהָא אִתְּמָר, וְכֹלָּא מִלְּתָא חָדָא אִסְתַּכָּלוּ (נ\"א אשתכללו). תְּחוֹתֵיהּ תִּטְלַל חֵיוַת בְּרָא. דְּתַנְיָא (נ\"א דתא חזי), כְּמָה דְיִשְׂרָאֵל קַדִּישָׁא עִלָּאָה, אִקְרֵי בֵּן לְאִמֵּיהּ, דִּכְתִיב, (משלי ד׳:ג׳) כִּי בֵּן הָיִיתִי לְאָבִי רַךְ וְיָחִיד לִפְנֵי אִמִּי, וּכְתִיב, (שמותד) בְּנִי בְּכוֹרִי יִשְׂרָאֵל, הָכִי נָמֵי לְתַתָּא, דָּא אִקְרֵי נַעַר לְאִמֵּיהּ. דִּכְתִיב, (הושע י״א:א׳) כִּי נַעַר יִשְׂרָאֵל וָאוֹהֲבֵהוּ, וּבְכַמָּה גְוָונִין אִקְרֵי בֶּן יָרֶד, וְהָא אוֹקִימְנָא. אֲבָל תָּא חֲזֵי, בֶּן יֶרֶד מַמָּשׁ. דְּתָנִינָן, עֶשֶׂר יְרִידוֹת יָרְדָה שְׁכִינָה לְאַרְעָא, וְכֻלְּהוּ אוּקְמוּהָ חַבְרַיָּיא וְאִתְּמָר. וּתְחוֹת הַאי, כַּמָּה חֵיוָתָא קָיְימִין, דְּאִקְרוּן חֵיוַת בְּרָא מַמָּשׁ.</p>\n<p>תְּחוֹת אִינוּן חֵיוָותָא, מִתְאַחֲדָן שַׂעֲרָהָא דְסִיהֲרָא, דְּאִקְרוּן כֹּכְבַיָא דְּשַׁרְבִיטָא, דְּשַׁרְבִיט מַמָּשׁ, מָארֵי דְּמָארִין, מָארֵי דְמַתְקְלָא, מָארֵי דְקַשְׁיוּ, מָארֵי דְחוּצְפָּא. וְכֻלְּהוּ אִקְרוּן מָארֵי (נ\"א שערי) דְאַרְגְּוָונָא, יְדָהָא וְרַגְלָהָא אֲחִידָן בְּהַאי, כְּאַרְיֵה (קדישא) תַּקִּיפָא דְּאָחִיד עַל טַּרְפֵּיהּ. וְעַל דָּא כְּתִיב, (מיכה ה׳:ז׳) וְטָרַף וְאֵין מַצִּיל.</p>\n<p>טוּפְרָהָא, כָּל אִינוּן דְּאַדְכְּרִין חוֹבֵי בְּנֵי נָשָׁא, וְכָתְבִין וְרָשְׁמִין חוֹבַיְיהוּ בִּתְקִיפוּ דְּדִינָא קַשְׁיָא. וְעַל דָּא כְּתִיב, (ירמיהו י״ז:א׳) חַטַּאת יְהוּדָה כְּתוּבָה בְּעֵט בַּרְזֶל בְּצִפּוֹרֶן שָׁמִיר. מַהוּ שָׁמִיר. הַהוּא דְּרָשִׁים וְנָקִיב אַבְנָא, וּפָסִיק לָהּ לְכָל סִטְרָא.</p>\n<p>זוּהֲמָא דְטוֹפְרָהָא, כָּל אִינוּן דְּלָא מִתְדַּבְּקִין בְּגוּפָא דְמַלְכָּא, וְיָנְקִין מִסִּטְרָא דִּמְסָאֲבוּתָא, כַּד שָׁארֵי סִיהֲרָא בִּפְגִימוּ.</p>\n<p>וּבְגִין דִּשְׁלֹמֹה מַלְכָּא יָרְתָא לְסִיהֲרָא בִּשְׁלֵימוּתָא, בָּעֵי לְיָרְתָא לָהּ בִּפְגִימוּתָא, וְעַל דָּא אִשְׁתַּדַּל לְמֵידַע, בְּדַעְתָּא (ברעותא) דְרוּחִין וְשֵׁדִין, לְמֵירַת סִיהֲרָא בְּכָל סִטְרָא.</p>\n<p>וּבְיוֹמוֹי דִשְׁלֹמֹה מַלְכָּא, בְּכֹלָּא אִתְנְהִיר סִיהֲרָא. הֲדָא הוּא דִכְתִיב, (מלכים א ה׳:י׳) וַתֵּרֶב חָכְמַת שְׁלֹמֹה, וַתֵּרֶב דַּיְיקָא. מֵחָכְמַת כָּל בְּנִי קֶדֶם, רָזָא עִלָּאָה הוּא, כְּמָה דִכְתִיב, (בראשית ל״ו:ל״א) וְאֵלֶּה הַמְלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם וְגו'. וְאִלֵּין אִקְרוּן בְּנִי קֶדֶם, דְּכֻלְּהוּ לָא אִתְקָיְימוּ, בַּר מֵהַאי דִּכְלִילָא דְּכַר וְנוּקְבָא דְּאִקְרֵי הֲדַר. דִּכְתִיב, (בראשית ל״ו:ל״ט) וַיִּמְלוֹךְ תַּחְתָּיו הֲדַר וְגו'.</p>\n<p>וְתָאנָא, דְּאַף עַל גַּב דְּאִתְקָיְימַת (נ\"א דאתנהירת סיהרא), לָא אִתְנְהִירַת בְּאַשְׁלָמוּתָא. עַד דְּאֲתָא שְׁלֹמֹה, דְּאִתְחֲזֵי לְקִבְלָהָא, כְּמָה דְאוֹקִימְנָא. דִּבְגִין כָּךְ אִמֵּיהּ בַּת שֶׁבַע הֲוַת.</p>\n<p>וּמִכָּל חָכְמַת מִצְרַיִם, דָּא חָכְמָה תַּתָּאָה, דְּאִקְרֵי שִׁפְחָה דְּבָתַר רֵיחַיָא, וְכֹלָּא אִתְכְּלִילַת הַאי חָכְמָה דִשְׁלֹמֹה, חָכְמַת בְּנִי קֶדֶם, וְחָכְמַת מִצְרַיִם. אָמַר רִבִּי אַבָּא, בְּרִיךְ רַחֲמָנָא, דְּשָׁאִילְנָא קַמָּךְ מִלָּה דָא, דְּהָא בְּכָל הַנֵּי מִילֵי (מלה דא) זָכִינָא. אָמַר רִבִּי שִׁמְעוֹן, מִלִּין אִלֵּין, הָא אוֹקִימְנָא לוֹן, וְהָא אִתָּמְרוּ.</p>\n<p>תָּאנָא, (קהלת א׳:ג׳) מַה יִּתְרוֹן לְאָדָם בְּכָל עֲמָלוֹ, יָכוֹל אַף עֲמָלָה דְאוֹרַיְיתָא, תַּלְמוּד לוֹמַר שֶׁיַּעֲמוֹל תַּחַת הַשָּׁמֶשׁ (כתיב). שָׁאנֵי עֲמָלָה דְאוֹרַיְיתָא, דִּלְעֵילָא מִן שִׁמְשָׁא הוּא. רִבִּי חִיָּיא אָמַר, אַף עֲמָלָה דְאוֹרַיְיתָא, דְּאִיהוּ עָמָל בְּגִינֵיהוֹן דִּבְנֵי נָשָׁא, אוֹ בְּגִין יְקָרָא דִילֵיהּ. הַאי תַּחַת הַשֶּׁמֶשׁ כְּתִיב. דְּהָא לָא סָלִיק לְעֵילָא. תַּנְיָא אָמַר רִבִּי אֶלְעָזָר, אֲפִילּוּ אִי בַּר נָשׁ קַיָּים אֶלֶף שְׁנִין, הַהוּא יוֹמָא דְאִסְתַּלַּק מֵעַלְמָא, דָּמֵי לֵיהּ כְּאִילּוּ לָא אִתְקְיַּים בַּר יוֹמָא חַד:</p>"],[9520011454,"<p>וְשָׁכַבְתִּי עִם אֲבוֹתַי, זַכָּאָה חוּלְקֵהוֹן דַּאֲבָהָתָא, דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד לוֹן רְתִיכָא קַדִּישָׁא לְעֵילָא, וְאִתְרְעֵי בְּהוּ, לְאִתְעַטְּרָא עִמְּהוֹן. הֲדָא הוּא דִכְתִיב, (דברים י׳:ט״ו) רַק בַּאֲבוֹתֶיךָ חָשַׁק ה' וְגו'. אָמַר רִבִּי <Nonei></i>אֶלְעָזָר, יַעֲקֹב הֲוָה יָדַע, דְּהָא עִטּוּרָא דִילֵיהּ בַּאֲבָהָתֵיהּ הוּא, דְּהָא עִטּוּרָא דַאֲבָהָן עִמֵּיהּ הוּא, וְהוּא עִמְּהוֹן. וְעַל דָּא בְּאַתְוָון גְּלִיפִין תָּנִינָן, ש תְּלַת קִּשְׁרִין, תְּרֵין קִשְׁרִין, חַד מֵהַאי סִטְרָא, וְחַד מֵהַאי סִטְרָא, וְחַד דְּכָלִיל לוֹן. וְדָא הוּא דְתָנִינָן, (שמות כ״ו:כ״ח-כ״ט) וְהַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִיחַ מִן הַקָּצֶה אֶל הַקָּצֶה, וְהַהוּא קִשְׁרָא דִּבְאֶמְצָעִיתָא, אָחִיד לְהַאי סִטְרָא, וּלְהַאי סִטְרָא. וְעַל הַאי כְּתִיב, וְשָׁכַבְתִּי עִם אֲבוֹתַי וַדַּאי.</p>\n<p>וְשָׁכַבְתִּי עִם אֲבוֹתַי וְגו'. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (ישעיהו מ״ב:י״ח) הַחֵרְשִׁים שְׁמָעוּ וְהַעִוְרִים הַבִּיטוּ לִרְאוֹת. הַחֵרְשִׁים שְׁמָעוּ, אִלֵּין בְּנֵי נָשָׁא דְּלָא צַיְיתִין לְמִלּוּלֵי אוֹרַיְיתָא, וְלָא פָּקְחִין אוּדְנַיְיהוּ, לְמִשְׁמַע לְפִקּוּדֵי דְמָארֵיהוֹן. וְהַעִוְרִים, דְּלָא מִסְתַּכְּלִין לְמִנְדַע עַל מָה אִינוּן קָיְימִין. דְּהָא בְּכָל יוֹמָא וְיוֹמָא כָּרוֹזָא נָפִיק וְקָרֵי, וְלֵית מַאן דְּיַשְׁגַּח.</p>\n<p>דְּתַנְיָא, אִינוּן יוֹמִין דְּבַּר נָשׁ כַּד אִתְבְּרֵי, בְּהַהוּא יוֹמָא דְּנָפַק לְעַלְמָא, כֻּלְּהוּ קָיְימִין בְּקִיּוּמַיְיהוּ. וְאָזְלִין וְטָאסִין בְּעַלְמָא, נָחֲתִין וְאַזְהֲרָן לְבַּר נָשׁ, כָּל יוֹמָא וְיוֹמָא בִּלְחוֹדוֹי. וְכַד הַהוּא יוֹמָא אָתֵי וְאַזְהַר לֵיהּ, וּבַר נָשׁ עָבִיד בְּהַהוּא יוֹמָא חוֹבָא קַמֵּי מָארֵיהּ. הַהוּא יוֹמָא סָלִיק בְּכִסּוּפָא, וְאַסְהִיד סַהֲדוּתָא, וְקָאִים בִּלְחוֹדוֹי לְבַר.</p>\n<p>וְתָאנָא, בָּתַר דְּקָאִים בִּלְחוֹדוֹי, יָתִיב, עַד דְּבַר נָשׁ עָבִיד מִנֵּיהּ תְּשׁוּבָה. זָכָה, תָּב הַהוּא יוֹמָא לְאַתְרֵיהּ. לָא זָכָה, הַהוּא יוֹמָא נָחִית, וְאִשְׁתַּתַּף בְּהַהוּא רוּחָא דִּלְבַר, וְתָב לְבֵיתֵיהּ. וְאִתְתַּקַּן בְּדִיוּקְנֵיהּ דְּהַהוּא בַּר נָשׁ מַמָּשׁ, בְּגִין לְאַבְאָשָׁא לֵיהּ, וְדַיָּיר עִמֵּיהּ בְּבֵיתָא. וְאִית דְּדִיּוּרָא לְטַב אִי הוּא זָכֵי. וְאִי לָאו, דִּיּוּרֵיהּ עִמֵּיהּ לְבִישׁ.</p>\n<p>בֵּין כָּךְ וּבֵין כָּךְ, אִתְפַּקְדָּן אִינוּן יוֹמִין וְחֲסֵרִים, וְלָא עָאלִין בְּמִנְיָינָא דְּאִינוּן דְּאִשְׁתָּאֲרוּ. וַוי לְהַהוּא בַּר נָשׁ, דְּגָרַע יוֹמוֹי קַמֵּי מַלְכָּא קַדִּישָׁא, וְלָא שָׁבִיק לְעֵילָא יוֹמִין, לְאִתְעַטְּרָא בְּהוּ בְּהַהוּא עַלְמָא, וּלְאִתְקָרְבָא בַּהֲדַיְיהוּ קַמֵּי מַלְכָּא קַדִּישָׁא.</p>\n<p>תָּא חֲזֵי, כַּד קְרִיבוּ אִינוּן יוֹמִין קַמֵּי מַלְכָּא קַדִּישָׁא. אִי הוּא זַכָּאָה, הַאי בַּר נָשׁ דְּנָפִיק מֵעַלְמָא, סָלִיק וְעָאל בְּאִינוּן יוֹמִין. וְאִינוּן לְבוּשֵׁי יְקָר, דְּמִתְלַבְּשָׁא בֵּיהּ נִשְׁמָתֵיהּ. וְאִינוּן יוֹמִין הֲווּ, דְּזָכָה בְּהוּ, וְלָא חָב בְּהוּ.</p>\n<p>וַוי לְהַהוּא דְגָרַע יוֹמוֹי לְעֵילָא. דְּכַד בָּעָאן לְאַלְבָּשָׁא לֵיהּ בְּיוֹמוֹי, אִינוּן יוֹמִין דְפָגִים אִיהוּ בְּחוֹבוֹי, חָסְרִין מֵהַהוּא לְבוּשָׁא, וְאִתְלַבַּשׁ בְּמָנָא חֲסֵרָא. כָּל שְׁכֵּן אִי סַגִּיאִין אִינוּן, וְלָא לֶהוֵי לֵיהּ לְבַּר נָשׁ בַּמֶּה דְּאִתְלַבַּשׁ בְּהַהוּא עַלְמָא. כְּדֵין וַוי לֵיהּ, וַוי לְנַפְשֵׁיהּ, דְּדָיְינִין לֵיהּ בַּגֵּיהִנָּם עַל אִינוּן יוֹמִין. יוֹמִין עַל יוֹמִין, יוֹמִין עַל חַד תְּרִין. דְּכַד נָפִיק מֵהַאי עַלְמָא, לָא אַשְׁכַּח יוֹמִין דְּאִתְלַבַּשׁ בְּהוּ, וְלָא הֲוֵי לֵיהּ לְבוּשָׁא בַּמֶה דְּאִתְכַּסֵּי. זַכָּאִין אִינוּן צַדִּיקַיָא, דְּיוֹמֵיהוֹן כֻּלְּהוֹן טְמִירִין אִינוּן לְגַבֵּיהּ דְּמַלְכָּא קַדִּישָׁא, וְאִתְעֲבִיד מִנַּיְיהוּ לְבוּשֵׁי יְקָר, לְאִתְלַבְּשָׁא בְּהוּ בְּעַלְמָא דְאָתֵי.</p>\n<p>תָּנִינָן בְּרָזָא דְּמַתְנִיתִין, מַאי דִכְתִיב, (בראשית ג׳:ז׳) וַיֵּדְעוּ כִּי עֵרוּמִּים הֵם, יְדִיעָה יָדְעֵי מַמָּשׁ. דְּהַהוּא לְבוּשָׁא דִּיקָר, דְּאִתְעֲבִיד מֵאִינוּן יוֹמִין, גָּרַע מִנַּיְיהוּ, וְלָא אִשְׁתָּאַר יוֹמָא מֵאִינוּן יוֹמִין לְאִתְלַבְּשָׁא בֵּיהּ. הֲדָא הוּא דִכְתִיב, (תהילים קל״ט:ט״ז) גָּלְמִי רָאוּ עֵינְיךָ וְעַל סִפְרְךָ כֻּלָּם יִכָּתֵבוּ. יָמִים יוּצָרוּ. יָמִים יוּצָרוּ וַדַּאי, וְלֹא אֶחָד בָּהֶם, דְּהָא לָא אִשְׁתָּאַר חַד מִנַּיְיהוּ לְאִתְלַבְּשָׁא בְּהוּ. עַד דְּאִשְׁתַּדַּל אָדָם, וְעָבַד תְּשׁוּבָה, וְקוּדְשָׁא בְּרִיךְ הוּא קַבִּיל לֵיהּ, וְעָבִיד לֵיהּ מָאנָא (מאני) לְבוּשָׁא אָחֳרָנִין, וְלָא מִן יוֹמוֹי. הֲדָא הוּא דִכְתִיב, (בראשית ג׳:כ״א) וַיַּעַשׂ ה' אֱלהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם.</p>\n<p>תָּא חֲזֵי, בְּאַבְרָהָם דְּזָכָה, מַה כְּתִיב, (בראשית כד) בָּא בַּיָּמִים, מִשּׁוּם דְּזָכָה. כַּד אִסְתַּלַּק מֵהַאי עַלְמָא, בְּאִינוּן יוֹמִין מַמָּשׁ דִּילֵיהּ, עָאל וְאִתְלַבַּשׁ בְּהוּ, וְלָא גָרַע מֵהַהוּא לְבוּשׁ יְקָר כְּלוּם, דִּכְתִיב בָּא בַּיָּמִים. בְּאִיּוֹב מַה כְּתִיב, (איוב א׳:כ״א) וַיֹּאמֶר עָרוֹם יָצָאתִי מִבֶּטֶן אִמִּי וְעָרוֹם אָשׁוּב שָׁמָּה. דְּהָא לָא אִשְׁתָּאַר לְבוּשָׁא לְאִתְלַבְּשָׁא בֵּיהּ.</p>\n<p>תָּנָא, זַכָּאִין אִינוּן צַדִּיקַיָא, דְּיוֹמֵיהוֹן זַכָּאִין, וְאִשְׁתָּאֲרוּ לְעַלְמָא דְאָתֵי (זכאין), וְכַד נָפְקִין, מִתְחַבְּרָן כֻּלְּהוּ, וְאִתְעֲבִידוּ <Nonei></i>לְבוּשֵׁי יְקָר, לְאִתְלַבְּשָׁא בֵּיהּ. וּבְהַהוּא לְבוּשָׁא, זָכָאן לְאִתְעַנָּגָא מֵעִנּוּגָא דְעַלְמָא דְאָתֵי, וּבְהַהוּא לְבוּשָׁא, זְמִינִין לַאֲחָיָיא וּלְמֵיקַם. וְכָל אִינוּן דְּאִית לְהוּ לְבוּשָׁא יְקוּמוּן, הֲדָא הוּא דִכְתִיב, (איוב ל״ח:י״ד) וַיִּתְיַצְּבוּ כְּמוֹ לְבוּשׁ. וַוי לְאִינוּן חַיָּיבֵי עַלְמָא, דְּיוֹמֵיהוֹן בְּחוֹבֵיהוֹן (עלמין) חַסְרִין, וְלָא אִשְׁתָּאַר מִנַּיְיהוּ, בַּמֶּה דְאִתְכַּסְיָין, כַּד יִפְקוּן מֵעַלְמָא.</p>\n<p>תָּאנָא, כָּל אִינוּן זַכָּאִין, דְּזָכוּ לְאִתְלַבְּשָׁא בִּלְבוּשׁ יְקָר בְּיוֹמֵיהוֹן, מִתְעַטְּרָן בְּהַהוּא עַלְמָא (ס\"א גולמא), מֵעִטּוּרֵי דְּמִתְעַטְּרֵי בְּהוּ אֲבָהָן, מֵהַהוּא נַחַל דְּנָגִיד וְנָפִיק לְגִנְתָא דְעֵדֶן. הֲדָא הוּא דִכְתִיב, (ישעיה מח) וְנָחֲךָ ה' תָּמִיד וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךָ וְגו'. וְאִינוּן חַיָּיבֵי עַלְמָא, דְּלָא זָכוּ לְאִתְלַבְּשָׁא בִּלְבוּשָׁא דְּיוֹמֵיהוֹן, עֲלַיְיהוּ כְּתִיב, (ירמיהו י״ז:ו׳) וְהָיָה כְּעַרְעָר בָּעֲרָבָה וְלֹא יִרְאֶה כִּי יָבֹא טוֹב וְשָׁכַן חֲרֵרִים בַּמִּדְבָּר.</p>\n<p>אָמַר רִבִּי יִצְחָק, זַכָּאָה חוּלָקֵיהּ דְּיַעֲקֹב, דְּרָחֲצָנוּ יַתִּיר הֲוָה לֵיהּ, דִּכְתִיב וְשָׁכַבְתִּי עִם אֲבוֹתַי. דְּאֶזְכֵּי בְּהוּ וְלָא בְּאָחֳרָא. דְּאֶזְכֵּי בְּהוּ, לְאִתְלַבְּשָׁא בְּיוֹמִין דִּילֵיהּ, וּבְיוֹמִין דִּלְהוֹן.</p>\n<p>רִבִּי יְהוּדָה אָמַר, כְּתִיב, (בראשית כ״ז:כ״ז) וַיָרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרַכֵהוּ. בְּגָדָיו. בִּגְדֵי עֵשָׂו מִבָּעֵי לֵיהּ. דְּהָא לָאו דִּידֵיהּ הֲווּ, אֶלָּא דְעֵשָׂו הֲווּ הַנְהוּ בְּגָדִים. דִּכְתִיב, (בראשית כ״ז:ט״ו) וַתִּקַּח רִבְקָה אֶת בִּגְדֵי עֵשָׂו בְּנָהּ הַגָּדוֹל הַחֲמוּדוֹת, בִּגְדֵי עֵשָׂו כְּתִיב (הכא), וְהָכָא רֵיחַ בְּגָדָיו, דְּיַעֲקֹב מַשְׁמַע.</p>\n<p>אֶלָּא, הָכִי אוֹקִימְנָא, וַיָּרַח, כְּלוֹמַר, אִסְתָּכַּל לְהָלְאָה, וְאָרַח רֵיחָא דִלְבוּשׁוֹי דְּהַהוּא עַלְמָא, כְּדֵין בָּרְכֵיהּ. וְעַל דָּא כְּתִיב, רְאֵה רֵיחַ בְּנִי כְּרֵיחַ שָׂדֶה, דָּא הוּא חֲקַל דְּתַפּוּחִין קַדִּישִׁין. אָמַר, הוֹאִיל וְזָכִיתָ בְּאִינוּן לְבוּשֵׁי יְקָר, וְיִתֶּן לְךָ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם. מַאי מַשְׁמַע, בְּגִין דִּבְהַהוּא חֲקַל דְּתַפּוּחִין קַדִּישִׁין, נָטִיל (ס\"א נטיף) טַלָּא כָּל יוֹמָא, מֵהַהוּא אֲתַר דְּאִקְרֵי שָׁמַיִם, דִּכְתִיב מִטַּל הַשָּׁמַיִם.</p>\n<p>אָמַר רִבִּי יוֹסֵי, בְּכֹלָּא בָּרְכֵיהּ, מִטַּל הַשָּׁמַיִם וּמִשְׁמַנִּי הָאָרֶץ. מַאי טַעְמָא, בְּגִין דְּוַיָּרַח אֶת רֵיחַ בְּגָדָיו. בְּגָדָיו מַמָּשׁ, כְּמָה דְאוֹקִימְנָא. תָּנָא, אֶלֶף וַחֲמֲשׁ מְאָה רֵיחִין, סָלְקִין בְּכָל יוֹמָא מִגַּן עֵדֶן, דְּמִתְבַּסְּמֵי בְּהוּ אִינוּן לְבוּשִׁין דִּיקָר דְּהַהוּא עַלְמָא, דְּמִתְעַטְּרָן מִן יוֹמוֹי דְּבַר נָשׁ.</p>\n<p>אָמַר רִבִּי יְהוּדָה, כַּמָּה לְבוּשִׁין אִינוּן. אָמַר רִבִּי אֶלְעָזָר, טוּרֵי (ויקרא ע\"א ע\"ב) דְעָלְמָא, עַל דָּא פְּלִיגוּ. אֲבָל תְּלָתָא אִינוּן. חַד דְּמִתְלַבְּשֵׁי בְּהַהוּא לְבוּשָׁא, רוּחָא דִּבְגִנְתָא דְעֵדֶן דְּאַרְעָא. וְחַד יְקָרָא מִכֹּלָּא, דְּמִתְלַבְּשָׁא בֵּיהּ נִשְׁמָתָא בְּגוֹ צְרוֹרָא דְחַיֵּי, בֵּין פּוּרְפִּירָא דְמַלְכָּא. וְחַד לְבוּשָׁא דִּלְבַר, דְּקָאִים וְלָא קָאִים, אִתְחֲזֵי וְלָא אִתְחֲזֵי. בְּהַאי מִתְלַבְּשָׁא בֵּיהּ נַפְשָׁא, וְאָזְלָא וְשָׁטָא בְּעַלְמָא.</p>\n<p>וּבְכָל רֵישׁ יַרְחֵי (שתא) וְשַׁבַּתָּא, אָזְלַת וְאִתְקַשְּׁרַת בְּרוּחָא דִּבְגִנְתָא דְּעֵדֶן דְּאַרְעָא, דְקָיְימָא בֵּין פַּרְגּוֹדָא יַקִּירָא, וּמִנֵּיהּ אוֹלִיף וְיָדַע מַה דְּיָדַע, וְשָׁט וְאוֹדַע לֵיהּ בְּעַלְמָא.</p>\n<p>תָּנָא, בִּתְרֵין קִשּׁוּרִין אִתְקַשַּׁר נַפְשָׁא, בְּכָל רֵישׁ יַרְחָא וְשַׁבַּתָּא, בְּקִשּׁוּרָא דְרוּחָא, דִּי בֵּין רֵיחֵי בּוּסְמִין דִּבְגִנְתָא דְעֵדֶן דְּאַרְעָא, וּמִתַּמָּן אָזִיל וְשָׁאט, וְאִתְקַשַּׁר עִם רוּחָא בְּנִשְׁמָתָא דִּצְרִירָא בִּצְרוֹרָא דְחַיֵּי, וּמִתְרַוְיָא וּמִתְזָנַת מֵאִינוּן זִיוִין יְקָרִין, דְּהַאי סִטְרָא, וּדְהַאי סִטְרָא. הֲדָא הוּא דִכְתִיב, וְנָחֲךָ ה' תָּמִיד, תָּמִיד דַּיְיקָא.</p>\n<p>וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךָ. מַהוּ בְּצַחְצָחוֹת. אֶלָּא צַחוּתָא חַד, כַּד אִתְקַשַּׁר בְּרוּחָא דִּבְגִנְתָא דִלְתַתָּא, צַחוּתָא דִלְגַו מִן צַחוּתָא, כַּד מִתְקַשְּׁרָן בְּנִשְׁמָתָא דִלְעֵילָא, בִּצְרוֹרָא דְחַיֵּי, וְהַיְינוּ בְּצַח חַד, צַחוֹת תְּרֵין, דְּאִינוּן לְעֵילָא לְעֵילָא, בְּיַקִּירוּ דְנִשְׁמָתָא וַדַּאי, כְּלוֹמַר צַחְצָחוֹת, מַאן יָרִית דָּא, נַפְשֶׁךָ. נַפְשֶׁךָ מַמָּשׁ. זַכָּאָה חוּלְקֵהוֹן דְּצַדִּיקַיָיא.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כַּד אֲנָא בֵּין אִינוּן חַבְרַיָיא דְּבָבֶל, מִתְכַּנְשֵׁי גַּבָּאי, וְאוֹלְפֵי מִלֵּי בְּאִתְגַּלְּיָיא, וְאִינוּן עַיְילֵי לוֹן בְּגוּשְׁפַּנְקָא דְפַרְזְלָא תַּקִּיפָא, סְתִימָא מִכָּל סִטְרִין. כַּמָּה זִמְנִין אוֹלִיפְנָא לוֹן אָרְחוֹי דְגִנְתָא דְמַלְכָּא, אוֹרְחוֹי דְמַלְכָּא. (נ\"א כמה זמנין אמינא לון ארחוי דאורייתא דמלכא קדישא ואורחין עלאין).</p>\n<p>כַּמָּה זִמְנִין אוֹלִיפְנָא לוֹן כָּל אִנּוּן דַּרְגִּין דְּצַדִּיקַיָא דִּבְהַהוּא עַלְמָא, וְכֻלְּהוּ מִסְתָּפֵי לְמֵימַר <Nonei></i>מִלִּין אִלֵּין, אֶלָּא לָעָאן (מעלעלין) בְּגִמְגוּמָא. בְּגִינִי כָּךְ פְּסִילוּסִין אִקְרוּן, כְּהַהוּא פְּסִילוּתָא דִמְגַמְגֵם בְּפוּמֵיהּ.</p>\n<p>אֲבָל לִזְכוּתָא דָּאִינְנָא לְהוּ, הוֹאִיל וּמִסְתָּפֵי. דְּהָא אֲוִירָא קַדִּישָׁא וְרוּחָא קַדִּישָׁא אִתְעֲדֵי מִנַּיְיהוּ, וְיָנְקֵי מֵאֲוִירָא וְרוּחָא דִרְשׁוּתָא אָחֳרָא. וְלָא עוֹד אֶלָּא דְקֶשֶׁת אִתְחֲזֵי עֲלַיְיהוּ, וְלָאו אִינוּן כְּדַאי לְמֶחמֵי סֵבֶר אַנְפּוֹי (ס\"א דאליהו), כָּל שֶׁכֵּן סֵבֶר אַנְפִּין אָחֳרָנִין.</p>\n<p>אֲבָל דָּא מְהַנְיָא לְהוּ, דְּאֲנָא שְׁכִיחַ בְּעַלְמָא וְאֲנָא סִימָנָא (נ\"א סמכא) בְּעַלְמָא, דְּהָא בְּחַיַּי לָא יָתִיב עַלְמָא בְּצַעֲרָא, וְלָא אִתְדָּן בְּדִינָא דִלְעֵילָא, בַּתְרָאי לָא יָקוּם דָּרָא כְּדָרָא דָא. וְזַמִּין עַלְמָא דְּלָא יִשְׁתַּכַּח מַאן דְּיָגִין עֲלַיְיהוּ, וְכָל אַנְפִּין חֲצִיפִין יִשְׁתַּכְּחוּן בֵּין לְעֵילָא בֵּין לְתַתָּא. לְעֵילָא, בְּחוֹבַיְיהוּ דִלְתַתָּא, וַחֲצִיפוּתָא דִלְהוֹן.</p>\n<p>וּזְמִינִין בְּנִי עַלְמָא דְּצָוְוחִין, וְלֵית מַאן דְּיַשְׁגַּח עֲלַיְיהוּ. יְהַדְּרוּן רֵישָׁא לְכָל סִטְרֵי עַלְמָא, וְלָא יְתוּבוּן בְּאַסְוָותָא. אֲבָל חַד אָסוּתָא אַשְׁכַּחְנָא לְהוּ בְּעַלְמָא וְלָא יַתִּיר, בְּהַהוּא אֲתַר דְּיִשְׁתַּכְּחוּן אִינוּן דְּלָעָאן בְּאוֹרַיְיתָא, וְאִשְׁתַּכַּח בֵּינַיְיהוּ (ויקרא ע\"א ע\"א) סֵפֶר תּוֹרָה דְּלָא מִשְׁתַּקַּר בֵּיהּ. כַּד מַפְקֵי הַאי, בְּגִינֵיהּ מִתְעָרֵי עִלָּאֵי וְתַתָּאֵי. וְכָל שֶׁכֵּן אִי אַכְתִּיב בֵּיהּ שְׁמָא קַדִּישָׁא כְּדְקָא חָזֵי, וְהָא אוֹלִיפְנָא מִלָּה.</p>\n<p>וַוי לְדָרָא דְּאִתְגַּלְּיָיא בֵּינַיְיהוּ סֵפֶר תּוֹרָה, וְלָא מִתְעָרֵי עֲלֵיהּ לְעֵילָא וְתַתָּא. מַאן אִתְעַר עֲלֵיהּ בְּשַׁעְתָּא דְעַלְמָא בְּצַעֲרָא טְפֵי, וְאִצְטְרִיךְ עַלְמָא לְמִטְרָא, וְאִצְטְרִיךְ לְאַגְלָאָה סֵפֶר תּוֹרָה יַתִּיר בְּדוֹחֲקָא דְעַלְמָא.</p>\n<p>דְּכַד עַלְמָא בְּצַעֲרָא, וּבָעָאן בְּנֵי נָשָׁא רַחֲמִין עֲלֵי קִבְרֵי, כֻּלְּהוּ מֵתִין מִתְעָרִין עֲלֵיהּ, דְּהָא נַפְשָׁא אַקְדִימַת וּמוֹדָעָא לְרוּחָא, דְּהָא סֵפֶר תּוֹרָה אִשְׁתַּכַּח בְּגָלוּתָא, דְּאִיגְלֵי בְּדוֹחֲקָא דְעַלְמָא, וְחַיָּיא אָתָאן וּבָעָאן רַחֲמֵי.</p>\n<p>כְּדֵין רוּחָא מוֹדְעָא לִנְשָׁמָה, וּנְשָׁמָה לְקוּדְשָׁא בְּרִיךְ הוּא, וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא אִתְעַר, וְחָס עַל עַלְמָא, וְדָא עַל גָּלוּתָא דְסֵפֶר תּוֹרָה מֵאַתְרִיהּ, וְחַיָּיא אָתִין לְמִבְעֵי רַחֲמֲי עַל קִבְרֵי מֵתַיָי. וַוי לְדָרָא אִי אִצְטְרִיךְ סֵפֶר תּוֹרָה לְאַגְלָאָה לֵיהּ מֵאֲתַר לְאֲתַר, אֲפִילּוּ מִבֵּי כְּנִישְׁתָּא לְבֵי כְּנִישְׁתָּא, דְּהָא לָא אִשְׁתַּכַּח בֵּינַיְיהוּ עַל מַה יִשְׁגְּחוּן עֲלַיְיהוּ.</p>\n<p>וְדָא לָא יָדְעִין כֻּלְּהוּ בְּנֵי נָשָׁא, דְּהָא שְׁכִינְתָּא כַּד אִתְגַּלְּיָיא גָּלוּתָא בַּתְרָאָה. עַד לָא תִסְתַּלַּק לְעֵילָא, מַה כְּתִיב, (ירמיהו ט׳:א׳) מִי יִתְּנִנִי בַּמִּדְבָּר מְלוֹן אוֹרְחִים. לְבָתַר בְּזִמְנָא דְּדָחֲקָא אִשְׁתַּכַּח טְפֵי בְּעַלְמָא, תַּמָּן אִשְׁתַּכְּחַת, וּבְגָלוּתָא דְסֵפֶר תּוֹרָה, תַּמָּן הִיא, וְכֹלָּא מִתְעָרִין עֲלֵיהּ, עִלָּאֵי וְתַתָּאֵי.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, אִי הַנֵּי בַּבְלָאֵי טִפְּשָׁאֵי, יִנְדְּעוּן מִלִּין דְּרָזֵי דְּחָכְמְתָא, עַל מַה קָּאִים עַלְמָא, וְסָמְכוֹי עַל מַה קָּא מִתְרַגְּשָׁן. כַּד יִשְׁתַּכַּח בְּדוֹחֲקָא, יִנְדְּעוּן שְׁבָחָא דְּרַב (המנונא) יֵיבָא סָבָא. כַּד אִשְׁתַּכַּח בֵּינַיְיהוּ, וְלָא הֲווּ יָדְעֵי שִׁבְחֵיהּ. וְהָא אַשְׁכַּחְנָא מִלּוֹי מִתְקַשְּׁרָן בְּמִלּוֹי דִּשְׁלֹמֹה מַלְכָּא, בְּרָזָא עִלָּאָה דְחָכְמְתָא, וְאִינוּן לָא הֲווּ יָדְעֵי שְׁבָחֵיהּ.</p>\n<p>וְהַשְׁתָּא אָזְלִין בָּתַר מִלֵּי דְחָכְמְתָא, וְלֵית מַאן דְּקָאִים עֲלָהּ, וְלֵית מַאן דְּקָרֵי. וְעִם כָּל דָא, אִית בֵּינַיְיהוּ פִּקְחִין בְּעִבּוּרָא דְּשַׁתָּא וּבִקְבִיעוּתָא דְיַרְחֵי, אַף עַל גַּב דְּלָא אִתְיְיהִיב לְהוּ, וְלָא אִתְמָסַר בִּידַיְיהוּ.</p>\n<p>תָּנִינָן, תְּרֵיסַר יַרְחֵי, הַאי נֶפֶשׁ אִיהִי מִתְקַשְּׁרָא בְּגוּפָא בְּקִבְרָא, וְאִתְדָּנוּ בְּדִינָא כְּחֲדָא, בַּר הַהִיא נֶפֶשׁ דְּצַדִּיקַיָיא, כְּמָה דְאוּקְמוּהָ, וּזְמִינָא בְּקִבְרָא, וְיָדַע בְּצַעֲרָא דִילֵיהּ, וּבְצַעֲרָא דְחַיֵּי יָדַע (ס\"א לא ידע), וְלָא אִשְׁתַּדְּלַת עֲלַיְיהוּ.</p>\n<p>וּלְבָתַר תְּרֵיסַר יַרְחֵי, אִתְלַבַּשׁ בִּלְבוּשָׁא חַד, וְאָזִיל וְשָׁאט בְּעַלְמָא, וְיָדַע מִן רוּחָא מַה דְּיָדַע, וְאִשְׁתְּדָּל צַעֲרָא לְעַלְמָא, וּלְמִבָּעֵי רַחֲמֵי. וּלְמִנְדַע (להו) צַעֲרָא דְחַיֵּי.</p>\n<p>וּמַאן אִתְעַר לְכָל הַאי, בְּזִמְנָא דְאִית זַכָּאָה, דְּאוֹדַע לְהוּ כְּדְקָא יְאוּת, וְהַהוּא זַכָּאָה אִשְׁתְּמוֹדַע בֵּינַיְיהוּ. דְּתַנְיָא, זַכָּאָה כַּד אִשְׁתָּאַר בְּעַלְמָא, בֵּין חַיָּיא, וּבֵין מֵיתַיָא אִשְׁתְּמוֹדַע, דְּהָא כָּל יוֹמָא מַכְרְזֵי עֲלֵיהּ בֵּינַיְיהוּ, וְכַד צַעֲרָא טָפֵי בְּעַלְמָא, וְהוּא לָא יָכִיל לַאֲגָנָא עַל דָּרָא, הוּא אוֹדַע לְהוּ צַעֲרָא דְעַלְמָא.</p>\n<p>וְכַד לָא אִשְׁתַּכַּח זַכָּאָה <Nonei></i>דְּמַכְרְזֵי עֲלֵיהּ בֵּינַיְיהוּ, וְלָא אִשְׁתַּכַּח (ד\"א ל\"ג בינייהו) מַאן דְּאִתְעַר לְהוּ בְּצַעֲרָא דְעַלְמָא, אֶלָּא סֵפֶר תּוֹרָה. כְּדֵין עִלָּאֵי וְתַתָּאֵי מִתְעָרִין עֲלֵיהּ, וּצְרִיכִין כֹּלָּא דְּיִשְׁתַּכְּחוּן בְּהַהִיא זִמְנָא בִּתְשׁוּבָה. וְאִי לָא מִשְׁתַּכְּחֵי, הָא מָארֵי דְּדִינָא אִתְעָרוּן עֲלַיְיהוּ, וְאֲפִילּוּ רוּחַ דְּגִנְתָא דְעֵדֶן, מִתְעָרִין עֲלַיְיהוּ, בְּגִינֵיהּ דְּסֵפֶר תּוֹרָה, כִּדְאִתְּמָר.</p>\n<p>תָּאנָא, וְשָׁכַבְתִּי עִם אֲבוֹתַי, בְּגוּפָא, בְּנַפְשָׁא, בְּרוּחָא, בְּנִשְׁמָתָא, בִּרְתִיכָא חָדָא, בְּדַרְגָא עִלָּאָה. אָמַר רִבִּי יְהוּדָה, כַּמָּה אֲטִימִין מִכֹּלָּא בְּנֵי עַלְמָא, דְּלָא יָדְעֵי, וְלָא מַשְׁגִּיחֵי, וְלָא שָׁמְעֵי, וְלָא מִסְתַּכְּלֵי בְּמִלֵּי דְעַלְמָא. וְהֵיךְ קוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּכַּח עֲלַיְיהוּ בְּרַחֲמִין, בְּכָל זְמַן וְעִידָן, וְלֵית מַאן דְּיַשְׁגַּח.</p>\n<p>תְּלַת זִמְנִין בְּיוֹמָא, עָאל רוּחָא חָדָא בִּמְעַרְתָּא דְכָפֶלְתָּא, וְנָשִׁיב בְּקִבְרֵי אֲבָהָתָא, וְאִתְסְיָין כָּל גַּרְמִין, וְקָיְימֵי בְּקִיּוּמָא, וְהַהוּא רוּחָא נָגִיד טַלָּא מִלְּעֵילָא, מֵרֵישָׁא דְמַלְכָּא, אֲתַר דְּמִשְׁתַּכְּחֵי אֲבָהָן עִלָּאֵי. וְכַד מָטֵי (ס\"א מתער) הַהוּא טַלָּא מִנַּיְיהוּ, מִתְעָרִין אֲבָהָן דִּלְתַתָּא.</p>\n<p>וְתָאנָא, נָחִית הַהוּא טַלָּא בְּדַרְגִּין יְדִיעָן, דַּרְגָּא בָּתַר דַּרְגָּא, וּמָטֵי לְגַן עֵדֶן דִּלְתַתָּא. וּמֵהַהוּא טַלָּא, אִתְסְחֵי בְּבוּסְמִין דְּגִנְתָא דְעֵדֶן. וְאִתְעַר רוּחָא חָדָא, דְּכָלִיל בִּתְרֵין אָחֳרָנִין וְסָלִיק וְשָׁאט בֵּינֵי בּוּסְמִין, וְעָיִיל בְּפִתְחָא דִמְעַרְתָּא, כְּדֵין מִתְעָרִין אֲבָהָן, אִינוּן וְזִיווּגָן, וּבְעָאן רַחֲמֵי עַל בְּנוֹי.</p>\n<p>וְכַד אִשְׁתַּכַּח עַלְמָא בְּצַעֲרָא, בְּגִין דְּאִינוּן דְּמִיכִין עַל חוֹבֵי עַלְמָא, וְהַהוּא טַלָּא לָא אִתְנְגִיד וְלָא אִשְׁתַּכַּח, עַד דְּאִתְעַר סֵפֶר תּוֹרָה, כְּדְקָא חָזֵי בְּעַלְמָא. וְנַפְשָׁא אוֹדְעָא לְרוּחָא, וְרוּחָא לְנִשְׁמָתָא, וְנִשְׁמָתָא לְקוּדְשָׁא בְּרִיךְ הוּא. כְּדֵין יָתִיב מַלְכָּא בְּכֻּרְסְיָיא דְרַחֲמֵי, וְנָגִיד מֵעַתִּיקָא קַדִּישָׁא עִלָּאָה, נְגִידוּ דְטַלָּא דְבָדוֹלְחָא. וּמָטֵי לְרִישָׁא דְמַלְכָּא, וּמִתְבָּרְכִין אֲבָהָן. וְנָגִיד הַהוּא טַלָּא, לְאִינוּן דְּמִיכִין, וּכְדֵין מִתְחַבְּרָן (נ\"א מתברכן) כֻּלְּהוּ, וְחָיִיס קוּדְשָׁא בְּרִיךְ הוּא עַל עַלְמָא. וְתָאנָא, לָא חָיִיס קוּדְשָׁא בְּרִיךְ הוּא עַל עַלְמָא, עַד דְּאוֹדַע לַאֲבָהָן וּבְגִינַיְיהוּ עַלְמָא אִתְבָּרְכָא. אָמַר רִבִּי יוֹסֵי, וַדַּאי הָכִי הוּא, וְהָא אַשְׁכַּחְנָא מִלֵּי בְּסִפְרָא דִשְׁלֹמֹה מַלְכָּא, הַהוּא עִלָּאָה, דְּקָרָא לֵיהּ עֵיטָא דְחָכְמְתָא דְכֹלָּא.</p>\n<p>וְרַב הַמְנוּנָא, הָכִי גַּלֵּי וְאָמַר, דְּהָא אַחְזִיּוּ לֵיהּ, דְּיַתִּיר עָבְדַת רָחֵל, דְּקָיְימָא בְּפָרָשַׁת אוֹרְחִין, בְּכָל זִמְנָא דְאִצְטְרִיךְ עַלְמָא, מִכֻּלְּהוּ. וְרָזָא דְמִלָּה, אָרוֹן וְכַפּוֹרֶת וּכְרוּבִים בְּחוּלְקָא דְבִנְיָמִן, דְּאִתְיְלִיד בְּאוֹרְחָא, וּשְׁכִינְתָּא עַל כֹּלָּא:</p>"],[9520011455,"<p>וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה, מַאן רֹאשׁ הַמִּטָּה. דָּא שְׁכִינְתָּא. אָמַר רַבִּי שִׁמְעוֹן, חַס וְשָׁלוֹם. אֶלָּא לְדִידֵיהּ כָּרַע וְסָגִיד. (אלא) תָּא חֲזֵי, מִטָּה, דָּא שְׁכִינְתָּא. דִּכְתִיב, (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה. רֹאשׁ הַמִּטָּה מַאן הוּא. דָּא יְסוֹדָא דְעַלְמָא, דְּהוּא רִישָׁא דְעַרְסָא קַדִּישָׁא. עַל רֹאשׁ, דָּא יִשְׂרָאֵל, דְּקָאִים עַל רֹאשׁ הַמִּטָּה. בְּגִינֵי כָּךְ, יִשְׂרָאֵל לְדִידֵיהּ קָא סָגִיד.</p>\n<p>וְאִי תֵימָא, הָא בְּהַהוּא זִמְנָא לָא הֲוָה מָרַע, דְּהָא לְבָתַר כְּתִיב, וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וַיֹּאמֶר לְיוֹסֵף הִנֵּה אָבִיךָ חוֹלֶה. וּבְשַׁעְתָּא דְּסָגִיד, לָא הֲוָה חוֹלֶה, וְעַל דְּיָדַע דְּהָא בְהַהוּא זִמְנָא, סָלִיק בְּדַרְגָא עִלָּאָה קַדִּישָׁא כֻּרְסְיָיא שְׁלֵימָתָא, בְּגִינֵי כָּךְ סָגִיד לְהַהוּא רְתִיכָא, כֻּרְסְיָיא עִלָּאָה, שְׁלִימוּ דְאִילָנָא רַבְרְבָא וְתַקִּיף, דְּאִקְרֵי עַל שְׁמֵיהּ. וְעַל דָּא, וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה, עַל רֹאשׁ הַמִּטָּה וַדַּאי, דְּהָא אִסְתַּלַּק לְאַתְרֵיהּ וְאִתְעַטַּר בְּעִטְרוֹי דְמַלְכָּא קַדִּישָׁא:</p>\n<p>וַיֹּאמֶר הִשָּׁבְעָה לִי וַיִּשָּׁבַע לוֹ וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה, רִבִּי חִיָּיא פָּתַח וְאָמַר, (קהלת ז׳:כ״ג) כָּל זֶה נִסִּיתִי בַחָכְמָה אָמַרְתִּי אֶחְכָּמָה וְהִיא רְחוֹקָה מִמֶּנִּי. הָא תָּנִינָן, שְׁלֹמֹה מַלְכָּא, יָרִית סִיהֲרָא מִכָּל סִטְרוֹי, וּבְיוֹמוֹי קָיְימָא בִּשְׁלֵמוּתָא, הַהִיא סִיהֲרָא דְּאִתְבָּרְכָא מִכֹּלָּא, וְכַד בָּעָא לְמֵיקַם עַל נִימוּסֵי אוֹרַיְיתָא. אָמַר, אָמַרְתִּי אֶחְכָּמָה וְגו'.</p>\n<p>אָמַר רִבִּי יְהוּדָה, יַעֲקֹב אָמַר, וְשָׁכַבְתִּי עִם אֲבוֹתַי וּנְשָׂאתַנִי מִמִּצְרַיִם וּקְבַרְתַּנִי בִּקְבוּרָתָם, תַּמָּן תָּנִינָן, מַאן דְּנָפַק נִשְׁמָתֵיהּ בִּרְשׁוּתָא אָחֳרָא, <Nonei></i>וְגוּפָא דִילֵיהּ אִתְקַבַּר בְּאַרְעָא קַדִּישָׁא, עֲלֵיהּ כְּתִיב, (ירמיהו ב׳:ז׳) וַתָּבֹאוּ וַתְּטַמְּאוּ אֶת אַרְצִי וְנַחֲלָתִי שַׂמְתֶּם לְתוֹעֵבָה, וְיַעֲקֹב אָמַר וּקְבַרְתַּנִי בִּקְבוּרָתָם, וְנִשְׁמָתֵיהּ נָפְקָא בִּרְשׁוּתָא אָחֳרָא.</p>\n<p>אָמַר רִבִּי יְהוּדָה, שָׁאנֵי יַעֲקֹב, דִּשְׁכִינְתָּא הֲוַת אֲחִידַת בֵּיהּ, וְאִתְדַּבְּקַת בֵּיהּ. הֲדָא הוּא דִכְתִיב, (בראשית מ״ו:ד׳) אָנֹכִי אֵרֵד עִמְּךָ מִצְרַיְמָה, לְדָיְירָא עִמָּךְ בְּגָלוּתָא. וְאָנֹכִי אֲעַלְךָ גַּם עָלה, לְאִזְדַּוְּוגָא בִּי נִשְׁמָתָךְ, וּלְאִתְקְבָרָא גּוּפָךְ בְּקִבְרֵי אֲבָהָתָךְ. מַאי קָא מַיְירֵי, (אף על גב דקא) (נ\"א דהא לא) נָפְקַת נִשְׁמָתֵיהּ בִּרְשׁוּתָא אָחֳרָא. (נ\"א ועל דא ואנכי אעלך גם עלה כתיב).</p>\n<p>וְיוֹסֵף יָשִׁית יָדוֹ עַל עֵינֶיךָ, יוֹסֵף וַדַּאי, דְּהָא הוּא בּוּכְרָא דְהִרְהוּרָא דְלִבָּא, בּוּכְרָא דְּטִפָּה קַדְמָאָה הֲוַת, כִּדְאִתְּמָר. וּבְגִין דְּיָדַע קוּדְשָׁא בְּרִיךְ הוּא טְמִירָא דָא, אִתְבַּשַּׂר לֵיהּ בְּיוֹסֵף, דְּהָא כָּל רְחִימוּתָא בֵּיהּ תַּלְיָא.</p>\n<p>יָשִׁית יָדוֹ עַל עֵינֶיךָ. מַאי קָא מַיְירֵי. אָמַר רִבִּי יֵיסָא, בְּגִין יְקָרָא דְיַעֲקֹב, וּלְאִתְבַּשְּׂרָא דְּהָא יוֹסֵף קַיָּים, וְיִשְׁתַּכַּח עֲלֵיהּ בְּמִיתָתֵיהּ. רִבִּי חִזְקִיָּה אָמַר, מִלָּה אוֹלִיפְנָא, וְדָחִילְנָא לְגַלָּאָה, וּבְעוֹבָדֵי עַלְמָא חָכְמְתָא אִשְׁתַּכַּח. אֲתָא רִבִּי אַבָּא, (ד\"א ל\"ג ונשקיה) בָּטַשׁ בֵּיהּ. אָמַר, אֵימָא מִילָךְ, וְזַיֵּין זַיְינָךְ. בְּיוֹמוֹי דְּרִבִּי שִׁמְעוֹן מִלִּין אִתְגַּלְּיָין.</p>\n<p>אָמַר, אוֹלִיפְנָא מִפִּרְקִין דְּרַב יֵיסָא סָבָא, בְּנִמּוּסֵי עַלְמָא. בַּר נָשׁ דְּזָכֵי לְבַר בְּהַאי עַלְמָא, לִיבָּעֵי לֵיהּ לְנַגְדָּא עַפְרָא עַל עֵינוֹי כַּד אִתְקַבַּר, וְדָא הוּא יְקָרָא דִילֵיהּ, לְאַחֲזָאָה דְעַלְמָא אַסְתִּים מִנֵּיהּ, וְהוּא יָרִית לֵיהּ לְעַלְמָא תְּחוֹתוֹי.</p>\n<p>בְּגִין דְּעֵינוֹי דְבַר נָשׁ, חֵיזוּ דְעַלְמָא בֵּיהּ אִתְחֲזֵי, וְכָל גְּוָונִין הָכִי אִינוּן דְּאַסְחָרוּ. חִוָּורָא דְבֵיהּ, הוּא יַמָּא רַבָּא אוֹקְיָנוֹס, דְּאַסְחַר כָּל עַלְמָא בְּכָל סִטְרֵי. גּווָֹנָא אָחֳרָא הוּא יַבֶּשְׁתָּא (דאקיפו), דְּאֲפִיקוּ מַיָא, וְיַבֶּשְׁתָּא קָאִים בֵּין מַיָא, הָכִי הוּא גּווָֹנָא בֵּין מַיָא.</p>\n<p>גּווָֹנָא אָחֳרָא תְּלִיתָאָה, הִיא בִּמְצִיעוּתָא דְבֵיהּ, דָּא יְרוּשָׁלַ ם, דְּהִיא אֶמְצָעוּתָא דְעַלְמָא. גּווָֹנָא רְבִיעָאָה, הִיא חֵיזוּ דְּכָל עֵינָא, וְאִקְרֵי בַּת עַיִן, דִּבְהַהוּא בַּת עַיִן, אִתְחֲזֵי פַּרְצוּפָא. וְחֵיזוּ יְקָרָא מִכֹּלָּא, דָּא צִיּוֹן, דְּאִיהִי נְקוּדָה אֶמְצָעוּתָא מִכֹּלָּא, דְּחֵיזוּ דְּכָל עַלְמָא תַּמָּן אִתְחֲזֵי. וְתַמָּן שַׁרְיָא שְׁכִינְתָּא, דְּהִיא שַׁפִּירוּ דְּכֹלָּא, וְחֵיזוּ דְּכֹלָּא, וְעֵינָא דָא הוּא יְרוּתַת עַלְמָא. וּבְגִינֵי כָּךְ, הַאי שָׁבִיק לֵיהּ, וְהַאי נָטִיל לֵיהּ, וְיָרִית לֵיהּ.</p>\n<p>אָמַר לֵיהּ, שַׁפִּיר קָאֲמַרְתְּ, אֲבָל מִלָּה סְתִימָא אִיהוּ יַתִּיר, וּבְנֵי עַלְמָא לָא יָדְעִין, וְלָא מִסְתַּכְּלָן, דְּהָא בְּשַׁעְתָּא דְּבַר נָשׁ נָפִיק מֵעַלְמָא. נַפְשָׁא דִילֵיהּ טְמִירָא עִמֵּיהּ, וְעַד לָא נָפְקַת, עֵינוֹי דְבַּר נָשׁ חָמוּ מַה דְּחָמוּ, כְּמָה דְאוֹקִימְנָא דִּכְתִיב, (שמות ל״ג:כ׳) כִּי לא יִרְאַנִי הָאָדָם וָחָי. בְּחַיֵּיהוֹן לָא חָמָאן, אֲבָל בְּמִיתַתְהוֹן חָמָאן.</p>\n<p>וְעֵינוֹי פְּקִיחָן מֵהַהוּא חֵיזוּ דְּחָמָא, וְאִינוּן דְּקָיְימִין עֲלֵיהּ, בָּעָא לְשַׁוְאָה יָדָא עַל עֵינוֹי, וּלְאַסְתָּמָא עֵינוֹי, בְּגִין הַהוּא דְּאוֹלִיפְנָא בְּרָזָא דְנִמּוּסֵי עַלְמָא. דִּבְשַׁעְתָּא דְאִשְׁתָּאֲרוּ עֵינוֹי פְּקִיחָן, מֵהַהוּא חֵיזוּ יַקִּירָא דְחָמָא. אִי זָכֵי לְבַר, בְּרָא קָדִים לְשַׁוְאָה יָדֵיהּ עַל עֵינוֹי וּלְאַסְתָּמָא לוֹן, כְּמָה דִכְתִיב וְיוֹסֵף יָשִׁית יָדוֹ עַל עֵינֶיךָ. בְּגִין דְּהָא חֵיזוּ אָחֳרָא דְּלָא קַדִּישָׁא אִזְדַּמְּנַת לְקֳבְלֵיהּ, וְעֵינָא דְחָמָא הַשְׁתָּא חֵיזוּ קַדִּישָׁא עִלָּאָה, לָא יִסְתַּכַּל בְּחֵיזוּ אָחֳרָא.</p>\n<p>וְעוֹד, דְּהַהוּא נֶפֶשׁ סְמִיכַת לְקֳבְלֵיהּ בְּבֵיתָא, וְאִי אִשְׁתָּאַר עֵינָא פְּקִיחָא, וְהַהוּא חֵיזוּ אָחֳרָא יִשְׁרֵי עַל עֵינוֹי, בְּכָל מַה דְּאִסְתַּכַּל אִתְלַטְיָא, וְלָאו יְקָרָא דְעֵינָא הוּא, וְכָל שֶׁכֵּן מִקְרִיבוֹי, וְכָל שֶׁכֵּן מִן מִיתָא, דְּלָאו יְקָרָא דִילֵיהּ לְאִסְתַּכָּלָא בַּמֶּה דְלָא אִצְטְרִיךְ, וּלְאַשְׁרַיָא עַל עֵינוֹי מִלָּה אָחֳרָא. לְבָתַר אִתְכַּסְיָא בְּעַפְרָא, וְהָא אִתְעָרוּ חַבְרַיָא עַל דִּינָא דְקִבְרָא מַהוּ. וִיקָרָא הוּא, דְּיַסְתִּים עֵינָא מִן כֹּלָּא, עַל יְדָא דִבְרֵיהּ דְּשָׁבַק בְּעַלְמָא.</p>\n<p>תָּא חֲזֵי, כָּל שִׁבְעָה יוֹמִין, נַפְשָׁא אָזְלָא מִבֵּיתָא לְקִבְרָא, וּמִקִּבְרָא לְבֵיתָא, וְאִתְאַבָּלַת עֲלֵיהּ, וּתְלַת זִמְנִין בְּיוֹמָא, אִתְדָּנוּ כְּחֲדָא נַפְשָׁא וְגוּפָא, וְלֵית מַאן דְּיָדַע בְּעַלְמָא, וְיַשְׁגַּח לְאַתְעָרָא לִבָּא.</p>\n<p>לְבָתַר, גּוּפָא אִתְטְרִיד, וְנַפְשָׁא אָזְלָא וְאִסְּתַחְיָא <Nonei></i>בַּגֵּיהִנָּם, וְנָפְקָא וְשָׁטָא בְּעַלְמָא, וּמְבַקְרָא לְקִבְרֵיהּ, עַד דְּמִתְלַבְּשָׁא בְּמָּה דְּאִתְלַבְּשָׁא.</p>\n<p>לְבָתַר תְּרֵיסַר יַרְחֵי, נָיְיחִין כֹּלָּא. גּוּפָא שָׁבִיק (שכיך) בְּעַפְרָא. נַפְשָׁא אִתְצְרֵיר וְאִתְנְהִיר בְּרוּחָא, בְּמָאנָא דְּאִתְלָבַּשׁ. רוּחָא אִתְעַנַּג בְּגִנְתָא דְעֵדֶן. נִשְׁמָתָא סָלְקָא לִצְרוֹרָא דְעִנּוּגָא דְּכָל עִנּוּגִין. וְכֹלָּא אִתְקַשַּׁר דָּא בְּדָא לְזִמְנִין יְדִיעָן.</p>\n<p>תָּא חֲזֵי, וַוי לוֹן לִבְנֵי נָשָׁא, דְּלָא מִסְתַּכְּלִין וְלָא יָדְעִין וְלָא אִשְׁתְּמוֹדְעָן, עַל מַה קָיְימֵי, וְיִתְנְשֵׁי מִנַּיְיהוּ לְמֶעְבַּד פִּקּוּדֵי אוֹרַיְיתָא. דְּאִית פִּקּוּדֵי אוֹרַיְיתָא דְּעָבְדֵי לְבוּשׁ יְקָר לְעֵילָא. וְאִית פִּקּוּדֵי אוֹרַיְיתָא דְּעָבְדֵי לְבוּשׁ יְקָר לְתַתָּא. וְאִית פִּקּוּדֵי אוֹרַיְיתָא דְּעָבְדֵי לְבוּשֵׁי יְקָר לְהַאי עַלְמָא. וְכֹלָּא אִצְטְרִיכָן לֵיהּ לְבַּר נָשׁ, וּמִן יוֹמוֹי מַמָּשׁ, כֻּלְּהוּ מִתְתַּקְנָן, כְּמָה דְאוֹקִימְנָא.</p>\n<p>רִבִּי יְהוּדָה סָבָא, אִתְרַגִּישׁ בְּדַעְתֵּיהּ יוֹמָא חַד, וְאַחֲזוּ לֵיהּ בְּחֶלְמֵיהּ, חַד דִּיוּקְנָא מִנְּהוֹרָא דִּילֵיהּ, תַּקִּיף, דְּאִזְדְּהַר לְאַרְבַּע סִטְרִין, אָמַר לֵיהּ, מַאי הַאי. אָמַר לֵיהּ, לְבוּשָׁא דִילָךְ הוּא, לְדִיּוּרָא דְהָכָא, וּמֵהַהוּא יוֹמָא הֲוָה חָדֵי.</p>\n<p>אָמַר רִבִּי יְהוּדָה, כָּל יוֹמָא וְיוֹמָא, רוּחִין דְּצַדִּיקַיָיא יָתְבִין בִּלְבוּשֵׁיהוֹן, שׁוּרִין שׁוּרִין בְּגִנְתָא דְעֵדֶן, וּמְשַׁבְּחָן לְקוּדְשָׁא בְּרִיךְ הוּא, בִּיקָרָא עִלָּאָה. הֲדָא הוּא דִכְתִיב, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ. אָמַר רִבִּי אַבָּא, בְּקַדְמִיתָא מַה כְּתִיב וַיִּשְׁתַּחוּ יִשְׂרָאֵל וְגו', כְּמָה דְאוֹקִימְנָא, מַאן מִטָּה, דָּא כְּנֶסֶת יִשְׂרָאֵל. רֹאשׁ הַמִּטָּה, דָּא צַדִּיק. עַל רֹאשׁ הַמִּטָּה, דָּא מַלְכָּא קַדִּישָׁא, דִּשְׁלָמָא כֹּלָּה דִילֵיהּ, כְּמָה דִכְתִיב (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה. דְּיַעֲקֹב לְדִידֵיהּ קָא סָגִיד, לְהַהוּא דְקָאִים עַל רֹאשׁ הַמִּטָּה, יִשְׂרָאֵל שְׁמֵיהּ, בְּגִינִי כָּךְ, וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה.</p>\n<p>לְבָתַר, כֵּיוָן דְּיָדַע יַעֲקֹב, דְּהָא בְּדַרְגָּא עִלָּאָה אִשְׁתְּלִים, וְדַרְגָּא דִילֵיהּ הוּא לְעֵילָא עִם אֲבָהָתָא, וְהוּא בִּלְחוֹדוֹי תִּקּוּנָא שְׁלֵימָתָא, אַחְסִין לִבֵּיהּ, וְחָדֵי וְאִתְתַּקַּף בִּרְעוּתָא עִלָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ. מַה כְּתִיב בֵּיהּ, וַיִּתְחַזֵּק יִשְׂרָאֵל וַיֵּשֶׁב עַל הַמִּטָּה, עַל הַמִּטָּה מַמָּשׁ, דְּהָא בְּדַרְגָּא עִלָּאָה יַתִּיר אִשְׁתָּלַּם, זַכָּאָה חוּלָקֵיהּ.</p>"],[9520011456,"<p>תָּאנָא, אָמַר רִבִּי יְהוּדָה, בְּמַתְנִיתָּא דִילָן אוֹקִימְנָא, הָא דְּתָנִינָן בְּאַרְבָּעָה פְּרָקִים בַּשָּׁנָה הָעוֹלָם נִדּוֹן, בַּפֶּסַח עַל הַתְּבוּאָה, בַּעֲצֶרֶת עַל פֵּירוֹת הָאִילָן, בְּרֹאשׁ הַשָּׁנָה כָּל בָּאֵי הָעוֹלָם עוֹבְרִים לְפָנָיו כִּבְנֵי מְרוֹן, וּבַחַג נִדּוֹנִין עַל הַמַּיִם, הָא אוֹקִימְנָא מִלֵּי. וְרָזָא דְמַתְנִיתָּא אוֹקִימְנָא, בְּפֶסַח עַל הַתְּבוּאָה וְכוּ', לָקֳבֵיל רְתִיכָא עִלָּאָה, רָזָא דְּאֲבָהָן, וְדָוִד מַלְכָּא. בְּפֶסַח עַל הַתְּבוּאָה, דְּהָכִי הוּא מַמָּשׁ, וְהָא אוֹקִימְנָא מִלָּה דָא, עַל מָה אַתְיָיא מַצָּה בְּפֶסַח, וְהָא דִינָא הוּא, דִּינָא דְמַלְכוּתָא דִינָא, וְדָא שֵׁירוּתָא דְּשָׁרִיאוּ יִשְׂרָאֵל לְמֵיעַל בְּחוּלָקָא קַדִּישָׁא דְקוּדְשָׁא בְּרִיךְ הוּא, וּלְבַעֲרָא מִנַּיְיהוּ חָמֵץ, דְּאִיהוּ טַעֲוָון אָחֳרָנִין דִּי מְמַנָּן עַל עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת דְּאִקְרוּן אֱלֹהִים אֲחֵרִים, אֱלהֵי נִכָר. וְאִקְרוּן חָמֵץ, יֵצֶר הָרָע, וּלְמֵיעַל בְּמַצָּה, חוּלָקָא קַדִּישָׁא דְקוּדְשָׁא בְּרִיךְ הוּא אַמַּאי תְּבוּאָה. (ס\"א ל\"ג כמה דאת אמר, (ירמיה ב) תבואתה בה\"א, רמיז לה\"א קדמאה דשמא קדישא) בְּגִין כָּךְ, בְּפֶסַח נִדּוֹנִין עַל הַתְּבוּאָה, וְאוֹקִימְנָא דְּעַלְמָא אִתְדָּן עַל דִּינָא דְה\"א.</p>\n<p>בַּעֲצֶרֶת עַל פֵּירוֹת הָאִילָן. פֵּירוֹת הָאִילָן, פֵּירוֹת הָאִילָנוֹת מִבָּעֵי לֵיהּ, מַאן פֵּירוֹת הָאִילָן. אֶלָּא, דָּא הוּא אִילָנָא רַבְרְבָא וְתַקִּיף לְעֵילָא. פֵּירוֹת הָאִילָן, כְּמָה דִכְתִיב, (הושע י״ד:ט׳) אֲנִי כִּבְרוֹשׁ רַעֲנָן מִמֶּנִּי פֶּרְיְךָ נִמְצָא.</p>\n<p>בְּרֹאשׁ הַשָּׁנָה עוֹבְרִין לְפָנָיו כִּבְנֵי מָרוֹן. תָּנָא רֹאשׁ הַשָּׁנָה, דָּא הוּא רֵישָׁא דְשַׁתָּא דְמַלְכָּא, וּמַאן הוּא רֹאשׁ הַשָּׁנָה, דָּא יִצְחָק, דְּאִקְרֵי רֹאשׁ, דְּאִיהוּ חַד רֵישָׁא דְמַלְכָּא (נ\"א לעילא), אֲתַר דְּאִקְרֵי שָׁנָה. בְּגִינֵי כָּךְ כָּל בָּאֵי עוֹלָם עוֹבְרִין לְפָנָיו כִּבְנֵי מָרוֹן. וְעַל דָּא תָּנִינָן, בְּרֹאשׁ הַשָּׁנָה, דְּהָא בְּרֵישָׁא דְשַׁתָּא שָׁארֵי יִצְחָק.</p>\n<p>וּבַחַג נִדּוֹנִין עַל הַמַּיִם, דָּא הוּא שֵׁירוּתָא (דרישא) דִּימִינָא דְּמַלְכָּא, וְעַל דָּא חֶדְוָותָא דְמַיָא אִשְׁתַּכַּח בְּכֹלָּא, בְּשַׁעְתָּא דְּנָסְכֵי מַיָא, וְשָׁאֲבֵי לוֹן, בְּגִין דְּמַיִם דָּא יְדִיעָא. וְעַל דָּא בְּאַרְבָּעָה פְּרָקִים אִלֵּין, כֹּלָּא מִשְׁתַּכְּחִין.</p>\n<p><Nonei></i>אָמַר רִבִּי יוֹסֵי, כַּד יִסְתַּכְּלוּן מִלֵּי, כֹּלָּא אִשְׁתַּכַּח בְּהַנִּי פִּרְקִין, אַבְרָהָם יִצְחָק וְיַעֲקֹב, דָּוִד מַלְכָּא. וּבְהַנִּי עַלְמָא אִתְדָּן, וּבְאַרְבַּע פְּרָקִין בְּנֵי נָשָׁא אִתְדָּנוּ, בְּיוֹמִין דְּאִשְׁתַּכָּחוּ בְּעַלְמָא. וּבְכָל יוֹמָא וְיוֹמָא, סִפְרִין פְּתִיחָן וְעוֹבָדִין כְּתִיבִין, וְלֵית מַאן דְּיַשְׁגַּח, וְלֵית מַאן דְּיַרְכִין אוּדְנֵיהּ, וְאוֹרַיְיתָא אַסְהִידַת בֵּיהּ בְּכָל יוֹמָא, וְקָלָא קָרֵי בְחֵילָא, (משלי ט׳:ד׳) מִי פֶּתִי יָסוּר הֵנָּה חֲסַר לֵב אָמְרָה לוֹ, וְלֵית מַאן דְּיָצִית לְקָלֵיהּ.</p>\n<p>תָּאנָא בְּשַׁעְתָּא דְּבַר נָשׁ קָאִים בְּצַפְרָא, סָהֲדִין קָיְימִין לְקֳבְלֵיהּ, וְסָהֲדִין בֵּיהּ, וְהוּא לָא אַשְׁגַּח. נִשְׁמָתָא אַסְהִידַת עֲלֵיהּ, בְּכָל עִדָּן וּבְכָל שַׁעְתָּא, אִי אָצִית יָאוֹת. וְאִי לָאו, הָא סִפְרִין פְּתִיחִין וְעוֹבָדִין כְּתִיבִין. אָמַר רִבִּי חִיָּיא, זַכָּאִין אִינוּן צַדִּיקַיָיא, דְּלָא מִסְתָּפוּ מִן דִּינָא, לָא בְּעַלְמָא דֵין, וְלָא בְּעַלְמָא דְאָתֵי. הֲדָא הוּא דִכְתִיב, (משלי כ״ח:א׳) וְצַדִּיקִים כִּכְפִיר יִבְטָח. וּכְתִיב, (תהילים ל״ז:כ״ט) צַדִּיקִים יִירְשׁוּ אָרֶץ.</p>"]]});
